INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-001', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'easy', 'Compass deviation is the angle between', '["true north and magnetic north", "grid north and true north", "aircraft heading and track", "magnetic north and compass north"]'::jsonb, 3, 'Deviation is the angle between magnetic north and compass north, produced by magnetic influences within the aircraft.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-002', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'A constant deviation on every heading is normally represented by which coefficient''', '["Coefficient C", "Coefficient A", "Coefficient D", "Coefficient B"]'::jsonb, 1, 'Coefficient A is the constant term and commonly represents a displaced lubber line or detector alignment error.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-003', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'hard', 'Earth convergency is best defined as', '["the distance between two meridians along a parallel", "the angle of inclination between selected meridians at a stated latitude", "half the difference between two rhumb-line tracks", "the angle between true and magnetic north"]'::jsonb, 1, 'Earth convergency is the angle of inclination between two selected meridians measured at a stated latitude.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-004', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'easy', 'Two meridians are 40 degrees apart at latitude 30 degrees north. Their convergency is', '["10 degrees", "30 degrees", "40 degrees", "20 degrees"]'::jsonb, 3, 'Convergency = 40 × sin 30 degrees = 20 degrees.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-005', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'The direction in which the longitudinal axis of an aircraft points is its', '["track", "drift", "heading", "groundspeed"]'::jsonb, 2, 'Heading is the direction in which the aircraft''s longitudinal axis points.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-006', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'hard', 'The direction of the path actually followed over the Earth''s surface is the', '["track", "heading", "wind direction", "true airspeed"]'::jsonb, 0, 'Track is the direction of the aircraft''s actual path over the Earth''s surface.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-007', 'air-navigation', 'air-navigation-departure', 'Departure', 'easy', 'What is departure in navigation''', '["The north-south distance between parallels", "The angular difference between two meridians", "The east-west distance between meridians along a stated parallel", "The shortest great-circle distance between two positions"]'::jsonb, 2, 'Departure is the east-west distance between two meridians measured along a specified parallel of latitude.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-008', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'Two meridians differ by 20 degrees at latitude 52 degrees. What is the departure''', '["About 739 NM", "About 1,200 NM", "About 616 NM", "About 400 NM"]'::jsonb, 0, 'Departure = 1,200 minutes × cos 52 degrees = 738.8 NM, which is about 739 NM.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-009', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'hard', 'In the red and blue pole convention, the Earth behaves as if which polarity lies in the northern magnetic region''', '["A blue pole", "A red pole", "Two red poles", "No magnetic pole"]'::jsonb, 0, 'The northern magnetic region behaves as a blue polarity, which attracts the red north-seeking end of a compass magnet.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-010', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'easy', 'Magnetic variation is the angle between', '["compass north and aircraft heading", "magnetic north and compass north", "true north and magnetic north", "the horizontal and the total magnetic field"]'::jsonb, 2, 'Variation is the horizontal angle between true north and magnetic north at a stated place and time.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-011', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'In chart projection, the reduced Earth is', '["the area omitted from a chart", "a mathematically flattened hemisphere", "a scale model of the Earth used as the projection basis", "the part of the globe below the equator"]'::jsonb, 2, 'The reduced Earth is the scale model of the globe on which the projection is based.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-012', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'hard', 'The three general developable projection surfaces are', '["plane, cylinder and cone", "sphere, ellipse and plane", "Mercator, Lambert and gnomonic", "tangent, secant and orthomorphic"]'::jsonb, 0, 'The three general families use a plane, a cylinder or a cone as the developable surface.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-013', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'easy', 'Which description defines a great circle''', '["Any circle drawn on the Earth''s surface", "A surface circle whose plane passes through the Earth''s centre", "Any parallel of latitude", "A route that keeps a constant direction"]'::jsonb, 1, 'A great circle has the same centre and radius as the Earth because its plane passes through the Earth''s centre.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-014', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'What is the defining property of a rhumb line''', '["It always passes through both poles", "It is always the shortest surface route", "It has two vertices", "It cuts every meridian at the same angle"]'::jsonb, 3, 'A rhumb line cuts every meridian at the same angle, which makes it a line of constant direction.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-015', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'hard', 'Two checkpoints are 20 NM apart and elapsed time is 8 minutes. Measured groundspeed is', '["120 kt", "135 kt", "160 kt", "150 kt"]'::jsonb, 3, 'Groundspeed is 20 multiplied by 60 divided by 8, which gives 150 kt.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-016', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'easy', 'An aircraft passes A at 1010 and B, 30 NM farther, at 1027. If 20 NM remains, revised ETA is approximately', '["1038", "1035", "1040", "1045"]'::jsonb, 0, 'The measured 30 NM took 17 minutes, so the remaining 20 NM takes about 11 minutes and ETA is about 1038.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-017', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'The principal navigation advantages sought in a Lambert conformal chart are', '["straight rhumb lines and true area", "constant scale at every point and straight meridians", "a visible geographic pole and equal area", "near constant scale and nearly straight great-circle routes"]'::jsonb, 3, 'Lambert was designed to give near constant scale and make a straight chart line a close approximation to a great circle.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-018', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'hard', 'On a simple conic projection, scale is correct at', '["the parallel of tangency", "the equator only", "every meridian", "the pole of projection"]'::jsonb, 0, 'The simple cone touches the reduced Earth at its parallel of tangency, so scale is correct there.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-019', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'easy', 'For practical aviation use, a chart may be treated as constant scale when its scale distortion does not exceed about', '["4 percent", "2 percent", "1 percent", "0.01 percent"]'::jsonb, 2, 'A Lambert sheet is treated as practically constant scale when its distortion remains within about 1 percent.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-020', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'A Lambert chart whose standard parallels are 16 degrees apart has an approximate maximum scale error of', '["0.1 percent", "1 percent", "2 percent", "4 percent"]'::jsonb, 1, 'Oxford''s guide gives about 1 percent maximum scale error for 16 degrees of standard-parallel separation.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-021', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'hard', 'A normal Mercator chart is correctly described as', '["a perspective conical equal-area projection", "a non-perspective conformal cylindrical projection", "a perspective polar projection", "a non-conformal plane projection"]'::jsonb, 1, 'The normal Mercator is cylindrical, mathematically modified and conformal, so it is non-perspective.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-022', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'easy', 'The graticule of a direct Mercator chart is', '["circular", "convergent", "radial", "rectangular"]'::jsonb, 3, 'Parallel straight meridians and parallel straight latitudes form a rectangular Mercator graticule.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-023', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'The scale at latitude L on a normal Mercator is', '["equatorial scale multiplied by sec L", "equatorial scale multiplied by cos L", "equatorial scale divided by tan L", "constant at every latitude"]'::jsonb, 0, 'Mercator scale at latitude L is the equatorial scale multiplied by secant L.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-024', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'hard', 'A Mercator has scale 1:1,000,000 at the equator. Its scale at 60 degrees north is', '["1:2,000,000", "1:1,000,000", "1:500,000", "1:250,000"]'::jsonb, 2, 'Secant 60 degrees is 2, so the scale doubles and the RF becomes 1:500,000.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-025', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'easy', 'Two aircraft 460 NM apart fly directly towards each other at groundspeeds of 250 kt and 210 kt. Their closing speed is', '["40 kt", "250 kt", "460 kt", "210 kt"]'::jsonb, 2, 'For head-on motion the groundspeeds add, giving a closing speed of 460 kt.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-026', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'An aircraft at 220 kt is 80 NM behind traffic at 180 kt on the same track. Time to overtake is', '["2 hours", "1 hour", "3 hours", "4 hours"]'::jsonb, 0, 'Relative closing speed is 40 kt, so 80 NM divided by 40 kt gives 2 hours.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-027', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'hard', 'An aircraft is 4 NM left of track after 30 NM. Its approximate track error is', '["8 degrees left", "4 degrees left", "8 degrees right", "13 degrees left"]'::jsonb, 0, 'Track error is 60 multiplied by 4 divided by 30, which gives 8 degrees left.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-028', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'easy', 'A 78 NM leg has 30 NM gone and a fix 4 NM left of track. What is the closing angle to destination''', '["8 degrees", "13 degrees", "5 degrees", "3 degrees"]'::jsonb, 2, 'Distance to go is 48 NM, so closing angle is 60 multiplied by 4 divided by 48, or 5 degrees.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-029', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'At 2 NM on a 3.5 degree glidepath, the approximate height above the touchdown reference is', '["350 ft", "600 ft", "700 ft", "1050 ft"]'::jsonb, 2, 'Height is 100 multiplied by 3.5 multiplied by 2, which gives 700 ft.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-030', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'hard', 'At 4 NM on a 2.6 degree glidepath, the approximate height is', '["1040 ft", "780 ft", "1200 ft", "650 ft"]'::jsonb, 0, 'Height is 100 multiplied by 2.6 multiplied by 4, which gives 1040 ft.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-031', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'easy', 'A position line is best described as', '["a line of constant heading", "a line somewhere along which the aircraft is known to be at a stated time", "the line joining two planned waypoints", "a line of constant groundspeed"]'::jsonb, 1, 'A position line is a line somewhere along which the aircraft is known to be at the observation time.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-032', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'Fixes at 1700 and 1730 are 100 NM apart. The measured groundspeed is', '["150 kt", "180 kt", "240 kt", "200 kt"]'::jsonb, 3, 'One hundred nautical miles in 30 minutes is 200 kt.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-033', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'hard', 'For a North Polar stereographic chart, the plane touches the North Pole and the projection point is at', '["the Earth''s centre", "the equator", "the North Pole", "the South Pole"]'::jsonb, 3, 'A North Polar stereographic is projected from the diametrically opposite South Pole onto a plane tangent at the North Pole.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-034', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'easy', 'The co-latitude of 70 degrees north is', '["70 degrees", "10 degrees", "20 degrees", "160 degrees"]'::jsonb, 2, 'Co-latitude equals 90 minus latitude, so 90 minus 70 gives 20 degrees.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-035', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'Chart scale is the relationship between', '["longitude and departure", "chart area and Earth area", "latitude spacing and longitude spacing", "a chart length and the corresponding Earth distance"]'::jsonb, 3, 'Scale relates a measured chart length to the corresponding distance between the same positions on Earth.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-036', 'air-navigation', 'air-navigation-scale', 'Scale', 'hard', 'Which set gives the three common methods of expressing scale''', '["Statement in words, graduated scale line, representative fraction", "Latitude, longitude, departure", "Large, medium, small", "Metric, imperial, angular"]'::jsonb, 0, 'Scale is commonly expressed by a word statement, a graduated scale line or a representative fraction.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-037', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'easy', 'Pressure altitude is the altitude indicated when the altimeter subscale is set to', '["local QFE", "regional QNH", "standard temperature", "1013.25 hPa"]'::jsonb, 3, 'Pressure altitude is read with the standard pressure setting of 1013.25 hPa on the subscale.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-038', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'Calibrated airspeed is obtained by correcting IAS for', '["density error only", "position or pressure error", "compressibility only", "temperature error only"]'::jsonb, 1, 'CAS is IAS corrected for position or pressure error; the aircraft card may combine this with instrument correction.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-039', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'hard', 'After 60 NM an aircraft is 7 NM left of planned track. Its track error is approximately', '["4 degrees left", "7 degrees left", "7 degrees right", "12 degrees left"]'::jsonb, 1, 'At the 60 NM reference distance, 7 NM off represents approximately 7 degrees left.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-040', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'easy', 'After travelling 120 NM from an on-track fix, an aircraft is 8 NM right of track. The track error is', '["8 degrees right", "2 degrees right", "4 degrees left", "4 degrees right"]'::jsonb, 3, 'Sixty multiplied by 8 divided by 120 gives a track error of 4 degrees right.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-041', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'For navigation calculations, what is the Earth''s approximate compression''', '["3 per cent", "0.03 per cent", "0.3 per cent, about 1 in 300", "1 in 3000"]'::jsonb, 2, 'The working compression is about 0.3 per cent, which is approximately 1 in 300; Bali gives the more exact ratio near 1 in 297.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-042', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'hard', 'What does the term graticule describe''', '["Every line printed on a chart", "The network of meridians and parallels on a globe, map or chart", "Only the small circles near a pole", "A magnetic compass correction card"]'::jsonb, 1, 'The graticule is the network formed by meridians and parallels, including the prime meridian and equator as its reference lines.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-043', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'easy', 'The measurement of a day is based primarily on Earth''s', '["distance from the Moon", "magnetic field", "rotation about its axis", "diameter at the equator"]'::jsonb, 2, 'A day is defined from Earth''s rotation measured against the Sun or a distant star.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-044', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'Perihelion normally occurs in', '["early January", "late March", "early July", "late September"]'::jsonb, 0, 'Earth is nearest the Sun at perihelion in early January.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-045', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'hard', 'An arc of 153 degrees 30 minutes is equivalent to approximately', '["10 hours 24 minutes", "10 hours 22 minutes", "10 hours 08 minutes", "10 hours 14 minutes"]'::jsonb, 3, 'At 15 degrees per hour, 153 degrees 30 minutes converts to 10 hours 14 minutes.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-046', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'easy', 'To find LMT from UTC at an easterly longitude, the longitude expressed as time is', '["subtracted twice", "added", "ignored", "always rounded to a whole hour"]'::jsonb, 1, 'East longitude is ahead of UTC, so its arc time is added to UTC to obtain LMT.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-047', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'On 21 June, the lowest listed northerly latitude at which the Sun remains above the horizon all day is', '["64 degrees north", "66 degrees north", "68 degrees north", "70 degrees north"]'::jsonb, 1, 'The Air Almanac question gives 66 degrees north as the lowest listed latitude with continuous daylight on 21 June.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-048', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'hard', 'On 21 December, the lowest listed northerly latitude at which the Sun does not rise is', '["64 degrees north", "66 degrees north", "68 degrees north", "70 degrees north"]'::jsonb, 2, 'The Air Almanac question gives 68 degrees north as the lowest listed latitude at which the Sun does not rise on 21 December.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-049', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'easy', 'Which of these chart scales normally gives the greater ground detail''', '["1:2,000,000", "1:500,000", "1:1,000,000", "1:5,000,000"]'::jsonb, 1, 'The 1:500,000 chart is the larger scale among these choices and normally shows more ground detail.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-050', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'On a contour chart, very closely spaced contours indicate', '["a steep slope", "a gentle slope", "flat ground at sea level", "an unknown contour interval"]'::jsonb, 0, 'A steep slope produces a large elevation change over a short horizontal distance, so its contours lie close together.', 'R.K. Bali Air Navigation / Oxford ATPL Gen Nav, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-001', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'easy', 'Which surveillance system can detect a reflecting aircraft without an airborne transponder''', '["ADS-B", "SSR", "PSR", "MLAT"]'::jsonb, 2, 'PSR detects reflected radio energy and therefore does not require an airborne transponder.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-002', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What determines when ADS-C sends a normal surveillance report''', '["The terms and triggers in the ground-held contract", "A broadcast request from every nearby aircraft", "Only the pilot pressing IDENT", "The rotation rate of a radar antenna"]'::jsonb, 0, 'ADS-C reports according to the periodic, event or demand conditions defined in its ground-held contract.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-003', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'hard', 'What is the sole objective of an Annex 13 safety investigation''', '["To decide compensation", "To apportion commercial liability", "To prosecute the flight crew", "To prevent future accidents and incidents"]'::jsonb, 3, 'The sole objective is prevention of future accidents and incidents, not apportionment of blame or liability.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-004', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'easy', 'When does an injury count as fatal under Bali''s national accident definition''', '["Only when death is immediate", "When it causes death within 30 days of the accident", "Within one year", "Within seven days"]'::jsonb, 1, 'Bali treats an accident injury as fatal when death occurs within 30 days of the accident date.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-005', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'Which working position normally controls traffic on the manoeuvring area except runways''', '["Clearance delivery", "Ground controller", "Approach control", "Aerodrome controller"]'::jsonb, 1, 'The ground controller normally controls manoeuvring-area traffic except the runways.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-006', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'hard', 'During low-visibility procedures, how should vehicle and person movements on the manoeuvring area be managed''', '["They may move without clearance", "Only aircraft movements are restricted", "Everyone must leave the aerodrome", "They are restricted to the essential minimum and ILS sensitive areas are protected"]'::jsonb, 3, 'Low-visibility procedures restrict persons and vehicles to the essential minimum and protect ILS critical and sensitive areas.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-007', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'easy', 'What display identifies a land-aerodrome identification beacon''', '["Green Morse-code characters", "Flashing red hazard lights", "Steady blue light", "Alternating red and yellow"]'::jsonb, 0, 'A land-aerodrome identification beacon flashes green characters in International Morse Code.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-008', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'What distinguishes the inner 300 m of a precision category II or III approach-light system''', '["Blue edge lights only", "One green crossbar", "No centre-line lights", "White centre-line barrettes with red side-row barrettes"]'::jsonb, 3, 'The inner 300 m is strengthened by white centre-line barrettes and red side-row barrettes.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-009', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'hard', 'Which area includes the manoeuvring area and aprons''', '["Movement area", "Runway strip", "RESA", "Clearway"]'::jsonb, 0, 'The movement area includes the manoeuvring area, aprons and relevant aircraft-maintenance movement areas.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-010', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'easy', 'What determines aerodrome reference-code element 2''', '["Reference field length only", "Runway slope and elevation", "Wingspan and outer main gear wheel span", "Pavement strength"]'::jsonb, 2, 'Element 2 is the letter determined from wingspan and outer main gear wheel span.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-011', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'Which ICAO Annex contains the Standards and Recommended Practices for aeronautical information services''', '["Annex 11", "Annex 14", "Annex 15", "Annex 17"]'::jsonb, 2, 'Annex 15 contains the Standards and Recommended Practices for aeronautical information services.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
