INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-013', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'easy', 'Which ATS objective is served by notifying rescue organisations about an aircraft needing aid''', '["The speed-control objective", "The aerodrome-lighting objective", "The registration objective", "The search and rescue support objective"]'::jsonb, 3, 'Notifying and assisting the organisations responsible for search and rescue is one of the five ATS objectives.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-014', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'Which airspace structure begins at the surface and protects arriving and departing controlled flights''', '["An airway", "A UIR", "A control zone", "A control area"]'::jsonb, 2, 'A control zone begins at the surface and contains the relevant arriving and departing flight paths.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-015', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'hard', 'Which ICAO Annex contains the international airworthiness Standards''', '["Annex 8", "Annex 6", "Annex 7", "Annex 16"]'::jsonb, 0, 'Annex 8 contains the international Standards for the airworthiness of aircraft.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-016', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'easy', 'Which State determines whether an aircraft on its register continues to be airworthy''', '["State of Manufacture", "State of Registry", "State of the next landing", "State of the operator''s insurer"]'::jsonb, 1, 'The State of Registry determines whether an aircraft on its register continues to be airworthy.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-017', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'Which setting makes an altimeter indicate altitude above mean sea level''', '["QFE", "QNE", "QNH", "Standard pressure only"]'::jsonb, 2, 'QNH makes the altimeter indicate altitude referenced to mean sea level.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-018', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'hard', 'What should a correctly set QFE altimeter indicate at its reference datum''', '["Zero", "Aerodrome elevation", "Flight level zero", "The transition altitude"]'::jsonb, 0, 'QFE is the pressure at the stated datum, so the altimeter indicates zero there.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-019', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'easy', 'Which instrument is the principal current Indian statute in the hierarchy described in this chapter''', '["Aircraft Rules 1937", "Chicago Convention", "Bharatiya Vayuyan Adhiniyam 2024", "Civil Aviation Requirements"]'::jsonb, 2, 'Bharatiya Vayuyan Adhiniyam 2024 is the principal current Indian statute, while the Rules and Civil Aviation Requirements provide more detailed requirements.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-020', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which Indian authority has the core civil aviation security oversight role''', '["BCAS", "AAIB", "AAI", "WPC Wing"]'::jsonb, 0, 'BCAS is the authority responsible for civil aviation security policy, standards and oversight.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-021', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'hard', 'What is the main purpose of Annex 9 facilitation''', '["To remove all border controls", "To expedite international air transport while maintaining necessary controls", "To replace customs with airline staff", "To govern aircraft design"]'::jsonb, 1, 'Annex 9 expedites aircraft, people and goods while preserving necessary customs, immigration, health, security and law-enforcement controls.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-022', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'easy', 'What happens when an aircraft-clearance document has been accepted electronically''', '["The same document should not also be demanded on paper", "It becomes a crew licence", "It may be ignored by authorities", "It must always be sent twice"]'::jsonb, 0, 'Once authorities accept the required electronic document, they should not demand the identical document again on paper.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-023', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which Chicago Convention Article establishes complete and exclusive State sovereignty over the airspace above its territory''', '["Article 5", "Article 1", "Article 12", "Article 38"]'::jsonb, 1, 'Article 1 establishes complete and exclusive sovereignty over the airspace above a State''s territory.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-024', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'hard', 'What does Article 6 require before a scheduled international air service operates over or into another State''', '["Only a filed flight plan", "A technical stop", "Cabotage approval", "Special permission or authorisation from that State"]'::jsonb, 3, 'Special permission or authorisation from that State is required for a scheduled international air service under Article 6.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-025', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'easy', 'Which law replaced the Aircraft Act, 1934 as India''s principal civil aviation enabling statute''', '["The Bharatiya Vayuyan Adhiniyam, 2024", "The Indian Aircraft Rules, 1920", "The Drone Rules, 2021", "The Aircraft Security Rules, 2011"]'::jsonb, 0, 'The Bharatiya Vayuyan Adhiniyam, 2024 replaced the Aircraft Act, 1934 as the principal enabling statute.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-026', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'Which body has the central role of investigating aircraft accidents and incidents in India''', '["Airports Authority of India", "Bureau of Civil Aviation Security", "Aircraft Accident Investigation Bureau", "Directorate General of Health Services"]'::jsonb, 2, 'The Aircraft Accident Investigation Bureau is the body responsible for investigating aircraft accidents and incidents.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-027', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'hard', 'Which threshold IAS places an aeroplane in Category C''', '["121 to 140 kt", "91 to 120 kt", "141 to 165 kt", "166 to 210 kt"]'::jsonb, 0, 'Category C covers a threshold IAS from 121 to 140 kt.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-028', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'easy', 'Which segment normally connects the en-route phase to the IAF''', '["Final", "Initial", "Arrival", "Intermediate"]'::jsonb, 2, 'The arrival segment connects the en-route structure or STAR to the IAF.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-029', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Where is full MOC provided in a track-guided protected area''', '["Only at the outer edge", "Only over the controlling obstacle", "Across the primary area", "Across each secondary area"]'::jsonb, 2, 'Full MOC applies across the primary area; in each secondary area it tapers to zero at the outer edge.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-030', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'hard', 'What engine condition is assumed in the design of a published instrument departure''', '["One engine inoperative", "Critical engine at idle", "Any condition selected by ATC", "All engines operating"]'::jsonb, 3, 'PANS-OPS departure procedures assume all engines are operating, so the operator develops the engine-out contingency.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-031', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'easy', 'Which ICAO Annex contains the Standards for aircraft nationality and registration marks''', '["Annex 7", "Annex 1", "Annex 8", "Annex 9"]'::jsonb, 0, 'Annex 7 contains the international Standards for Aircraft Nationality and Registration Marks.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-032', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Who assigns the individual registration mark to an aircraft''', '["The aircraft manufacturer", "The International Telecommunication Union alone", "The State of Registry or common mark registering authority", "The aerodrome operator"]'::jsonb, 2, 'The State of Registry or common mark registering authority assigns the aircraft''s registration mark.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-033', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'hard', 'What is the relationship between an operator''s MEL and the approved MMEL''', '["The MEL replaces all Flight Manual limits", "The MMEL applies only to one flight", "The MEL cannot be less restrictive than the MMEL", "Neither document needs approval"]'::jsonb, 2, 'The operator''s approved MEL is tailored from, and cannot be less restrictive than, the approved MMEL.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-034', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'easy', 'When does holdover time begin''', '["At engine start", "At the start of the final de-icing or anti-icing application", "At the end of the first inspection", "When taxi begins"]'::jsonb, 1, 'Holdover time begins at the start of the final de-icing or anti-icing application.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-035', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'What does an AOC or permit authorise''', '["Only aerodrome construction", "Any flight without operational limits", "Only aircraft maintenance", "Specified commercial air transport operations"]'::jsonb, 3, 'An AOC or permit authorises the operator to conduct specified commercial air transport operations.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-036', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'hard', 'Which item belongs in the operational-manual group carried on board''', '["The Minimum Equipment List", "A passenger''s passport copy", "A land-ownership deed", "An aerodrome construction permit"]'::jsonb, 0, 'The Minimum Equipment List is one of the operational documents carried for the flight.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-037', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'easy', 'What is the minimum age stated by Bali for an aeroplane CPL''', '["18 years", "16 years", "17 years", "21 years"]'::jsonb, 0, 'The minimum age for an aeroplane Commercial Pilot''s Licence is 18 years.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-038', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'Which language level is Operational and must be re-evaluated every three years''', '["Level 6", "Level 3", "Level 4", "Level 5"]'::jsonb, 2, 'Level 4 is Operational, is accepted, and requires re-evaluation every three years.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-039', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'hard', 'When may the pilot-in-command depart from a Rule of the Air''', '["Only when absolutely necessary in the interests of safety", "Whenever a passenger requests it", "Whenever operating in visual conditions", "Only after landing"]'::jsonb, 0, 'A pilot-in-command may depart from a Rule only when circumstances make it absolutely necessary in the interests of safety.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-040', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'easy', 'What must pre-flight action include for an IFR flight''', '["Only the intended departure time", "Only aircraft registration details", "Current weather, fuel requirements and an alternative course of action", "A passenger preference survey"]'::jsonb, 2, 'IFR pre-flight action includes current weather information, fuel requirements and an alternative course of action if the plan cannot be completed.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-041', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What flight visibility is required at or above 10,000 ft AMSL under the standard VMC table''', '["5 km", "3 km", "1.5 km", "8 km"]'::jsonb, 3, 'The standard VMC minimum at or above 10,000 ft AMSL is 8 km flight visibility.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-042', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'hard', 'Which statement describes a Special VFR flight''', '["It may ignore ATC in a control zone", "It is an IFR flight in visual conditions", "It is individually cleared within a control zone and remains clear of cloud with the surface in sight", "It is available above FL 150 without approval"]'::jsonb, 2, 'Special VFR is an individually cleared control-zone operation that remains clear of cloud and in sight of the surface.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-043', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'easy', 'Which unit coordinates search and rescue operations throughout one SAR region''', '["The Rescue Coordination Centre", "The operator''s dispatch office", "The aerodrome customs office", "The aircraft manufacturer"]'::jsonb, 0, 'The Rescue Coordination Centre organises SAR service and coordinates operations throughout its SAR region.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-044', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'Which organisation coordinates maritime SAR policy in Bali''s Indian framework''', '["NASARCC", "Airports Authority of India", "The National Maritime Search and Rescue Board", "The meteorological office"]'::jsonb, 2, 'The National Maritime Search and Rescue Board coordinates maritime SAR policy under the Indian Coast Guard leadership described by Bali.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-045', 'air-regulations', 'air-regulations-security', 'Security', 'hard', 'What is the primary objective of Annex 17 security measures''', '["Fast passenger processing", "Commercial protection alone", "Safety of passengers, crew, ground personnel and the public", "Uniform ticket prices"]'::jsonb, 2, 'The safety of passengers, crew, ground personnel and the public is the primary Annex 17 objective.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-046', 'air-regulations', 'air-regulations-security', 'Security', 'easy', 'Which body is India''s specialist civil aviation security regulator and oversight authority''', '["AAIB", "ICAO Council", "Airports Authority only", "Bureau of Civil Aviation Security"]'::jsonb, 3, 'The Bureau of Civil Aviation Security, BCAS, sets standards and oversees civil aviation security in India.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-047', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What is the normal vertical separation minimum below FL 290''', '["2,000 ft", "1,000 ft", "500 ft", "4,000 ft"]'::jsonb, 1, 'Below FL 290, the normal vertical separation minimum is 1,000 ft.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-048', 'air-regulations', 'air-regulations-separation', 'Separation', 'hard', 'When does the Bali VOR divergence method establish lateral separation''', '["At 5 degrees with both aircraft overhead", "At 30 degrees with no distance condition", "At 15 degrees with at least one aircraft 15 NM from the facility", "At 90 degrees only"]'::jsonb, 2, 'The VOR method uses at least 15 degrees divergence with one aircraft at least 15 NM from the facility.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-049', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'easy', 'When may a one-minute interval be used between two departures under Bali''s stated divergence case''', '["Only when vertical separation already exists", "Whenever the preceding aircraft is faster", "When both aircraft fly the same SID", "When their tracks diverge by at least 45 degrees immediately after take-off"]'::jsonb, 3, 'One minute applies when the departure tracks diverge by at least 45 degrees immediately after take-off.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-050', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'What speed relationship supports Bali''s two-minute same-track departure interval''', '["The following aircraft is at least 20 kt faster", "The preceding aircraft is at least 40 kt faster", "Both aircraft have identical filed speeds", "The preceding aircraft is at least 10 kt faster"]'::jsonb, 1, 'The two-minute same-track case requires the preceding aircraft to be 40 kt or more faster than the following aircraft.', 'R.K. Bali Air Regulations / ICAO Annexes, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-001', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'easy', 'The lowest layer of the atmosphere, in which almost all weather phenomena occur, is called the:', '["Stratosphere", "Troposphere", "Mesosphere", "Thermosphere"]'::jsonb, 1, 'The troposphere extends from the surface to about 16-18 km at the equator and 8-10 km at the poles. It contains about 75% of the atmospheric mass and virtually all weather phenomena.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''Atmosphere'', Page 5', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-002', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'medium', 'In the International Standard Atmosphere (ISA), what is the standard temperature and pressure at mean sea level''', '["15°C (288.15 K) and 1013.25 hPa", "20°C and 1000 hPa", "0°C and 1013.25 hPa", "15°C and 1000 hPa"]'::jsonb, 0, 'ICAO ISA specifies sea level temperature as +15°C (288.15 K), pressure as 1013.25 hPa (29.92 inHg), and density as 1225 g/m³ with a lapse rate of 6.5°C/km (approx 1.98°C/1000 ft) up to 11 km.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''Atmosphere'', Page 7', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-003', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'medium', 'The height of the tropopause is:', '["Constant over all latitudes at 11 km", "Highest at the equator (16-18 km) and lowest at the poles (8-10 km)", "Highest at the poles and lowest at the equator", "Dependent only on the time of day"]'::jsonb, 1, 'Due to intense solar heating and strong vertical convective currents in the tropics, the tropopause reaches 16-18 km at the equator, while over the cold poles it lies between 8-10 km.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''Atmosphere'', Page 5', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-004', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'hard', 'In ISA, from 11 km to 20 km altitude, the temperature is assumed to:', '["Decrease at 2°C/1000 ft", "Increase at 1°C/km", "Remain constant at -56.5°C (isothermal)", "Decrease to -90°C"]'::jsonb, 2, 'In the ICAO Standard Atmosphere, temperature decreases at 6.5°C/km from sea level to 11 km (-56.5°C), and then remains isothermal at -56.5°C from 11 km up to 20 km.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''Atmosphere'', Page 7', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-005', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'easy', 'Roughly, a 1 hPa decrease in atmospheric pressure near mean sea level corresponds to an increase in height of approximately:', '["10 ft", "27 to 30 ft", "60 ft", "100 ft"]'::jsonb, 1, 'Near mean sea level, 1 hPa change in pressure corresponds to approximately 27 to 30 ft (96 * T/P ft). At 20,000 ft it is about 50 ft/hPa, and at 40,000 ft about 100 ft/hPa.', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure'', Page 12', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-006', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'medium', 'When flying from an area of high pressure into an area of low pressure without resetting the altimeter subscale, the altimeter will:', '["Under-read (aircraft is higher than indicated)", "Over-read (aircraft is lower than indicated)", "Read correctly because pitot-static tube compensates", "Fluctuate rapidly between high and low readings"]'::jsonb, 1, 'Rule: ''High to Low, Look Out Below''. When flying from high to low pressure, the altimeter senses lower pressure and interprets it as higher altitude, thus over-reading. The true altitude is lower than indicated.', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure'', Page 19', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-007', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'medium', 'Which pressure setting is defined as the aerodrome station level pressure reduced to mean sea level assuming ISA conditions''', '["QFE", "QFF", "QNH", "QNE"]'::jsonb, 2, 'QNH is station pressure reduced to MSL using ISA temperature lapse rate. When set on the altimeter subscale on the ground, the altimeter reads aerodrome elevation above MSL.', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure'', Page 18', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-008', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'hard', 'In the standard atmosphere, the 500 hPa and 300 hPa pressure levels correspond approximately to which altitudes''', '["10,000 ft and 20,000 ft", "18,000 ft (FL180) and 30,000 ft (FL300)", "24,000 ft and 40,000 ft", "14,000 ft and 25,000 ft"]'::jsonb, 1, 'Standard isobaric levels in ISA: 850 hPa = 5,000 ft (FL50); 700 hPa = 10,000 ft (FL100); 500 hPa = 18,000 ft (FL180); 300 hPa = 30,000 ft (FL300); 200 hPa = 38,000 ft (FL380).', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure'', Page 19 Table 2.1', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-009', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'easy', 'On a clear day with calm winds, the minimum surface air temperature normally occurs:', '["At midnight", "At 03:00 local time", "Half an hour to one hour after sunrise", "Exactly at the moment of sunrise"]'::jsonb, 2, 'Due to nocturnal radiational cooling, ground temperatures continue falling after sunrise until incoming solar radiation balances outgoing terrestrial radiation, typically 30 to 60 minutes after dawn.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature'', Page 32', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-010', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'medium', 'The fraction of incoming solar radiation reflected back into space by clouds, aerosols, and the Earth surface is termed:', '["Insolation", "Albedo", "Advection", "Thermal radiation"]'::jsonb, 1, 'Albedo is the ratio of reflected solar radiation to total incident solar radiation. Earth''s average albedo is about 30%, whereas fresh snow reflects about 80%.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature'', Page 31', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-011', 'aviation-meteorology', 'aviation-meteorology-air-density', 'Air Density', 'easy', 'Density altitude is defined as:', '["The pressure altitude corrected for non-standard temperature", "The altitude above ground level in standard temperature", "The indicated altitude corrected for instrument error", "The true altitude minus terrain elevation"]'::jsonb, 0, 'Density altitude is pressure altitude corrected for non-standard temperature. In aviation, high density altitude reduces aircraft performance: longer takeoff run, slower rate of climb, and reduced engine power.', 'I.C. Joshi Aviation Meteorology, Chapter 4 ''Air Density'', Page 36', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-012', 'aviation-meteorology', 'aviation-meteorology-air-density', 'Air Density', 'medium', 'For every 1°C increase in temperature above ISA, the density altitude increases by approximately:', '["30 ft", "60 ft", "120 ft", "200 ft"]'::jsonb, 2, 'A rule of thumb in aviation meteorology states that for each 1°C rise above standard ISA temperature, density altitude increases by approximately 120 ft above pressure altitude.', 'I.C. Joshi Aviation Meteorology, Chapter 4 ''Air Density'', Page 36', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-013', 'aviation-meteorology', 'aviation-meteorology-humidity', 'Humidity', 'easy', 'The temperature to which moist air must be cooled at constant pressure to reach saturation is called the:', '["Wet bulb temperature", "Dew point temperature", "Virtual temperature", "Frost point"]'::jsonb, 1, 'Dew point (Td) is the temperature to which unsaturated air must be cooled at constant pressure and moisture content to become saturated (100% relative humidity).', 'I.C. Joshi Aviation Meteorology, Chapter 5 ''Humidity'', Page 41', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-014', 'aviation-meteorology', 'aviation-meteorology-humidity', 'Humidity', 'medium', 'When unsaturated air is lifted adiabatically, what happens to its Relative Humidity (RH) and Dew Point (DP)''', '["RH decreases and DP increases", "RH increases and DP decreases (by approx 2°C/km)", "RH and DP both remain unchanged", "RH increases while the humidity mixing ratio increases"]'::jsonb, 1, 'As air rises, it expands and cools at DALR (9.8°C/km). Dew point falls at approx 1.8°C to 2°C/km. The temperature and dew point converge, so Relative Humidity increases until saturation (LCL).', 'I.C. Joshi Aviation Meteorology, Chapter 5 ''Humidity'', Page 41-42', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-015', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'easy', 'In the Northern Hemisphere, Buys Ballot''s Law states that if an observer stands with their back to the wind:', '["Low pressure is to their right and high pressure to their left", "Low pressure is to their left and high pressure to their right", "Low pressure is directly ahead", "Low pressure is directly behind"]'::jsonb, 1, 'Buys Ballot''s Law states that in the Northern Hemisphere, an observer facing downwind has lower pressure to the left and higher pressure to the right. In the Southern Hemisphere, this is reversed.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Winds'', Page 46', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-016', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'medium', 'Coriolis force is directly proportional to wind speed and the sine of latitude. Where is Coriolis force zero''', '["At the geographic poles", "At 45° latitude", "At the Equator", "At the tropopause"]'::jsonb, 2, 'Coriolis force = 2 * omega * V * sin(phi). Since sin(0°) = 0, Coriolis force is zero at the Equator and reaches its maximum value at the poles where sin(90°) = 1.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Winds'', Page 47', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-017', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'medium', 'A cold, dense wind blowing down a mountain slope at night due to surface cooling is termed a:', '["Fohn wind", "Anabatic wind", "Katabatic wind", "Chinook"]'::jsonb, 2, 'Katabatic winds are gravity-driven down-slope winds caused by nocturnal radiational cooling of the mountain slopes, making the air heavier than surrounding free air.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Winds'', Page 54', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-018', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'hard', 'A sudden increase in wind speed of at least 16 kt (32 km/h), reaching 22 kt or more and lasting for at least one minute, is classified as a:', '["Gust", "Squall", "Gale", "Microburst"]'::jsonb, 1, 'WMO defines a squall as a sudden increase of wind speed by at least 16 kt (8 m/s), the speed rising to 22 kt (11 m/s) or more and lasting for at least one minute. Gusts are transient fluctuations of seconds.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Winds'', Page 46', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-019', 'aviation-meteorology', 'aviation-meteorology-visibility-fog', 'Visibility & Fog', 'easy', 'In aviation weather reports, ''Fog'' (FG) is reported when the horizontal visibility is reduced by water droplets or ice crystals to less than:', '["500 m", "1000 m", "1500 m", "5000 m"]'::jsonb, 1, 'By international aeronautical definition, fog is reported when visibility is less than 1000 m and relative humidity is near 100%. If visibility is between 1000 m and 5000 m with RH >= 95%, it is reported as Mist (BR).', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Visibility and Fog'', Page 66', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-020', 'aviation-meteorology', 'aviation-meteorology-visibility-fog', 'Visibility & Fog', 'medium', 'Radiation fog is most likely to form under which combination of meteorological conditions''', '["Strong winds (> 15 kt), overcast stratus sky, and dry air", "Light winds (2-7 kt), clear skies at night, and high relative humidity", "Calm wind, cloudy sky, and warm advection", "Gale force winds and heavy precipitation"]'::jsonb, 1, 'Radiation fog requires high relative humidity, clear skies for maximum terrestrial radiation cooling, and light wind (2-7 kt) to produce gentle turbulent mixing confined to a shallow layer near the ground.', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Visibility and Fog'', Page 69', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-021', 'aviation-meteorology', 'aviation-meteorology-visibility-fog', 'Visibility & Fog', 'medium', 'Advection fog forms when:', '["Cold dry air blows over warm land", "Warm, moist air moves horizontally over a cold land or sea surface", "Air is cooled adiabatically by climbing a mountain", "Rain falls into cold surface air"]'::jsonb, 1, 'Advection fog forms when warm moist air is transported over a colder underlying surface, cooling the air to its dew point. It can form over land or sea at any time of day or night and with moderate winds.', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Visibility and Fog'', Page 70', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-022', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'easy', 'Which cloud type is characterized by great vertical development, an anvil-shaped fibrous top, and hazards including severe turbulence, hail, and microbursts''', '["Altocumulus (AC)", "Nimbostratus (NS)", "Cumulonimbus (CB)", "Stratocumulus (SC)"]'::jsonb, 2, 'Cumulonimbus (CB) is the thunderstorm cloud. It features massive vertical development, anvil cirrus top, and poses the most severe hazards in aviation (turbulence, severe icing, wind shear, hail, lightning).', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Clouds'', Page 78', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-023', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'medium', 'Optical halos around the sun or moon are produced by light refraction through ice crystals in which cloud type''', '["Altocumulus (AC)", "Cirrostratus (CS)", "Altostratus (AS)", "Stratocumulus (SC)"]'::jsonb, 1, 'Cirrostratus (CS) clouds consist of hexagonal ice crystals that refract sunlight or moonlight at a 22° angle, producing a circular halo with the red component on the inside.', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Clouds'', Page 77; Chapter 10 ''Optical Phenomena'', Page 94', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-024', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'medium', 'Precipitation consisting of very small, closely spaced water droplets (diameter < 0.5 mm) falling almost exclusively from Stratus cloud is termed:', '["Rain (RA)", "Drizzle (DZ)", "Sleet", "Virga"]'::jsonb, 1, 'Drizzle (DZ) consists of small water droplets of diameter 0.1 to 0.5 mm that appear to float in air currents. It falls almost exclusively from Stratus (ST) clouds.', 'I.C. Joshi Aviation Meteorology, Chapter 11 ''Precipitation'', Page 100', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-025', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'hard', 'Rain falling from a cloud that evaporates completely before reaching the ground is called:', '["Graupel", "Virga", "Mirage", "Mizzle"]'::jsonb, 1, 'Virga is precipitation falling from a cloud base that evaporates in dry air below before reaching the ground. It often indicates strong downdrafts beneath the cloud.', 'I.C. Joshi Aviation Meteorology, Chapter 11 ''Precipitation'', Page 101', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-026', 'aviation-meteorology', 'aviation-meteorology-stability-adiabatics', 'Stability & Adiabatics', 'medium', 'The Dry Adiabatic Lapse Rate (DALR) and Saturated Adiabatic Lapse Rate (SALR) near sea level are approximately:', '["6.5°C/km and 2°C/km", "9.8°C/km (approx 3°C/1000 ft) and 5°C/km (approx 1.5°C/1000 ft)", "2°C/1000 ft and 3°C/1000 ft", "10°C/km and 9.8°C/km"]'::jsonb, 1, 'DALR is constant at 9.8°C/km (approx 3°C/1000 ft). SALR is lower because latent heat released during condensation warms the rising air, averaging about 5°C/km near sea level.', 'I.C. Joshi Aviation Meteorology, Chapter 9 ''Stability and Instability'', Page 86', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-027', 'aviation-meteorology', 'aviation-meteorology-stability-adiabatics', 'Stability & Adiabatics', 'hard', 'If the Environmental Lapse Rate (ELR) is greater than the Dry Adiabatic Lapse Rate (DALR), the atmosphere is in a state of:', '["Absolute stability", "Conditional instability", "Absolute instability", "Neutral equilibrium"]'::jsonb, 2, 'When ELR > DALR (super-adiabatic), lifted parcels of both dry and saturated air are warmer and less dense than the environment, continuing to accelerate upward (Absolute Instability).', 'I.C. Joshi Aviation Meteorology, Chapter 9 ''Stability and Instability'', Page 87', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-028', 'aviation-meteorology', 'aviation-meteorology-ice-accretion', 'Ice Accretion', 'medium', 'Clear ice (glazed ice) on an airframe is most dangerous because it:', '["Is light and easily shaken off by vibration", "Is heavy, transparent, adheres tenaciously, alters airfoil shape, and is hard to remove", "Forms only on parked aircraft overnight", "Affects only communication antennas"]'::jsonb, 1, 'Clear ice forms from large supercooled water droplets at temperatures between 0°C and -10°C. The drops flow back before freezing, forming a dense, tenacious, transparent coating that severely degrades lift and adds weight.', 'I.C. Joshi Aviation Meteorology, Chapter 12 ''Ice Accretion'', Page 106', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-029', 'aviation-meteorology', 'aviation-meteorology-ice-accretion', 'Ice Accretion', 'easy', 'Carburetor icing in piston engines is most likely to occur in which temperature and humidity conditions''', '["Only below -20°C in dry air", "At ambient temperatures between -7°C and +30°C in moist air (RH > 60%)", "Only when flying through heavy rain at 0°C", "Only during full-throttle takeoff climb"]'::jsonb, 1, 'Fuel vaporization and adiabatic pressure reduction at the carburetor throttle butterfly can drop air temperature by up to 20°C. Carburetor ice can form even in warm ambient air up to +30°C with high relative humidity.', 'I.C. Joshi Aviation Meteorology, Chapter 12 ''Ice Accretion'', Page 107', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-030', 'aviation-meteorology', 'aviation-meteorology-thunderstorms', 'Thunderstorms', 'medium', 'The mature stage of a thunderstorm lifecycle is definitively marked by:', '["The first appearance of an anvil top", "The beginning of rain at the Earth''s surface and the onset of downdrafts", "The cessation of all lightning flashes", "Weakening of the updrafts throughout the entire cell"]'::jsonb, 1, 'The mature stage begins when falling precipitation reaches the surface. Rain drags cold air downward, generating downdrafts and the first gust / squall front. Updrafts and downdrafts coexist in this stage.', 'I.C. Joshi Aviation Meteorology, Chapter 13 ''Thunderstorm'', Page 113', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-031', 'aviation-meteorology', 'aviation-meteorology-thunderstorms', 'Thunderstorms', 'hard', 'A microburst is a localized intense downdraught with a horizontal diameter of less than 4 km. Its lifecycle typically lasts about:', '["1 to 2 hours", "15 to 20 minutes", "1 to 2 days", "30 to 45 seconds"]'::jsonb, 1, 'Microbursts typically last 15 to 20 minutes. Peak winds develop 5 minutes after surface contact. An aircraft flying through encounters increasing headwind, strong downdraft, and then a dangerous sudden tailwind.', 'I.C. Joshi Aviation Meteorology, Chapter 13 ''Thunderstorm'', Page 117-118', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-032', 'aviation-meteorology', 'aviation-meteorology-air-masses-fronts', 'Air Masses & Fronts', 'medium', 'What is the typical slope of a cold front compared to a warm front''', '["Cold front is flatter (1:150 to 1:180), warm front is steeper", "Cold front is steeper (approx 1:50 to 1:80), warm front is shallower (approx 1:150 to 1:180)", "Both fronts have the identical slope of 1:100", "Cold fronts have no slope as they are vertical walls"]'::jsonb, 1, 'Cold fronts advance like a blunt wedge with a steep slope of about 1:50 to 1:80, causing rapid vertical lifting and convective clouds (CU, CB). Warm fronts have a shallow slope of 1:150 to 1:180 with stratiform clouds.', 'I.C. Joshi Aviation Meteorology, Chapter 14 ''Air Masses Fronts and Western Disturbances'', Page 128-129', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-033', 'aviation-meteorology', 'aviation-meteorology-air-masses-fronts', 'Air Masses & Fronts', 'medium', 'Western Disturbances (WDs) affecting northern India during winter originate primarily over which region''', '["Bay of Bengal", "Arabian Sea", "Mediterranean Sea and Caspian Sea region", "Siberian landmass"]'::jsonb, 2, 'Western Disturbances originate as extra-tropical low-pressure systems over the Mediterranean and Caspian Seas, travelling eastward steered by the Subtropical Westerly Jet stream into Pakistan and northern India.', 'I.C. Joshi Aviation Meteorology, Chapter 14 ''Air Masses Fronts and Western Disturbances'', Page 132', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-034', 'aviation-meteorology', 'aviation-meteorology-jet-streams', 'Jet Streams', 'easy', 'By WMO definition, the arbitrary lower speed limit for the core of a jet stream is:', '["30 kt", "45 kt", "60 kt (approx 30 m/s)", "100 kt"]'::jsonb, 2, 'WMO defines a jet stream as a strong narrow current of winds concentrated along a quasi-horizontal axis in the upper troposphere or stratosphere, with a minimum core speed of 60 kt (30 m/s).', 'I.C. Joshi Aviation Meteorology, Chapter 15 ''Jet Streams'', Page 136', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-035', 'aviation-meteorology', 'aviation-meteorology-jet-streams', 'Jet Streams', 'medium', 'The Subtropical Jet Stream (STJ) affects northern India primarily during which months''', '["June to September only", "October to May (winter and transition seasons)", "July and August only", "April and May only"]'::jsonb, 1, 'The Subtropical Westerly Jet Stream prevails over northern India from October to May, reaching peak core speeds of 100-150 kt in January/February near 27° N at 12 km (200 hPa).', 'I.C. Joshi Aviation Meteorology, Chapter 15 ''Jet Streams'', Page 137', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-036', 'aviation-meteorology', 'aviation-meteorology-clear-air-turbulence', 'Clear Air Turbulence', 'medium', 'Clear Air Turbulence (CAT) is most severe and most frequently encountered in which region relative to a jet stream''', '["Directly in the calm center of the jet core", "On the low-pressure (colder / poleward) side near or below the jet axis where vertical and horizontal wind shear is greatest", "Far away from all frontal zones and tropopause folds", "Only at altitudes below 10,000 ft AMSL"]'::jsonb, 1, 'CAT occurs predominantly in regions of strong horizontal and vertical wind shear just below the tropopause, especially on the colder, poleward (left in Northern Hemisphere) side of the jet stream core.', 'I.C. Joshi Aviation Meteorology, Chapter 16 ''Clear Air Turbulence'', Page 143', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-037', 'aviation-meteorology', 'aviation-meteorology-tropical-systems-monsoon', 'Tropical Systems & Monsoon', 'easy', 'In the mature stage of a Tropical Cyclone, the central calm region of light winds and descending air is termed the:', '["Wall Cloud", "Eye", "Surge Line", "Spiral Band"]'::jsonb, 1, 'The Eye is the central region of lowest surface pressure, warmest temperatures, light winds, and often clear skies caused by subsiding air. It is surrounded by the destructive Eye Wall.', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Tropical Systems'', Page 157', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-038', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'medium', 'The normal date of onset of the Southwest Monsoon over the mainland of India (Kerala coast) is:', '["15 May", "01 June", "15 June", "01 July"]'::jsonb, 1, 'The normal date for the onset of the Southwest Monsoon over the South Andaman Sea is 20 May, and over the mainland coast of Kerala is 01 June.', 'I.C. Joshi Aviation Meteorology, Chapter 19 ''Climatology of India'', Page 171', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-039', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'medium', 'During a ''Break in Monsoon'', the axis of the monsoon trough shifts towards:', '["The Indian Peninsula (Tamil Nadu)", "The foot hills of the Himalayas", "The central Arabian Sea", "The equator"]'::jsonb, 1, 'During a break in monsoon, the monsoon trough shifts northwards close to the Himalayan foothills, causing heavy floods in Assam and sub-Himalayan Bengal while the plains of India experience dry spells.', 'I.C. Joshi Aviation Meteorology, Chapter 19 ''Climatology of India'', Page 172', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-040', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'easy', 'In a METAR weather report, the term CAVOK indicates that simultaneously:', '["Visibility >= 10 km, no clouds below 1500 m (5000 ft) or MSA, and no weather of significance", "Visibility >= 5 km and sky completely clear", "Visibility >= 8 km and no rain", "No clouds at all altitudes and zero wind"]'::jsonb, 0, 'CAVOK (Ceiling And Visibility OK) requires: visibility 10 km or more; no cloud below 1500 m (5000 ft) or highest minimum sector altitude (whichever is greater), no CB/TCU; and no significant weather.', 'I.C. Joshi Aviation Meteorology, Chapter 25 ''METAR SPECI'', Page 219', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-041', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'medium', 'A TREND landing forecast appended to a METAR or SPECI has a validity period of:', '["30 minutes", "2 hours", "6 hours", "9 hours"]'::jsonb, 1, 'A TREND forecast consists of a concise statement of expected significant changes appended to a METAR or SPECI and is valid for 2 hours from the time of the report.', 'I.C. Joshi Aviation Meteorology, Chapter 25 ''METAR SPECI'', Page 223', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-042', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'medium', 'In a TAF report, the change indicator ''TEMPO 1215'' means that the described weather changes are expected to:', '["Start permanently at 12:00 UTC and continue through 15:00 UTC", "Occur temporarily between 12:00 UTC and 15:00 UTC, lasting less than 1 hour in each instance", "Be valid only for 12 to 15 minutes", "Occur exactly at 12:15 UTC"]'::jsonb, 1, 'TEMPO denotes temporary fluctuations lasting less than one hour in each instance and in aggregate covering less than half of the indicated period (from 12:00 to 15:00 UTC).', 'I.C. Joshi Aviation Meteorology, Chapter 26 ''Aviation Weather Forecasts TAF'', Page 224, 231', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-043', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'hard', 'In a METAR, ''R27/1200D'' in the runway visual range group indicates:', '["Runway 27 RVR is 1200 ft with downward slope", "Runway 27 RVR is 1200 metres with a downward (decreasing) tendency", "Runway 27 RVR is 1200 metres during daytime", "Runway 27 RVR is between 1200 and 1500 m"]'::jsonb, 1, 'In the RVR group RD_R/V_RV_RV_RV_R i: R27 indicates Runway 27, 1200 indicates 1200 metres, and the tendency letter ''D'' indicates decreasing over the past 10 minutes (''U'' = increasing, ''N'' = no change).', 'I.C. Joshi Aviation Meteorology, Chapter 25 ''METAR SPECI'', Page 221', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-044', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'medium', 'A SIGMET is issued by a Meteorological Watch Office (MWO) to warn pilots of:', '["Routine terminal weather conditions", "En-route weather phenomena that may affect the safety of all aircraft operations", "Only local airport surface wind gusts", "Flight delays caused by air traffic congestion"]'::jsonb, 1, 'SIGMET messages give concise information concerning the occurrence or expected occurrence of specified en-route weather phenomena which may affect the safety of aircraft operations (e.g., severe turbulence, severe icing, volcanic ash, tropical cyclones).', 'I.C. Joshi Aviation Meteorology, Chapter 21 ''Met Services'', Page 192', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-045', 'aviation-meteorology', 'aviation-meteorology-general-circulation', 'General Circulation', 'medium', 'The descending branch of the Hadley Cell near latitude 30° N and 30° S is characterized by calm winds, high pressure, and world deserts. This region is known as:', '["The Doldrums (ITCZ)", "The Horse Latitudes", "The Roaring Forties", "The Polar Front"]'::jsonb, 1, 'The Horse Latitudes are subtropical high-pressure belts located around 30° N and 30° S, formed by subsiding air from the Hadley cell. The sinking air causes adiabatic warming, cloud dissipation, calm winds, and major arid zones.', 'I.C. Joshi Aviation Meteorology, Chapter 20 ''General Circulation'', Page 184', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-001', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'easy', 'According to Bernoulli''s principle, as airflow accelerates over the cambered upper surface of an airfoil, what happens to dynamic pressure and static pressure''', '["Dynamic pressure decreases and static pressure increases", "Dynamic pressure increases and static pressure decreases", "Both dynamic and static pressure increase", "Both dynamic and static pressure decrease"]'::jsonb, 1, 'Bernoulli''s theorem states that for steady incompressible flow, total pressure (static + dynamic) remains constant. As air accelerates over the camber, dynamic pressure increases and static pressure decreases, producing lift.', 'Oxford ATPL Principles of Flight, Chapter 2 ''Subsonic Airflow''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-002', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'An aircraft will stall whenever which condition occurs''', '["The airspeed falls below a fixed calibrated airspeed", "The critical (stalling) angle of attack is exceeded, regardless of airspeed, weight, or attitude", "The engine power is reduced to idle", "The aircraft enters a banked turn exceeding 45 degrees"]'::jsonb, 1, 'An airfoil always stalls at the same critical angle of attack (typically 15°-18° for general aviation airfoils), regardless of airspeed, weight, load factor, or flight attitude.', 'Oxford ATPL Principles of Flight, Chapter 3 ''The Stall''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-003', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'Induced drag is a byproduct of lift creation caused by wingtip vortices. As airspeed increases in straight and level flight, induced drag:', '["Increases proportional to the square of airspeed", "Decreases inversely proportional to the square of airspeed", "Remains constant", "Increases linearly with airspeed"]'::jsonb, 1, 'Induced drag is inversely proportional to the square of airspeed (Di proportional to 1/V^2). At high speeds, angle of attack is small, wingtip vortices are weak, and induced drag is low. At low speeds, induced drag is high.', 'Oxford ATPL Principles of Flight, Chapter 4 ''Drag''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-004', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'hard', 'In a level, coordinated 60-degree banked turn, the load factor (g) and stall speed increase by approximately what factors''', '["Load factor 1.41 g, stall speed increases by 19%", "Load factor 2.0 g, stall speed increases by approximately 41%", "Load factor 3.0 g, stall speed doubles (100%)", "Load factor 1.5 g, stall speed increases by 25%"]'::jsonb, 1, 'Load factor n = 1 / cos(bank angle). At 60°, n = 1/cos(60°) = 2.0 g. Stall speed in a turn Vs_turn = Vs_level * sqrt(n) = Vs * sqrt(2.0) = 1.414 * Vs (a 41% increase in stalling speed).', 'Oxford ATPL Principles of Flight, Chapter 8 ''Manoeuvres''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-005', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'When flying into ground effect (within approximately one wingspan of the surface), which changes occur''', '["Induced drag increases and elevator authority is lost", "Induced drag decreases, effective lift increases, and the aircraft tends to float", "Parasite drag increases dramatically requiring more thrust", "Stall speed increases significantly"]'::jsonb, 1, 'The proximity of the ground restricts the vertical component of airflow, reducing downwash and wingtip vortex size. Induced drag drops significantly, increasing the lift-to-drag ratio and causing the aircraft to float.', 'Oxford ATPL Principles of Flight, Chapter 4 ''Ground Effect''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-006', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'What is the primary aerodynamic purpose of wing dihedral (wings angled upward from root to tip)''', '["To increase maximum takeoff weight", "To provide lateral (roll) stability", "To provide longitudinal (pitch) stability", "To reduce parasite drag in cruise"]'::jsonb, 1, 'Dihedral provides lateral stability. When the aircraft sideslips (rolls), the lower wing has a higher effective angle of attack than the higher wing, producing a restoring rolling moment that levels the wings.', 'Oxford ATPL Principles of Flight, Chapter 9 ''Stability''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-007', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'easy', 'In a four-stroke internal combustion aero-engine, what is the correct order of the operating strokes''', '["Compression, Intake, Exhaust, Power", "Intake, Compression, Power, Exhaust", "Intake, Power, Compression, Exhaust", "Power, Compression, Exhaust, Intake"]'::jsonb, 1, 'The Otto four-stroke cycle consists of: 1) Intake (fuel-air drawn in), 2) Compression (mixture compressed), 3) Power/Expansion (spark fires, burning expands), 4) Exhaust (burnt gases expelled).', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 1 ''Piston Engines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-008', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'Aviation piston engines use dual independent ignition systems primarily consisting of:', '["A car battery and two alternators", "Two engine-driven magnetos, each firing one of two spark plugs per cylinder, independent of the electrical system", "A single distributor firing four spark plugs in sequence", "Direct injection piezo-electric igniters powered by the busbar"]'::jsonb, 1, 'Aero piston engines use two independent magnetos (left and right), each powering one spark plug per cylinder. Magnetos are engine-driven permanent-magnet generators that operate completely independent of the aircraft battery.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 3 ''Ignition Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-009', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'Detonation in an aircraft piston engine is best defined as:', '["Ignition of the fuel-air charge prior to the normal spark event", "An uncontrolled, explosive burning of the remaining fuel-air charge ahead of the normal flame front", "Backfiring through the carburetor induction pipe due to lean mixture", "Normal rapid combustion at full takeoff power"]'::jsonb, 1, 'Detonation is the sudden explosive combustion of the end-gas ahead of the advancing flame front. It causes extreme cylinder head temperature and pressure spikes, potentially leading to catastrophic engine damage.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 2 ''Combustion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-010', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'hard', 'Pre-ignition differs from detonation in that pre-ignition is caused by:', '["Using fuel of too high an octane rating", "An incandescent hotspot (such as glowing carbon or overheated spark plug electrode) igniting the mixture before timed spark occurs", "Over-cooling the cylinder head during a descent", "Excessively rich fuel-to-air mixture"]'::jsonb, 1, 'Pre-ignition is the ignition of the fuel-air charge before the spark plug fires, caused by a local hot spot in the cylinder (overheated spark plug tip, carbon deposit, or cracked exhaust valve).', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 2 ''Combustion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-011', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'During a pre-flight magneto check at 1800 RPM, switching from BOTH to LEFT produces no drop in RPM. The most likely reason is:', '["The engine is running perfectly with zero magneto wear", "The right magneto P-lead (ground wire) is broken/disconnected, leaving the right magneto permanently LIVE", "The left magneto has failed completely", "The carburetor heat is stuck in the ON position"]'::jsonb, 1, 'If switching to one magneto produces no RPM drop, the P-lead on the other magneto is broken or disconnected. The other magneto remains ungrounded (hot/live) and keeps firing. This is an extreme safety hazard on the ground.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 3 ''Ignition Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-012', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'easy', 'Applying carburetor heat to an aircraft with an iced carburetor will initially cause:', '["An immediate increase in engine RPM and smoother running", "A further drop in RPM and possible engine roughness as ice melts, followed by an RPM rise once clear", "The engine to cut out permanently", "The cylinder head temperature to drop to zero"]'::jsonb, 1, 'When carburetor heat is applied, hot air is less dense, so the mixture richens and RPM drops slightly. As ice melts, water passes through the cylinders causing temporary roughness, before smooth operation returns at clear RPM.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 4 ''Fuel and Carburetion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-013', 'technical-general', 'technical-general-propellers', 'Propellers', 'easy', 'A constant-speed propeller automatically adjusts its blade pitch to maintain a constant:', '["Aircraft true airspeed (TAS)", "Engine RPM selected by the pilot via the propeller control", "Manifold pressure at all altitudes", "Exhaust gas temperature (EGT)"]'::jsonb, 1, 'A constant-speed propeller uses a hydraulic governor to automatically vary the blade pitch angle, maintaining the engine RPM selected by the pilot on the blue propeller pitch lever regardless of airspeed or throttle setting.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 7 ''Propellers''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-014', 'technical-general', 'technical-general-propellers', 'Propellers', 'medium', 'P-factor (asymmetric propeller blade effect) causes an aircraft to yaw to the left during high angle of attack flight (such as climb) because:', '["The ascending blade takes a bigger bite of air than the descending blade", "The descending blade operates at a higher effective angle of attack and produces more thrust than the ascending blade", "Propeller torque rolls the left wheel down on the runway", "Slipstream hits the left side of the rudder"]'::jsonb, 1, 'At high angles of attack, the propeller disc is tilted relative to relative airflow. The downward-moving blade on the right has a higher forward velocity and higher angle of attack, producing more thrust than the upward blade on the left, yawing the plane left.', 'Oxford ATPL Principles of Flight, Chapter 7 ''Propeller Effects''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-015', 'technical-general', 'technical-general-propellers', 'Propellers', 'hard', 'On a multi-engine aircraft with both propellers rotating clockwise (viewed from the cockpit), the ''critical engine'' is the:', '["Right engine, because its failure causes no asymmetric yaw", "Left engine, because its thrust line is closer to the fuselage than the right engine''s descending blade thrust line", "Engine closest to the fuel tanks", "Neither engine, because clockwise engines are symmetric"]'::jsonb, 1, 'The descending blade on the right engine produces thrust furthest from the aircraft centerline (longer moment arm). Failure of the left engine leaves the right engine operating with maximum asymmetric yaw moment, making the left engine critical.', 'Oxford ATPL Principles of Flight, Chapter 10 ''Multi-Engine Flight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-016', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'medium', 'In a hydraulic system, why is mineral-based fluid (such as MIL-PRF-5606) dyed red''', '["To indicate it is corrosive to aluminum", "For leak detection and to prevent accidental servicing with incompatible fluid types", "To lubricate actuator seals automatically", "To indicate it has boiled under high pressure"]'::jsonb, 1, 'Aviation hydraulic fluids are color-coded to prevent catastrophic cross-contamination: MIL-H-5606 (mineral) is dyed red; Skydrol (phosphate-ester synthetic) is dyed purple/green. Mixing them destroys system packings and seals.', 'Oxford ATPL Aircraft General Knowledge - Systems, Chapter 1 ''Hydraulics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-017', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'easy', 'What is the purpose of an aircraft electrical circuit breaker''', '["To boost voltage when the battery is weak", "To protect aircraft wiring and equipment from overheating and fire caused by excessive current (overload/short-circuit)", "To convert alternating current (AC) to direct current (DC)", "To ground the magnetos when shutting down the engine"]'::jsonb, 1, 'Circuit breakers protect wiring and electrical components from carrying excessive electrical current that could cause insulation melting, electrical fires, and equipment failure. They pop open automatically when rated current is exceeded.', 'Oxford ATPL Aircraft General Knowledge - Systems, Chapter 4 ''Electrics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-018', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'medium', 'An aircraft alternator failure in flight is normally first indicated by:', '["Immediate engine stoppage", "A zero or negative reading on the ammeter (discharge) and an annunciator warning light", "The airspeed indicator reading zero", "Loss of all hydraulic pressure"]'::jsonb, 1, 'Since the ignition system runs on magnetos, the engine continues running. The ammeter shows battery discharge (or zero output), and the low-voltage/alternator-fail warning illuminates as the battery takes over electrical loads.', 'Oxford ATPL Aircraft General Knowledge - Systems, Chapter 4 ''Electrics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-019', 'technical-general', 'technical-general-pitot-static-instruments', 'Pitot-Static Instruments', 'easy', 'Which flight instrument relies on BOTH pitot (ram) pressure and static pressure to operate''', '["Altimeter", "Vertical Speed Indicator (VSI)", "Airspeed Indicator (ASI)", "Turn Coordinator"]'::jsonb, 2, 'The Airspeed Indicator (ASI) measures dynamic pressure (ram pressure minus static pressure). The Altimeter and Vertical Speed Indicator connect to the static source only.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 1 ''Pitot-Static Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-020', 'technical-general', 'technical-general-pitot-static-instruments', 'Pitot-Static Instruments', 'medium', 'If the pitot tube ram pressure inlet is completely blocked by ice while the drain hole remains open, what will the Airspeed Indicator indicate''', '["It will freeze at the speed when blockage occurred", "The pressure bleeds out through the drain hole, causing the ASI to drop to zero", "It will over-read progressively as the aircraft climbs", "It will indicate maximum airspeed (Vne)"]'::jsonb, 1, 'If the ram air inlet is blocked while the drain hole is open, trapped pressure leaks out through the drain hole. The pressure inside the capsule drops to ambient static pressure, and the ASI indicates zero.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 1 ''Pitot-Static Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-021', 'technical-general', 'technical-general-pitot-static-instruments', 'Pitot-Static Instruments', 'hard', 'If BOTH the pitot tube ram inlet and drain hole are completely frozen shut, how will the Airspeed Indicator behave during a climb''', '["It will indicate zero", "It will act like an altimeter, over-reading as the aircraft climbs into lower ambient static pressure", "It will under-read as the aircraft climbs", "It will read constant regardless of attitude"]'::jsonb, 1, 'Trapped ram pressure remains constant in the capsule. As the aircraft climbs, ambient static pressure in the casing decreases, allowing the capsule to expand. The ASI acts like an altimeter and falsely over-reads.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 1 ''Pitot-Static Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-022', 'technical-general', 'technical-general-pitot-static-instruments', 'Pitot-Static Instruments', 'hard', 'If the static port becomes completely blocked while climbing to a higher altitude, what will the Altimeter and VSI indicate''', '["Altimeter will read zero; VSI will show maximum climb", "Altimeter freezes at the altitude where blockage occurred; VSI drops to zero after pressure equalizes", "Altimeter continues to read correctly; VSI over-reads", "Both instruments oscillate erratically"]'::jsonb, 1, 'Trapped static pressure holds the altimeter aneroid capsule fixed, freezing the altimeter at the altitude of blockage. In the VSI, calibrated leak capillary equalizes pressure between capsule and case, causing the VSI to read zero.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 1 ''Pitot-Static Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-023', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'easy', 'The two fundamental physical properties of a spinning gyroscope that enable aircraft flight instruments are:', '["Centrifugal force and gravitational attraction", "Rigidity in space (gyroscopic inertia) and precession", "Aerodynamic lift and drag", "Magnetic dip and variation"]'::jsonb, 1, 'The two fundamental properties of a gyroscope are: 1) Rigidity in space (the rotor maintains its spin axis orientation in inertial space), and 2) Precession (an applied force results in angular motion 90° ahead in the direction of rotation).', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 2 ''Gyroscopic Instruments''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-024', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'medium', 'The Attitude Indicator (Artificial Horizon) utilizes a gyro spinning in which plane to display pitch and roll''', '["Horizontal spin axis with vertical gimbals", "Vertical spin axis (spinning in the horizontal plane) with freedom in two gimbals", "Tilted 45 degrees to sense both yaw and roll", "Fixed single gimbal aligned with the longitudinal axis"]'::jsonb, 1, 'The Attitude Indicator rotor spins about a vertical axis (in the horizontal plane) supported by two gimbals, giving 3 degrees of freedom. This provides an earth-vertical reference against which aircraft pitch and roll attitudes are measured.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 2 ''Gyroscopic Instruments''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-025', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'medium', 'Apparent drift (apparent wander) in a Directional Gyroscope is caused by:', '["Friction in the gimbal bearings only", "The rotation of the Earth beneath the gyro spinning in space, equal to 15° per hour multiplied by sin(latitude)", "Magnetic fields from electrical wires in the cockpit", "Vibrations from the engine exhaust system"]'::jsonb, 1, 'A Directional Gyro maintains its axis in space while the Earth rotates 15° per hour beneath it. At the poles, apparent drift is 15°/hr * sin(90°) = 15°/hr. At the equator (sin 0° = 0), apparent drift is zero.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 2 ''Gyroscopic Instruments''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-026', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'medium', 'The Turn Coordinator differs from the older Turn and Slip Indicator because its gimbal is tilted approximately 30 degrees, allowing it to sense:', '["Pitch rate only", "Both rate of roll and rate of yaw", "Only rate of yaw (turn)", "Angle of bank directly in degrees"]'::jsonb, 1, 'The Turn Coordinator has its gyro gimbal tilted 30° up from horizontal, enabling it to sense both roll rate and yaw rate. The older Turn and Slip Indicator had a horizontal gimbal sensing yaw rate only.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 2 ''Gyroscopic Instruments''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-027', 'technical-general', 'technical-general-weight-balance', 'Weight & Balance', 'easy', 'What is the primary aerodynamic hazard of operating an aircraft with the Center of Gravity (CG) located aft of the approved aft limit''', '["Severely increased elevator control forces during landing flare", "Decreased longitudinal static stability, violent stall characteristics, and possible inability to recover from a stall or spin", "Excessive fuel consumption due to heavy nose-down trim", "Decreased cruise speed due to excessive tailplane download"]'::jsonb, 1, 'An aft CG reduces the tailplane arm and download requirement, drastically reducing longitudinal static stability. In extreme aft CG, the aircraft becomes dynamically unstable and may enter an unrecoverable flat spin.', 'Oxford ATPL Principles of Flight, Chapter 9 ''Weight and Balance / Stability''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-028', 'technical-general', 'technical-general-weight-balance', 'Weight & Balance', 'medium', 'Operating an aircraft with the Center of Gravity (CG) at its extreme forward limit results in:', '["Higher cruise speed and lighter control forces", "Higher stall speed, heavier elevator control forces, and difficulty in achieving full flare on landing", "Danger of unrecoverable spin", "Zero induced drag in straight and level flight"]'::jsonb, 1, 'A forward CG requires a larger down-load on the tailplane to balance the nose-heavy moment. The wings must produce more total lift, which increases stall speed, increases induced drag (reducing cruise speed), and demands high stick forces.', 'Oxford ATPL Principles of Flight, Chapter 9 ''Weight and Balance / Stability''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-029', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'easy', 'Calibrated Airspeed (CAS) is defined as Indicated Airspeed (IAS) corrected for:', '["Air density and altitude variations", "Compressibility error at high Mach numbers", "Instrument and position (installation) errors", "Wind speed and direction"]'::jsonb, 2, 'CAS is IAS corrected for position error (static port location turbulence and angle of attack) and instrument mechanical errors. Flight manuals provide CAS vs IAS correction tables.', 'Oxford ATPL Aircraft General Knowledge - Instrumentation, Chapter 1', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-030', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'medium', 'True Airspeed (TAS) equals Calibrated Airspeed (CAS) under which atmospheric conditions''', '["At any altitude as long as IAS is below 100 kt", "In standard ISA conditions at mean sea level (15°C, 1013.25 hPa, 1225 g/m³)", "At the absolute ceiling of the aircraft", "At FL180 in standard temperature"]'::jsonb, 1, 'TAS is the actual speed of the aircraft through the air mass: TAS = EAS / sqrt(relative density). At sea level in ISA, relative density = 1.0, so TAS equals EAS/CAS. At altitude, air is thinner so TAS is higher than CAS.', 'Oxford ATPL Principles of Flight / Navigation, Chapter ''Airspeeds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-031', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'easy', 'A pilot flying at a constant Calibrated Airspeed of 120 kt climbs from sea level to 10,000 ft in ISA. The True Airspeed (TAS) will:', '["Decrease by about 10%", "Remain exactly 120 kt", "Increase by approximately 2% per 1000 ft of altitude (reaching approx 144 kt)", "Increase to 200 kt"]'::jsonb, 2, 'Rule of thumb: TAS increases by approximately 1.5% to 2% per 1000 ft of altitude for a constant CAS. At 10,000 ft: 120 kt + (10 * 2%) = 120 * 1.20 = approx 144 kt.', 'Oxford ATPL General Navigation, Chapter ''Airspeed Conversions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-032', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'Exhaust Gas Temperature (EGT) is used by pilots of piston aircraft primarily to:', '["Monitor oil cooler efficiency", "Set and adjust the fuel-to-air mixture for best economy or best power", "Verify whether the cabin heater valve is open", "Determine the exact outside air temperature"]'::jsonb, 1, 'EGT measures the temperature of combustion gases exiting the cylinder. Peaking the mixture (chemically correct stoichiometric ratio) and leaning or richening relative to peak EGT allows precise fuel mixture management.', 'Oxford ATPL Aircraft General Knowledge - Powerplant, Chapter 4 ''Mixture Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-033', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'hard', 'Vapor lock in an aircraft fuel system is caused by:', '["Water accumulating in the fuel tank sumps freezing at low temperatures", "Fuel vaporizing prematurely in fuel lines due to high fuel temperature, low ambient pressure, or excessive suction, blocking liquid fuel flow", "Microbiological fungal growth in Jet-A1 tanks", "Excessive lead additives accumulating in fuel injectors"]'::jsonb, 1, 'Vapor lock occurs when high temperatures and/or low atmospheric pressures cause volatile fuel components to boil inside fuel lines. The resulting vapor bubble prevents the fuel pump from delivering liquid fuel to the engine.', 'Oxford ATPL Aircraft General Knowledge - Systems, Chapter 3 ''Fuel Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-034', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'medium', 'What is the primary function of the aircraft landing gear oleo-pneumatic strut''', '["To steer the aircraft on the ground only", "To absorb and dissipate landing impact shocks using compressed gas (nitrogen) and hydraulic fluid forced through an orifice", "To retract the landing gear after takeoff", "To cool the wheel brakes after landing"]'::jsonb, 1, 'An oleo strut absorbs landing loads: compressed nitrogen acts as a spring, while hydraulic oil forced through a metering orifice provides viscous damping, dissipating kinetic energy as heat without rebounding.', 'Oxford ATPL Aircraft General Knowledge - Systems, Chapter 2 ''Landing Gear''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-035', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'easy', 'Which flight control surface provides longitudinal control (pitch about the lateral axis)''', '["Ailerons", "Elevator (or Stabilator)", "Rudder", "Flaps"]'::jsonb, 1, 'The elevator controls pitch about the lateral axis (longitudinal control). Ailerons control roll about the longitudinal axis (lateral control). The rudder controls yaw about the normal/vertical axis (directional control).', 'Oxford ATPL Principles of Flight, Chapter 6 ''Flight Controls''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-001', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'easy', 'Vso is defined as the stalling speed or minimum steady flight speed in which configuration''', '["Clean configuration at maximum weight", "Landing configuration (flaps and gear extended)", "Cruise configuration at sea level", "Take-off configuration with flaps at first notch"]'::jsonb, 1, 'Vso is the stalling speed or minimum steady flight speed in the landing configuration (flaps fully extended, gear down). It corresponds to the lower end of the white arc on the airspeed indicator.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-002', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'easy', 'Vno is best described as which of the following''', '["Never-exceed speed", "Maximum structural cruising speed", "Best rate-of-climb speed", "Manoeuvring speed"]'::jsonb, 1, 'Vno is the maximum structural cruising speed. Flight above Vno should only be conducted in smooth air and with caution. It marks the upper limit of the green arc and the lower limit of the yellow arc on the ASI.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-003', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'medium', 'Va (manoeuvring speed) is significant because below this speed the aircraft:', '["Will not exceed its never-exceed speed in a dive", "Will stall before exceeding its limit load factor with a single full control input", "Can extend flaps without structural damage", "Achieves best glide ratio"]'::jsonb, 1, 'At or below Va, the wings will stall before the airframe can be overstressed by a single full (abrupt) control deflection. Va decreases as aircraft weight decreases because a lighter aircraft needs less lift and will stall at a lower speed.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-004', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'medium', 'Vx and Vy differ in that Vx gives best angle of climb while Vy gives best rate of climb. Which statement about their relationship at altitude is correct''', '["Vx and Vy converge as altitude increases, meeting at the aircraft absolute ceiling", "Vx remains constant while Vy decreases with altitude", "Vy remains constant while Vx increases with altitude", "Both Vx and Vy increase equally with altitude"]'::jsonb, 0, 'As altitude increases, excess power decreases more rapidly than excess thrust. Vy decreases and Vx increases slightly until they converge at the absolute ceiling where the aircraft can maintain level flight at only one airspeed.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-005', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'hard', 'Vfe refers to the maximum speed at which flaps may be extended. If a pilot inadvertently exceeds Vfe with flaps deployed, the primary structural risk is to which component''', '["Engine mounts due to increased drag loading", "Flap hinges, actuating mechanism, and wing flap attachment structure", "Landing gear doors due to airflow disruption", "Elevator trim tab"]'::jsonb, 1, 'Exceeding Vfe with flaps extended risks structural damage or failure of the flap hinges, actuating rods/screws, and the wing structure at the flap attachment points due to excessive aerodynamic loads on the flap surfaces.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-006', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'easy', 'On a standard airspeed indicator, the white arc represents which speed range''', '["Normal operating range from Vno to Vne", "Flap operating range from Vso to Vfe", "Caution range from Vno to Vne", "Best glide speed to never-exceed speed"]'::jsonb, 1, 'The white arc on the airspeed indicator represents the flap operating range. Its lower limit is Vso (stalling speed in landing configuration) and its upper limit is Vfe (maximum flap extended speed).', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-007', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'easy', 'The red radial line on the airspeed indicator represents:', '["Vno - maximum structural cruising speed", "Vne - never-exceed speed", "Vso - stall speed in landing configuration", "Va - manoeuvring speed"]'::jsonb, 1, 'The red radial line marks Vne, the never-exceed speed. Exceeding this speed risks structural failure due to flutter or overstress. It is placed at the top of the yellow arc.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-008', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'medium', 'The yellow arc (caution range) on the airspeed indicator lies between which two speeds''', '["Vs1 and Vso", "Vfe and Vne", "Vno and Vne", "Va and Vno"]'::jsonb, 2, 'The yellow arc (caution range) lies between Vno (maximum structural cruising speed) and Vne (never-exceed speed). Flight in this range is permitted only in smooth air and requires caution.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-009', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'medium', 'The green arc on the ASI represents the normal operating range. What are its lower and upper limits''', '["Vso to Vno", "Vs1 to Vno", "Vso to Vne", "Va to Vno"]'::jsonb, 1, 'The green arc spans from Vs1 (stalling speed in clean/cruise configuration, power off) at its lower end to Vno (maximum structural cruising speed) at its upper end. This is the normal operating range in smooth air.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-010', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'hard', 'On a multi-engine aircraft ASI, a blue radial line indicates:', '["Vmc - minimum control speed with critical engine inoperative", "Vyse - best rate-of-climb speed with one engine inoperative", "Vxse - best angle-of-climb speed with one engine inoperative", "Vsse - safe intentional one-engine inoperative speed"]'::jsonb, 1, 'The blue radial line on a multi-engine ASI marks Vyse, the best rate-of-climb speed with one engine inoperative (also called blue-line speed). It represents the optimum single-engine climb performance speed.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-011', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'easy', 'AVGAS 100LL used in piston aircraft is which color''', '["Red", "Green", "Blue", "Colorless"]'::jsonb, 2, 'AVGAS 100LL (100 octane, Low Lead) is dyed blue. The color coding helps pilots and fuellers identify the correct fuel type and avoid misfuelling.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-012', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'easy', 'Jet-A1 turbine fuel, when visually inspected, normally appears as which color''', '["Blue", "Green", "Straw/colorless (pale yellow)", "Red"]'::jsonb, 2, 'Jet-A1 is a kerosene-based turbine fuel that appears straw-colored or nearly colorless. Unlike AVGAS, it is not dyed with a distinctive color. Its density and smell differ markedly from AVGAS.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-013', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'medium', 'AVGAS 80 (grade 80/87) is identified by which color''', '["Blue", "Red", "Green", "Orange"]'::jsonb, 1, 'AVGAS Grade 80/87 is dyed red. It is a lower octane fuel suitable for engines with lower compression ratios. AVGAS 100 (non-low-lead) is dyed green, while 100LL is blue.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-014', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'hard', 'A pilot discovers that AVGAS 100LL has been accidentally loaded into an aircraft certified for AVGAS 80 only. The primary concern is:', '["Fuel will burn too lean causing engine roughness", "Higher lead content of 100LL may cause valve seat deposits and fouling over time, and the engine was not designed for it", "Fuel will vaporize at low altitudes causing vapor lock", "The blue dye will contaminate the fuel system filters"]'::jsonb, 1, 'While 100LL has adequate octane rating for lower-grade engines, its higher lead content (compared to AVGAS 80) can lead to lead fouling of spark plugs and valve seats over time. The engine manufacturer approval must be confirmed. Using an unapproved fuel grade is also a regulatory violation.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-015', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'easy', 'QNH is defined as the altimeter sub-scale setting that causes the altimeter to read:', '["Zero on the ground at any elevation", "Pressure altitude at the airfield", "Airfield elevation above mean sea level when on the ground", "Height above the standard datum of 1013.25 hPa"]'::jsonb, 2, 'QNH is the local altimeter setting adjusted so that the altimeter reads the aerodrome elevation (AMSL) when the aircraft is on the ground at that aerodrome. It allows aircraft to fly at altitudes referenced to mean sea level.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-016', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'medium', 'When climbing through the transition altitude, the pilot should change the altimeter setting from QNH to:', '["QFE of the destination aerodrome", "Standard pressure setting of 1013.25 hPa (29.92 inHg)", "QNH of the destination aerodrome", "Regional QNH"]'::jsonb, 1, 'At the transition altitude, climbing aircraft change from QNH to standard pressure (1013.25 hPa / 29.92 inHg). Above the transition layer, aircraft fly at Flight Levels referenced to standard pressure, ensuring uniform vertical separation.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-017', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'medium', 'QFE is the altimeter setting that causes the altimeter to indicate:', '["Elevation AMSL at the aerodrome", "Height above the aerodrome reference point (zero on the ground at the aerodrome)", "Density altitude at field elevation", "Flight level equivalent of field elevation"]'::jsonb, 1, 'QFE is set so that the altimeter reads zero (or aerodrome elevation if at a threshold) when the aircraft is on the ground at the reference point. It gives height above the aerodrome rather than altitude above sea level.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-018', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'hard', 'An aircraft on approach with QNH set will read altitude AMSL. If the actual atmospheric pressure is lower than the set QNH, the aircraft will be:', '["Higher than indicated - safe situation", "Lower than indicated - potentially dangerous", "At the correct altitude since QNH compensates automatically", "Unaffected, as pressure changes only affect TAS"]'::jsonb, 1, 'If the actual pressure is lower than set (cold or low-pressure air), the altimeter over-reads - the aircraft is actually lower than indicated. This is the basis of the memory aid: High to Low, Look Out Below. This is a safety-critical scenario during approaches.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-019', 'technical-specific', 'technical-specific-poh-sections', 'POH sections', 'easy', 'According to the standard POH/AFM structure (FAR Part 23 / EASA CS-23 format), which section contains emergency procedures''', '["Section 1", "Section 2", "Section 3", "Section 4"]'::jsonb, 2, 'The standard POH is divided into 9 sections. Section 3 is Emergency Procedures, which contains memory items, checklists for abnormal/emergency situations, and amplified procedures. Section 1 is General, Section 2 is Limitations, and Section 4 is Normal Procedures.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-020', 'technical-specific', 'technical-specific-poh-sections', 'POH sections', 'medium', 'A pilot needs to find the aircraft maximum certified takeoff weight and CG limits. This information is located in which POH section''', '["Section 4 - Normal Procedures", "Section 6 - Weight and Balance", "Section 2 - Limitations", "Section 7 - Airplane and Systems Description"]'::jsonb, 2, 'Section 2 (Limitations) contains all FAA/DGCA-approved operating limitations, including maximum takeoff weight, maximum landing weight, CG limits, airspeed limitations, engine limitations, and approved fuel types.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-021', 'technical-specific', 'technical-specific-poh-sections', 'POH sections', 'medium', 'Which section of the POH would a pilot consult to determine the aircraft useful load and to perform a weight and balance calculation''', '["Section 2 - Limitations", "Section 5 - Performance", "Section 6 - Weight and Balance", "Section 9 - Supplements"]'::jsonb, 2, 'Section 6 (Weight and Balance) contains equipment lists, loading graphs, moment/weight tables, and sample CG calculations. Pilots use this section to compute the loaded weight and confirm the CG is within limits before each flight.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-022', 'technical-specific', 'technical-specific-weight-limits', 'Weight limits', 'easy', 'Maximum ramp weight (maximum taxi weight) differs from maximum takeoff weight because it accounts for:', '["Fuel burn during flight to destination", "Fuel burned and oil consumed during engine start, taxi, and runup", "Passenger and baggage weight loaded at the terminal", "Structural limits applicable only on the ground"]'::jsonb, 1, 'Maximum ramp weight (also called maximum taxi weight) is slightly higher than maximum takeoff weight by the amount of fuel expected to be burned during engine start, taxi, and run-up. The aircraft must be at or below MTOW by the time it begins its takeoff roll.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-023', 'technical-specific', 'technical-specific-weight-limits', 'Weight limits', 'medium', 'An aircraft has a maximum zero fuel weight (MZFW) limitation. The purpose of this limit is to:', '["Prevent the aircraft from exceeding structural limits in turbulence when fuel is absent from the wing tanks", "Ensure the aircraft cannot take off with an empty fuel tank", "Limit the payload that can be carried on short sectors", "Prevent exceeding the maximum landing weight on arrival"]'::jsonb, 0, 'MZFW is the maximum weight of the aircraft without usable fuel. Fuel in the wing tanks relieves upward bending loads on the wing root. Without fuel (or with minimal fuel), bending loads on the wing root structure are highest, so MZFW limits the payload/structure combination to prevent overstress.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-024', 'technical-specific', 'technical-specific-performance-charts', 'Performance charts', 'medium', 'When using a takeoff distance performance chart, increasing pressure altitude while keeping all other variables constant will result in:', '["Shorter ground roll due to higher engine efficiency", "Longer ground roll because of reduced air density and engine power output", "No change because ASI reads the same IAS", "Shorter total distance because thinner air reduces drag"]'::jsonb, 1, 'At higher pressure altitudes, air density is lower. This reduces both engine power output and propeller/wing efficiency (aerodynamic performance). As a result, acceleration is lower and the aircraft needs more runway to reach the required airspeed for liftoff.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-025', 'technical-specific', 'technical-specific-performance-charts', 'Performance charts', 'hard', 'A performance chart gives a take-off distance of 800 m under standard conditions. The temperature is ISA+20. Using the approximation of 10% increase per 1000 ft density altitude increase above field elevation, and the density altitude is approximately 2000 ft above field elevation, the corrected distance is approximately:', '["960 m", "880 m", "800 m", "840 m"]'::jsonb, 0, 'A 2000 ft density altitude increase above the charted conditions gives approximately 2 x 10% = 20% increase in distance. 800 m x 1.20 = 960 m. This is a standard approximation method used when exact chart corrections are not available.', 'Generic POH / DGCA Flight Test Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-001', 'rtr', 'rtr-phonetic-alphabet', 'Phonetic alphabet', 'easy', 'In the ICAO phonetic alphabet, the letter W is represented by which word''', '["Washington", "Whiskey", "White", "Warsaw"]'::jsonb, 1, 'The ICAO phonetic alphabet word for W is Whiskey. The full alphabet is standardised in ICAO Doc 9432 and Annex 10 to ensure clarity in voice communications regardless of the speaker language background.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-002', 'rtr', 'rtr-phonetic-alphabet', 'Phonetic alphabet', 'easy', 'How is the number 9 pronounced in standard ICAO radiotelephony''', '["Nine", "Niner", "Nov-em-ber", "Nyne"]'::jsonb, 1, 'In ICAO radiotelephony, the digit 9 is pronounced NINER to avoid confusion with the German word nein (no) and similar words in other languages. Correct numeral pronunciation is specified in ICAO Doc 9432.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-003', 'rtr', 'rtr-phonetic-alphabet', 'Phonetic alphabet', 'medium', 'A pilot is asked to spell out the registration VT-KAB using the ICAO phonetic alphabet. The correct transmission is:', '["Victor Tango Kilo Alpha Bravo", "Victor Tango Kilo November Bravo", "Victor Tango Kilo Alfa Bravo", "Violet Tiger Kilo Alpha Bravo"]'::jsonb, 2, 'The ICAO phonetic word for A is Alfa (not Alpha - the spelling Alpha is not the official ICAO form). The correct transmission is Victor Tango Kilo Alfa Bravo. ICAO Doc 9432 specifies Alfa and Juliett as the standard spellings.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-004', 'rtr', 'rtr-readability-scale', 'Readability scale', 'easy', 'In ICAO standard radiotelephony, a readability of 5 means:', '["Unreadable", "Readable now and then", "Readable but with difficulty", "Perfectly readable"]'::jsonb, 3, 'The ICAO readability scale runs from 1 to 5: 1 = Unreadable, 2 = Readable now and then, 3 = Readable but with difficulty, 4 = Readable, 5 = Perfectly readable. A readability of 5 is the best possible signal quality report.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-005', 'rtr', 'rtr-readability-scale', 'Readability scale', 'medium', 'A controller responds to a pilot radio check with READABILITY 3. This means the pilot transmission is:', '["Perfectly readable", "Readable but with difficulty", "Readable now and then", "Unreadable"]'::jsonb, 1, 'Readability 3 on the ICAO scale means readable but with difficulty. The pilot should take corrective action (check microphone, adjust squelch, check frequency, or change position) to improve signal quality.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-006', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'easy', 'Which word is used in ICAO RTF to indicate that a message has been received and understood''', '["Copy", "Roger", "Wilco", "Affirmative"]'::jsonb, 1, 'ROGER means I have received all of your last transmission. It does not mean I will comply (that is WILCO - will comply). COPY and AFFIRMATIVE are not the standard ICAO terms for simple acknowledgement of receipt.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-007', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'easy', 'The word WILCO in ICAO RTF phraseology means:', '["I have received and understood your message", "I have received your message, will comply", "Wait, I must check with operations", "Your message is not understood"]'::jsonb, 1, 'WILCO (derived from will comply) means I have received your message, understand it, and will comply with it. It already implies receipt, so ROGER WILCO is redundant but sometimes used colloquially; WILCO alone is technically sufficient.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-008', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'medium', 'The phrase BREAK BREAK in RTF is used to indicate:', '["A separation between the address and the message of the same station", "An emergency transmission follows", "Separation between messages to different aircraft in a busy frequency", "The pilot is leaving the frequency temporarily"]'::jsonb, 2, 'BREAK BREAK is used to indicate a separation between messages addressed to different aircraft on the same frequency, especially when several messages are transmitted in sequence. BREAK (once) separates the address from the message text for the same station.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-009', 'rtr', 'rtr-atc-clearances-and-readback', 'ATC clearances and readback', 'medium', 'Which of the following items in an ATC clearance is MANDATORY to read back by the pilot''', '["Weather information and ATIS code", "Route clearance, assigned heading, altitude, and speed instructions", "Taxiway names during pushback", "Traffic information passed by ATC"]'::jsonb, 1, 'ICAO Annex 11 and Doc 4444 require mandatory readback of: ATC route clearances, runway-in-use, clearances to enter/land/take off/hold short of any active runway, heading instructions, altitude instructions, speed instructions, SSR transponder codes, and altimeter settings. Weather info and ATIS codes do not require readback.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-010', 'rtr', 'rtr-atc-clearances-and-readback', 'ATC clearances and readback', 'medium', 'A pilot reads back an ATC clearance incorrectly. The controller should respond with:', '["ROGER - the readback is accepted even if incorrect", "NEGATIVE, followed by the correct version of the instruction", "STANDBY and reissue after other traffic is handled", "CONFIRM - asking the pilot to re-read the original message"]'::jsonb, 1, 'If a readback is incorrect or incomplete, ATC must use the word NEGATIVE and immediately transmit the correct version. This is a safety-critical procedure to prevent misunderstandings from becoming operational errors.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-011', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'easy', 'The MAYDAY distress call is transmitted how many times at the beginning of a distress message''', '["Once", "Twice", "Three times", "Five times"]'::jsonb, 2, 'The distress call begins with MAYDAY MAYDAY MAYDAY spoken three times, as specified in ICAO Annex 10 and Doc 9432. The repetition ensures the call is recognised as a distress call even if the beginning is partially missed.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-012', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'easy', 'PAN-PAN (urgency) differs from MAYDAY (distress) primarily because:', '["PAN-PAN is used by ATC; MAYDAY is used only by pilots", "PAN-PAN indicates a serious situation requiring priority, but the aircraft is not in immediate danger of destruction", "PAN-PAN is used only on 121.5 MHz; MAYDAY on working frequency", "PAN-PAN requires a full position report; MAYDAY does not"]'::jsonb, 1, 'MAYDAY indicates a state of distress - grave and imminent danger requiring immediate assistance (e.g., engine failure with forced landing imminent). PAN-PAN indicates urgency - a serious and urgent situation that requires priority handling but is not immediately life-threatening (e.g., medical emergency, lost aircraft).', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-013', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'medium', 'The international aeronautical distress frequency on which all aircraft should monitor during flight (and on which ELTs transmit) is:', '["123.45 MHz", "121.5 MHz", "156.8 MHz", "243.0 MHz"]'::jsonb, 1, '121.5 MHz is the international VHF aeronautical emergency/distress frequency. ELTs (Emergency Locator Transmitters) transmit on both 121.5 MHz and 406 MHz. Aircraft are encouraged to monitor 121.5 MHz when on airways. 243.0 MHz is the military UHF guard frequency.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-014', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'hard', 'After transmitting a MAYDAY call, a pilot does not receive a response. What is the next correct action per ICAO procedures''', '["Cease transmitting to avoid blocking the channel", "Repeat the MAYDAY call on 121.5 MHz or any other available frequency", "Switch to squawk 7700 and only transmit on 243.0 MHz", "Transmit a PAN-PAN downgrade and await acknowledgement"]'::jsonb, 1, 'If a MAYDAY call goes unanswered on the current frequency, the pilot should repeat it on 121.5 MHz (international distress frequency) or attempt any other available frequency. Squawk 7700 should also be selected, but continued voice transmission attempts are essential.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-015', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'easy', 'The SSR transponder code 7700 indicates:', '["Radio communication failure", "Unlawful interference (hijack)", "General emergency", "VFR flight in uncontrolled airspace"]'::jsonb, 2, 'Squawk 7700 is the standard ICAO SSR code for general emergency. Squawk 7600 indicates radio communication failure (NORDO), and squawk 7500 indicates unlawful interference (hijacking). These codes are recognized worldwide and trigger immediate ATC alerts.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-016', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'easy', 'Which transponder code should a pilot squawk when experiencing radio communication failure (NORDO)''', '["7700", "7500", "7600", "2000"]'::jsonb, 2, 'Code 7600 is the ICAO designated SSR code for radio communication failure (NORDO - No Radio). It alerts ATC that the aircraft cannot communicate by voice. ATC will then apply NORDO procedures. Code 7700 is general emergency and 7500 is hijack.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-017', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'medium', 'An ATC instruction reads SQUAWK IDENT. The correct pilot action is:', '["Switch the transponder to STANDBY mode", "Press the IDENT button on the transponder to produce a special SPI pulse on radar", "Change the transponder code to the assigned squawk and press IDENT", "Set the transponder to Mode A only and confirm on radio"]'::jsonb, 1, 'When instructed to SQUAWK IDENT, the pilot presses the IDENT (Identification) button on the transponder. This triggers a Special Position Identification (SPI) pulse, causing the aircraft radar return to blossom on the controller screen for quick identification.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-018', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'medium', 'Transponder Mode C provides ATC with which additional information compared to Mode A''', '["Aircraft registration and flight number", "Pressure altitude of the aircraft", "GPS position of the aircraft", "Ground speed and heading"]'::jsonb, 1, 'Mode A transmits only the 4-digit squawk code for identification. Mode C additionally transmits the aircraft pressure altitude (derived from the transponder encoding altimeter or air data computer), enabling ATC to see the aircraft altitude on radar.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-019', 'rtr', 'rtr-frequency-management', 'Frequency management', 'easy', 'Before changing from one ATC frequency to another (when not instructed by ATC), the pilot should:', '["Change immediately to avoid delay", "Inform the current controller and obtain approval or acknowledgement before changing", "Switch without informing since radio is the pilot prerogative", "Squawk 7600 and then change frequency"]'::jsonb, 1, 'A pilot should always inform the current ATC unit before changing to another frequency, unless ATC has already instructed the change or it is an emergency. Unannounced frequency changes can result in loss of radio contact and are contrary to ICAO RTF procedures.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-020', 'rtr', 'rtr-frequency-management', 'Frequency management', 'medium', 'A pilot is instructed MONITOR 128.3. The correct action is:', '["Tune 128.3, call the station, and await a response", "Tune 128.3 and listen without making an initial call", "Continue on the current frequency and note 128.3 as backup", "Acknowledge on current frequency, tune 128.3, and call when ready"]'::jsonb, 1, 'MONITOR (frequency) means tune to the stated frequency and listen, but do not make an initial call. CONTACT (frequency) means tune and make an initial call. These are distinct standard ICAO instructions with different required actions.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-021', 'rtr', 'rtr-atis', 'ATIS', 'easy', 'ATIS stands for:', '["Automatic Terminal Information Service", "Air Traffic Identification System", "Aerodrome Traffic and Information Squawk", "Automatic Transponder Identification System"]'::jsonb, 0, 'ATIS stands for Automatic Terminal Information Service. It is a continuous broadcast of routine aerodrome meteorological and operational information on a dedicated frequency, updated regularly (typically every 30 minutes or when significant changes occur), and identified by a successive letter of the alphabet.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-022', 'rtr', 'rtr-atis', 'ATIS', 'medium', 'When making first contact with approach control after listening to ATIS information CHARLIE, the pilot should:', '["State the full ATIS message received to confirm awareness", "Mention INFORMATION CHARLIE in the initial call to indicate the ATIS has been received", "Ask for the latest ATIS as it may have changed", "Omit any reference to ATIS and wait for the controller to ask"]'::jsonb, 1, 'Pilots should include the ATIS identifier (e.g., INFORMATION CHARLIE) in their initial call to the ATC unit. This informs the controller that the pilot has the current ATIS information and does not need it repeated. If the ATIS has been updated, ATC will advise the pilot to obtain the new information.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-023', 'rtr', 'rtr-vhf-propagation-basics', 'VHF propagation basics', 'medium', 'VHF radio waves used in aviation communications travel primarily as:', '["Ground waves that follow the curvature of the Earth", "Sky waves reflected by the ionosphere", "Line-of-sight waves limited by the horizon", "Surface waves diffracted around terrain"]'::jsonb, 2, 'VHF (Very High Frequency, 30-300 MHz) signals propagate primarily by line-of-sight. They cannot follow the Earth curvature and are not significantly reflected by the ionosphere (unlike HF/MF). This limits VHF range to approximately line-of-sight between the aircraft and the ground station antenna.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-024', 'rtr', 'rtr-vhf-propagation-basics', 'VHF propagation basics', 'medium', 'A pilot flying at 1600 ft AGL notices VHF communication with a ground station 60 NM away is unreliable. The most likely reason is:', '["VHF frequency selected is outside the aviation band", "The aircraft is below the radio horizon for that range at its current altitude", "The transmitter is operating on a sky wave at this frequency", "Ionospheric absorption is highest during daytime at VHF"]'::jsonb, 1, 'VHF range is governed by line-of-sight. The radio horizon in nautical miles is approximately 1.23 times the square root of altitude in feet. At 1600 ft: 1.23 x sqrt(1600) = 1.23 x 40 = approximately 49 NM. The 60 NM station may therefore be beyond the radio horizon, causing unreliable reception.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-025', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'hard', 'When a pilot is uncertain of a received ATC clearance, the correct ICAO phraseology to request repetition of the last message is:', '["REPEAT LAST MESSAGE", "SAY AGAIN", "CONFIRM LAST TRANSMISSION", "RESTATE INSTRUCTIONS"]'::jsonb, 1, 'SAY AGAIN is the standard ICAO phraseology requesting repetition of all or part of a previous transmission. The word REPEAT is reserved for use by artillery and should not be used in aviation RTF to avoid confusion. Pilots should use SAY AGAIN ALL AFTER (phrase) or SAY AGAIN ALL BEFORE (phrase) for partial repetition.', 'ICAO Doc 9432 / DGCA RTR(A) Syllabus / Annex 10', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-051', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'A great circle has its northern vertex at 70 degrees N, 130 degrees E. Where is the southern vertex?', '["70 degrees S, 130 degrees W", "20 degrees S, 050 degrees W", "70 degrees N, 050 degrees W", "70 degrees S, 050 degrees W"]'::jsonb, 3, 'Opposite vertices are antipodal, so the latitude changes to 70 degrees S and longitude changes by 180 degrees to 050 degrees W.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-052', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'Using a semi-major axis of 6378.4 km and compression of 1/297, what is the approximate semi-minor axis?', '["6356.9 km", "6399.9 km", "6378.4 km", "6367.0 km"]'::jsonb, 0, 'The reduction is 6378.4 divided by 297, about 21.5 km, so the semi-minor axis is approximately 6356.9 km.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-053', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'Which datum is used for measuring latitude?', '["The prime meridian", "The equator", "The North Pole only", "The Greenwich anti-meridian"]'::jsonb, 1, 'Latitude is the angular distance north or south of the equatorial plane, so the equator is its datum.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-054', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'Where is the difference between geocentric and geodetic latitude greatest?', '["At the equator", "At both geographic poles", "At 23.5 degrees N and S", "Near 45 degrees N and S"]'::jsonb, 3, 'The difference is greatest near 45 degrees north and south, where it reaches about 11.6 minutes of arc.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-055', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'An aircraft moves from 165 degrees W to 103 degrees W. What is the shorter change of longitude?', '["62 degrees E", "62 degrees W", "268 degrees E", "268 degrees W"]'::jsonb, 0, 'The longitudes have the same name, so subtract to obtain 62 degrees; 103 degrees W lies east of 165 degrees W, giving 62 degrees E.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-056', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'An aircraft holds compass heading 355 degrees with deviation 2 degrees west and variation 6 degrees east. What is the true heading?', '["347 degrees T", "005 degrees T", "359 degrees T", "353 degrees T"]'::jsonb, 2, 'Compass plus deviation gives magnetic: 355 minus 2 is 353 degrees M. Magnetic plus easterly variation gives true: 353 plus 6 is 359 degrees T.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-057', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'True heading is 015 degrees, variation is 9 degrees west and deviation is 3 degrees east. What compass heading should the pilot steer?', '["009 degrees C", "021 degrees C", "027 degrees C", "003 degrees C"]'::jsonb, 1, 'Reverse the chain by subtracting the signed corrections. True minus westerly variation: 015 minus minus 9 is 024 degrees M. Then 024 minus 3 degrees easterly deviation is 021 degrees C.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-058', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'What is the reciprocal of a true direction of 353 degrees?', '["173 degrees T", "153 degrees T", "163 degrees T", "183 degrees T"]'::jsonb, 0, 'A reciprocal is 180 degrees away. Subtracting 180 from 353 gives 173 degrees T.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-059', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'What latitude resolution is implied by quoting a position to one decimal minute?', '["About 1 NM", "About 30 m", "About 3 m", "About 0.1 NM, or 185 m"]'::jsonb, 3, 'One decimal minute is 0.1 minute of great-circle arc, about 0.1 NM or 185 m along a meridian.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-060', 'air-navigation', 'air-navigation-the-earth-direction-and-position', 'The Earth, Direction and Position', 'medium', 'If a great circle has its southern vertex at 63 degrees S, 170 degrees W, where is its northern vertex?', '["63 degrees N, 170 degrees E", "27 degrees N, 010 degrees E", "63 degrees N, 010 degrees E", "63 degrees S, 010 degrees E"]'::jsonb, 2, 'The antipodal vertex has the opposite latitude name and a longitude 180 degrees away, giving 63 degrees N, 010 degrees E.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The Earth, Direction and Position''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-061', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'A meridian, considered from one pole to the other, is', '["a semi-great circle and a rhumb line", "a small circle only", "a complete great circle by itself", "neither a great circle nor a rhumb line"]'::jsonb, 0, 'A meridian is one half of a great circle and gives a constant north or south direction, so it is also a rhumb line.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-062', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'One minute of longitude represents one nautical mile', '["at every latitude", "only at 45 degrees latitude", "only at the Equator", "only at either pole"]'::jsonb, 2, 'One minute of longitude equals one nautical mile only at the Equator, where the parallel is itself a great circle.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-063', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'What is the exact ICAO value of one nautical mile?', '["1852 m", "1609 m", "2000 m", "6080 m"]'::jsonb, 0, 'The ICAO nautical mile is exactly 1852 metres. The traditional 6080 figure is in feet.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-064', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'How many feet are in one statute mile?', '["5000 ft", "6076 ft", "5280 ft", "6080 ft"]'::jsonb, 2, 'One statute mile is 5280 ft. It must not be confused with the traditional 6080 ft nautical mile.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-065', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'An aircraft flies from 72 degrees north, 002 degrees 30 minutes east to 72 degrees north, 177 degrees 30 minutes west by the shortest route. What is its initial true track?', '["090 degrees", "180 degrees", "270 degrees", "360 degrees"]'::jsonb, 3, 'The points lie on a meridian and anti-meridian. The shorter great-circle route initially goes north over the North Pole, so the initial track is 360 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-066', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'Relative to the corresponding great circle, a rhumb line between two ordinary points lies', '["on the polar side", "on the equatorial side", "on the same path in every case", "through the nearest pole"]'::jsonb, 1, 'The rhumb line lies on the equatorial side of the great circle, which bows towards the nearer pole.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-067', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'Two points on the same meridian are at 41 degrees 25 minutes north and 79 degrees 30 minutes north. Their separation is', '["1905 NM", "2135 NM", "2285 NM", "4232 NM"]'::jsonb, 2, 'The change of latitude is 38 degrees 05 minutes, equal to 2285 minutes of arc and therefore 2285 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-068', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'What is the great-circle distance between antipodal points on the spherical navigation model?', '["10 800 NM", "5400 NM", "21 600 NM", "18 000 NM"]'::jsonb, 0, 'Antipodes are separated by 180 degrees. Multiplying by 60 gives 10 800 NM, half the Earth''s 21 600 NM circumference.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-069', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'If the convergency between the end meridians is 14 degrees, the conversion angle is', '["14 degrees", "7 degrees", "28 degrees", "3.5 degrees"]'::jsonb, 1, 'Conversion angle is half the meridian convergency, so half of 14 degrees is 7 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-070', 'air-navigation', 'air-navigation-great-circles-and-rhumb-lines', 'Great Circles and Rhumb Lines', 'medium', 'Which statement about parallels of latitude is correct?', '["Every parallel is a great circle", "No parallel is a rhumb line", "Only the poles are small circles", "Every parallel except the Equator is a small circle and a rhumb line"]'::jsonb, 3, 'Every non-equatorial parallel is a small circle, and it is also a rhumb line because it cuts each meridian at 90 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Great Circles and Rhumb Lines''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-071', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'What is the angle of dip at the magnetic equator?', '["90 degrees", "0 degrees", "45 degrees", "180 degrees"]'::jsonb, 1, 'Dip is 0 degrees at the magnetic equator because the total field is horizontal there.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-072', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'Which equation correctly relates total force T, horizontal force H and vertical force Z?', '["T = H + Z", "H² = T² + Z²", "Z = T + H", "T² = H² + Z²"]'::jsonb, 3, 'The three forces form a right triangle, so the correct relationship is T² = H² + Z².', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-073', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'Which component of the Earth''s magnetic field supplies a heading compass with directive force?', '["The vertical component Z", "The horizontal component H", "The total force only", "The secular component"]'::jsonb, 1, 'The horizontal component H is the directive force that aligns the compass with the magnetic meridian.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-074', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'What does an agonic line join?', '["Places of zero variation", "Places of equal dip", "The geographic poles", "Places of maximum horizontal force"]'::jsonb, 0, 'An agonic line is the zero-value isogonal, so it joins places where magnetic variation is zero.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-075', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'A line joining places of equal magnetic dip is called', '["an isogonal", "an agonic line", "a magnetic meridian", "an isoclinal"]'::jsonb, 3, 'An isoclinal joins places of equal magnetic dip. Its zero-dip special case is the aclinic line.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-076', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'What is the maximum possible magnitude of magnetic dip?', '["45 degrees", "60 degrees", "90 degrees", "180 degrees"]'::jsonb, 2, 'Dip reaches 90 degrees at a magnetic pole, where the field is vertical.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-077', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'If H is 30 microteslas and Z is 40 microteslas, what is T?', '["50 microteslas", "70 microteslas", "35 microteslas", "10 microteslas"]'::jsonb, 0, 'Using T² = H² + Z² gives T = √(900 + 1600) = 50 microteslas.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-078', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'Which description best matches secular change?', '["The compass error caused by aircraft electrical equipment", "The daily cycle lasting about 24 hours", "A sudden receiver failure during a magnetic storm", "The slow long-term drift of the Earth''s main magnetic field"]'::jsonb, 3, 'Secular change is the slow long-term change of the main field, which moves poles and isogonals over years and decades.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-079', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'What does an isogonal join?', '["Places of equal magnetic dip", "Places of zero dip only", "Places of equal magnetic variation", "Places with equal geographic latitude"]'::jsonb, 2, 'An isogonal joins places of equal magnetic variation for the stated chart epoch.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-080', 'air-navigation', 'air-navigation-earth-magnetism', 'Earth Magnetism', 'medium', 'Why does a direct-reading magnetic compass become unreliable near a magnetic pole?', '["Total field T becomes zero", "Horizontal component H approaches zero", "Vertical component Z approaches zero", "Variation must always be zero"]'::jsonb, 1, 'Near a magnetic pole the field is nearly vertical, so the horizontal directive component H approaches zero and cannot establish a dependable heading.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Earth Magnetism''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-081', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'On which pair of headings is coefficient B normally corrected?', '["East and west", "North and south", "North-east and south-west", "Any two headings 30 degrees apart"]'::jsonb, 0, 'Coefficient B has its maximum semicircular effect on east and west headings, so those headings are used for its correction.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-082', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'Observed deviations are north +6 degrees and south minus 2 degrees. What is coefficient C?', '["minus 4 degrees", "+2 degrees", "+4 degrees", "+8 degrees"]'::jsonb, 2, 'C = (deviation north minus deviation south) divided by 2, so C = [6 minus (minus 2)] divided by 2 = +4 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-083', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'Which item is one of the aims of a compass swing?', '["To remove magnetic variation", "To record the residual deviation", "To align true north with grid north", "To calculate wind velocity"]'::jsonb, 1, 'A compass swing determines deviation, reduces correctable error and records the residual deviation on the aircraft compass card.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-084', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'In the northern hemisphere, acceleration on an easterly heading makes a direct compass show an apparent turn towards', '["east", "west", "south", "north"]'::jsonb, 3, 'In the northern hemisphere, acceleration on an east or west heading causes an apparent turn towards north.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-085', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'What does UNOS mean for a direct compass in the northern hemisphere?', '["Underread south, overread north", "Use north only for setting", "Undershoot north, overshoot south", "Uniform north and opposite south"]'::jsonb, 2, 'UNOS means undershoot north and overshoot south when rolling out using a direct magnetic compass in the northern hemisphere.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-086', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'At the magnetic equator, an aircraft accelerates on a westerly heading. What dip-induced indication should be expected?', '["No apparent turn", "An apparent turn north", "An apparent turn south", "A 90 degree compass swing"]'::jsonb, 0, 'There is no dip-induced acceleration error at the magnetic equator because the vertical field component and dip are zero.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-087', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'A direct compass described as aperiodic is one that', '["can indicate true heading directly", "has no liquid in its bowl", "requires no deviation card", "settles quickly without prolonged oscillation"]'::jsonb, 3, 'Aperiodic, or dead beat, means the disturbed magnet system settles quickly without continuing to oscillate.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-088', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'A bubble in the liquid of a direct compass most strongly suggests', '["a leaking seal", "excess horizontal field H", "a correct damping time", "a displaced agonic line"]'::jsonb, 0, 'A bubble commonly indicates a leaking seal and can move through the liquid, creating eddies that disturb the magnet assembly.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-089', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'Why is a remote magnetic detector commonly installed near a wingtip or fin?', '["To increase magnetic dip", "To reduce exposure to aircraft magnetic interference", "To make the aircraft turn faster", "To remove the need for electrical power"]'::jsonb, 1, 'A remote location is chosen because aircraft magnetic and electrical interference is normally smaller there.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-090', 'air-navigation', 'air-navigation-aircraft-magnetism-and-the-compasses', 'Aircraft Magnetism and the Compasses', 'medium', 'What does a slaved gyro magnetic compass combine?', '["True north with pressure altitude", "A direct compass with a wind vane", "Magnetic north-seeking with gyro stability", "Grid convergence with liquid damping"]'::jsonb, 2, 'The flux-valve reference supplies magnetic north-seeking, while the directional gyro supplies a stable short-term heading display.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Aircraft Magnetism and the Compasses''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-091', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'At the equator, a change of longitude of one minute corresponds to a departure of', '["60 NM", "1 kilometre", "zero", "1 NM"]'::jsonb, 3, 'At the equator cosine latitude is 1, so one minute of longitude gives 1 NM of departure.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-092', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'What is the departure between any two meridians measured exactly at a pole?', '["60 NM per degree", "Zero", "It equals the longitude difference", "It cannot be determined"]'::jsonb, 1, 'All meridians meet at each pole, so their east-west separation and departure are zero.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-093', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'At latitude 60 degrees, 600 NM of departure represents what change of longitude?', '["20 degrees", "10 degrees", "30 degrees", "5 degrees"]'::jsonb, 0, 'Change of longitude = 600 ÷ cos 60 degrees = 1,200 minutes, which is 20 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-094', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'An aircraft flies 165 km east at 60 degrees north. Approximately what change of longitude results?', '["1 degree 29 minutes", "5 degrees 56 minutes", "2 degrees 58 minutes", "8 degrees 54 minutes"]'::jsonb, 2, '165 km is about 89 NM. Dividing 89 by cos 60 degrees gives 178 minutes, or 2 degrees 58 minutes.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-095', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'A longitude difference of 44 degrees 11 minutes gives 2,000 NM departure. What is the latitude?', '["About 49 degrees north only", "About 41 degrees north or south", "About 30 degrees north or south", "About 60 degrees south only"]'::jsonb, 1, 'Cos latitude = 2,000 ÷ 2,651 = 0.7544, so the latitude is about 41 degrees north or south.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-096', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'For the same change of longitude, which statement is correct?', '["Departure is greatest near a pole", "Departure is independent of latitude", "Departure changes sign at the equator", "Departure decreases as latitude increases"]'::jsonb, 3, 'Departure varies with cosine latitude, so its magnitude decreases as a parallel lies farther from the equator.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-097', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'An aircraft flies 300 NM east at 45 degrees north, then later 300 NM west at 50 degrees north and returns to its original latitude. Relative to the start, it finishes', '["east of the starting meridian", "on the starting meridian", "west of the starting meridian", "at the opposite meridian"]'::jsonb, 2, 'The same distance at 50 degrees spans more longitude than at 45 degrees, so the westward longitude change is greater and the aircraft finishes west.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-098', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'A departure of 240 NM at 44 degrees south spans fixed meridians. What is the departure between them at 40 degrees south?', '["About 225 NM", "About 256 NM", "Exactly 240 NM", "About 288 NM"]'::jsonb, 1, 'Departure at 40 = 240 × cos 40 degrees ÷ cos 44 degrees = 255.6 NM, or about 256 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-099', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'From 58 degrees 33 minutes north, 174 degrees west, an aircraft flies exactly 6 NM east. What longitude is reached?', '["174 degrees 11.5 minutes west", "173 degrees 40 minutes west", "173 degrees 55 minutes west", "173 degrees 48.5 minutes west"]'::jsonb, 3, 'The longitude change is 6 ÷ cos 58 degrees 33 minutes = 11.5 minutes east, giving 173 degrees 48.5 minutes west.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-100', 'air-navigation', 'air-navigation-departure', 'Departure', 'medium', 'For a short 120 NM leg on track 060 degrees true, what is the eastward departure component?', '["About 104 NM", "60 NM", "120 NM", "About 208 NM"]'::jsonb, 0, 'Departure = distance × sin track = 120 × sin 60 degrees = 103.9 NM, which is about 104 NM east.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Departure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-101', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'At the equator, the convergency between two meridians is', '["zero", "equal to half their longitude difference", "equal to their longitude difference", "90 degrees"]'::jsonb, 0, 'The local directions of the meridians are parallel at the equator, so convergency is zero.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-102', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'At either geographic pole, earth convergency between two meridians is', '["always zero", "half the change of longitude", "equal to the change of longitude", "twice the change of longitude"]'::jsonb, 2, 'At a pole the meridians meet, and their included angle equals their change of longitude.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-103', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'Positions A and B differ by 12 degrees of longitude and have a mean latitude of 45 degrees north. Approximate convergency is', '["17.0 degrees", "6.0 degrees", "8.5 degrees", "12.0 degrees"]'::jsonb, 2, 'Convergency = 12 × sin 45 degrees = 8.5 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-104', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'A great-circle track changes by 5 degrees between points whose mean latitude is 39 degrees. The longitude difference is approximately', '["8 degrees", "3 degrees", "5 degrees", "12 degrees"]'::jsonb, 0, 'Change of longitude = 5 ÷ sin 39 degrees, which is approximately 8 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-105', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'Conversion angle between a great-circle direction and the matching rhumb-line direction equals', '["twice convergency", "convergency divided by longitude", "the full convergency", "half the convergency"]'::jsonb, 3, 'Conversion angle is exactly one half of earth convergency.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-106', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'From 30 degrees north, 020 degrees west to 30 degrees north, 020 degrees east, the rhumb-line track is 090 degrees true. The initial great-circle track is', '["100 degrees true", "080 degrees true", "090 degrees true", "070 degrees true"]'::jsonb, 1, 'Convergency is 20 degrees and conversion angle is 10 degrees, so the eastbound Northern Hemisphere great circle starts on 080 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-107', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'The initial great-circle track from A to B is 060 degrees true and convergency is 8.5 degrees in an eastbound Northern Hemisphere case. The initial great-circle track from B to A is', '["248.5 degrees true", "231.5 degrees true", "240.0 degrees true", "068.5 degrees true"]'::jsonb, 0, 'The track at B has increased to 068.5 degrees true; its reciprocal from B to A is 248.5 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-108', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'Three waypoints lie at 53 degrees north and are spaced by 10 degrees of longitude. Each great-circle leg has a conversion angle near 4 degrees. At the middle waypoint the track command changes by', '["4 degrees increase", "zero", "8 degrees decrease", "8 degrees increase"]'::jsonb, 2, 'The first leg ends near 094 degrees and the next begins near 086 degrees, giving an 8 degree decrease.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-109', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'A is at 55 degrees north on the prime meridian and B is at 54 degrees north, 010 degrees east. If the initial great-circle track from A is 100 degrees true, the approximate rhumb-line track is', '["096 degrees true", "104 degrees true", "100 degrees true", "108 degrees true"]'::jsonb, 1, 'Conversion angle is about 4 degrees, so the eastbound Northern Hemisphere rhumb-line track is 104 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-110', 'air-navigation', 'air-navigation-convergency-and-conversion-angle', 'Convergency and Conversion Angle', 'medium', 'A Southern Hemisphere route spans 16 degrees of longitude at a mean latitude of 42.5 degrees south. Approximate earth convergency is', '["5.4 degrees", "16.0 degrees", "8.0 degrees", "10.8 degrees"]'::jsonb, 3, 'Convergency = 16 × sin 42.5 degrees = approximately 10.8 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Convergency and Conversion Angle''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-111', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'If 1 centimetre on a chart represents 5 kilometres on Earth, the RF is', '["1:50,000", "1:5,000,000", "1:500,000", "1:185,200"]'::jsonb, 2, 'Five kilometres equals 500,000 centimetres, so the RF is 1:500,000.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-112', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'Five centimetres on a chart represents 7 nautical miles. The RF is closest to', '["1:1,296,400", "1:259,280", "1:92,600", "1:500,000"]'::jsonb, 1, 'Seven nautical miles is 1,296,400 centimetres; dividing by 5 gives an RF denominator of 259,280.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-113', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'Compared with a small-scale chart, a large-scale chart normally has', '["a larger denominator and less detail", "a smaller denominator and more detail", "the same denominator and more coverage", "a larger denominator and more coverage"]'::jsonb, 1, 'A large-scale chart has a numerically larger fraction, therefore a smaller denominator, and it shows more detail over less area.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-114', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'On a 1:5,000,000 chart, a line is 1.7 centimetres long. The Earth distance is approximately', '["8.5 NM", "17.0 NM", "85.0 NM", "45.9 NM"]'::jsonb, 3, 'The line represents 85 kilometres, which is approximately 45.9 nautical miles.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-115', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'A scale statement says 1 inch represents 10 nautical miles. The representative fraction is approximately', '["1:729,600", "1:60,800", "1:185,200", "1:1,000,000"]'::jsonb, 0, 'Ten nautical miles is 10 × 6,080 × 12 = 729,600 inches, giving 1:729,600.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-116', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'On a chart with RF 1:1,000,000, what chart length represents 50 kilometres?', '["50 cm", "0.5 cm", "5 cm", "1.97 cm"]'::jsonb, 2, 'Fifty kilometres is 5,000,000 centimetres; dividing by 1,000,000 gives 5 centimetres.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-117', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'On a 1:500,000 chart, the chart length representing 30 kilometres is', '["6 cm", "15 cm", "0.6 cm", "60 cm"]'::jsonb, 0, 'Thirty kilometres is 3,000,000 centimetres; dividing by 500,000 gives 6 centimetres.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-118', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'If 3 centimetres on a chart represents 200 statute miles, the RF is closest to', '["1:3,576,320", "1:2,000,000", "1:20,000,000", "1:10,728,960"]'::jsonb, 3, 'Converting 200 statute miles to centimetres and dividing by 3 gives a denominator of about 10,728,960.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-119', 'air-navigation', 'air-navigation-scale', 'Scale', 'medium', 'At RF 1:2,000,000, a chart line of 4.2 inches represents approximately', '["21.34 km", "106.68 km", "213.36 km", "426.72 km"]'::jsonb, 2, 'Earth distance = 4.2 × 2.54 × 2,000,000 centimetres = 213.36 kilometres.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-120', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'On a polar azimuthal projection, the graticule normally shows', '["parallel meridians and parallel latitudes", "curved meridians and straight latitudes", "parallel meridians and circular latitudes", "straight meridians radiating from the pole and concentric latitude circles"]'::jsonb, 3, 'A polar plane projection has straight radiating meridians and concentric circular parallels.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-121', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'A normal cylindrical graticule is characterised by', '["radiating meridians and concentric circles", "parallel straight meridians and parallel straight latitudes", "converging meridians and circular latitudes", "curved meridians and curved latitudes"]'::jsonb, 1, 'The normal cylindrical family opens into parallel straight meridians crossed by parallel straight latitudes.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-122', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'A typical conical graticule has', '["parallel meridians and equally spaced latitudes", "curved meridians and straight latitudes", "one meridian and one latitude only", "straight meridians converging towards an apex and parallels as circular arcs"]'::jsonb, 3, 'On a conical chart the meridians converge towards the cone apex and the parallels are arcs centred on it.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-123', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'Which ideal property cannot remain both constant and correct over an extensive flat chart?', '["Latitude labels", "Longitude labels", "Scale", "Chart colour"]'::jsonb, 2, 'Constant correct scale over a large flat chart is impossible; it can be exact only at selected points or lines.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-124', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'An orthomorphic or conformal chart is one on which', '["all areas are correct", "local angles and bearings are represented correctly", "scale is constant worldwide", "every great circle and rhumb line is straight"]'::jsonb, 1, 'Conformality preserves local angles, allowing chart bearings to match directions on Earth.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-125', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'The first condition for conformality is that', '["meridians and parallels intersect at 90 degrees", "all parallels are equally spaced", "all meridians are parallel", "areas remain exactly proportional"]'::jsonb, 0, 'A conformal graticule must preserve the right-angle crossing of meridians and parallels.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-126', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'The second condition for conformality requires scale at a point to', '["be exactly 1:1,000,000", "increase only northwards", "be equal in every direction or change equally in every direction", "remain constant over the whole chart"]'::jsonb, 2, 'At one point, directional scale must match, or change at the same rate in every direction.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-127', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'Which statement correctly distinguishes projection construction?', '["All operational charts are direct photographs", "All projections must use a physical light source", "Non-perspective means the chart has no graticule", "Perspective uses geometric rays, while non-perspective construction is mathematical or mathematically modified"]'::jsonb, 3, 'Perspective construction uses projection rays; non-perspective charts are produced or corrected mathematically.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-128', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'Which pair belongs to the navigation requirements of an ideal chart?', '["Straight rhumb lines and straight great circles", "Correct political boundaries and colours", "Equal areas and constant rainfall", "A single worldwide RF and no graticule"]'::jsonb, 0, 'An ideal navigation chart would show both rhumb lines and great circles as straight lines.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-129', 'air-navigation', 'air-navigation-general-chart-properties', 'General Chart Properties', 'medium', 'On a secant conical projection, scale is normally correct along', '["the equator only", "two standard parallels", "every meridian", "the cone apex"]'::jsonb, 1, 'A secant cone cuts the reduced Earth along two standard parallels, where scale is correct.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''General Chart Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-130', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'On a normal Mercator, meridians are', '["straight, parallel and equally spaced", "straight and convergent", "curved towards the pole", "parallel but increasingly spaced"]'::jsonb, 0, 'Mercator meridians are straight parallel lines with equal spacing.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-131', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'How are parallels of latitude shown on a normal Mercator?', '["As concentric circles", "As equally spaced straight lines", "As straight parallel lines whose spacing increases towards the poles", "As curves concave to the equator"]'::jsonb, 2, 'Mercator parallels are straight and parallel, with their separation increasing poleward.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-132', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'A rhumb line on a Mercator chart is represented by', '["a curve concave to the equator", "a curve convex to the equator", "a complex curve except at low latitude", "a straight line"]'::jsonb, 3, 'A straight line cuts every parallel Mercator meridian at the same angle, so it is a rhumb line.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-133', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'On a direct Mercator, great circles are shown as', '["straight lines only", "straight lines for the equator and meridians, but curves for all others", "curves only", "rhumb lines at every latitude"]'::jsonb, 1, 'The equator and meridians are straight great circles; every other great circle appears curved.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-134', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'Apart from the equator and meridians, a great circle on Mercator is a curve', '["concave to the nearer pole", "always concave northwards", "concave to the equator", "with no fixed relationship to the equator"]'::jsonb, 2, 'The Mercator great-circle curve is concave to the equator and lies poleward of the corresponding rhumb line.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-135', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'Chart convergence on a normal Mercator is', '["zero everywhere", "equal to Earth convergency", "correct at every latitude", "equal to longitude change"]'::jsonb, 0, 'Mercator meridians are parallel, so their chart convergence is zero everywhere.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-136', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'Mercator conformality means that the chart preserves', '["equal areas", "local angles and bearings", "one constant scale worldwide", "the true shape of continents"]'::jsonb, 1, 'A conformal Mercator preserves local angles and therefore locally correct bearings.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-137', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'Why can the geographic poles not be shown on a normal Mercator?', '["Scale and latitude spacing become infinite as latitude approaches 90 degrees", "The equator blocks the projection rays", "The meridians stop at 80 degrees", "The chart becomes equal-area"]'::jsonb, 0, 'Mercator scale and parallel spacing grow without limit towards 90 degrees, placing the poles at infinity.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-138', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'Compared with the equator, Mercator scale at 60 degrees latitude is', '["half as large", "unchanged", "about 1.5 times as large", "twice as large"]'::jsonb, 3, 'Relative Mercator scale is secant latitude; sec 60 degrees equals 2.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-139', 'air-navigation', 'air-navigation-mercator-charts-properties', 'Mercator Charts: Properties', 'medium', 'The rhumb-line track from Turin to Khartoum is 145 degrees true. With a conversion angle of 6 degrees, the initial great-circle track at Turin is', '["151 degrees true", "145 degrees true", "139 degrees true", "133 degrees true"]'::jsonb, 2, 'The Northern Hemisphere south-eastbound great circle starts poleward of the rhumb line, giving 145 minus 6 = 139 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Properties''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-140', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'The scale at 52 degrees south is 1:2,000,000. The approximate equatorial scale is', '["1:1,232,000", "1:3,249,000", "1:2,000,000", "1:4,000,000"]'::jsonb, 1, 'The equatorial denominator is 2,000,000 divided by cos 52 degrees, approximately 3,249,000.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-141', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'Moving poleward on a normal Mercator causes', '["scale to contract and the RF denominator to fall", "scale to remain fixed", "scale to expand and the RF denominator to rise", "scale to expand and the RF denominator to fall"]'::jsonb, 3, 'Mercator scale expands poleward, which means the representative-fraction denominator falls.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-142', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'The scale is 1:2,000,000 at 54 degrees south. At 25 degrees north it is approximately', '["1:1,121,000", "1:2,000,000", "1:3,084,000", "1:3,825,000"]'::jsonb, 2, 'Using the cosine ratio gives a denominator of about 3,083,806, so 1:3,084,000 is correct.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-143', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'A short distance on a Mercator chart should be measured against', '["latitude graduations at the mid-latitude of the leg", "longitude graduations at the start", "longitude graduations at the equator", "latitude graduations at the nearest pole"]'::jsonb, 0, 'Use the graduated meridian at the leg''s mid-latitude because that represents the appropriate local scale.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-144', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'Why must longitude graduations not be used as a general distance scale?', '["Meridians are curved", "Longitude is measured in radians", "Latitude spacing never changes", "One minute of longitude equals one NM only at the equator"]'::jsonb, 3, 'A minute of longitude represents one nautical mile only on the equator, so longitude graduations are not a general distance scale.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-145', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'The chart distance between the same two meridians on a normal Mercator', '["reduces towards the poles", "is the same at every latitude", "increases with cosine latitude", "is zero at the equator"]'::jsonb, 1, 'Mercator meridians are parallel and equally spaced, so their chart separation is constant with latitude.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-146', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'On a Mercator, 160 east to 160 west measures 30 cm. At 30 degrees south, the scale is approximately', '["1:6,416,000", "1:14,816,000", "1:24,000,000", "1:12,831,000"]'::jsonb, 3, 'The 40 degree departure at 30 degrees south is about 2,078 NM, giving an RF of about 1:12,831,000.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-147', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'A normal Mercator remains within about 1 percent of equatorial scale to', '["30 degrees north and south", "8 degrees north and south", "45 degrees north and south", "60 degrees north and south"]'::jsonb, 1, 'The practical one-percent band extends roughly 8 degrees, or about 480 to 500 NM, each side of the equator.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-148', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'On a secant Mercator, scale is exactly correct', '["along the two standard parallels", "only at the equator", "at every latitude", "only at the poles"]'::jsonb, 0, 'A secant Mercator is correct in scale along its two standard parallels.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-149', 'air-navigation', 'air-navigation-mercator-charts-scale', 'Mercator Charts: Scale', 'medium', 'Meridians 5 degrees apart measure 8 cm at 60 degrees north. The Mercator scale is nearest', '["1:1,736,000", "1:6,945,000", "1:3,500,000", "1:12,000,000"]'::jsonb, 2, 'Five degrees of longitude at 60 degrees is 150 NM; over 8 cm this gives approximately 1:3,472,500, nearest 1:3,500,000.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Mercator Charts: Scale''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-150', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'For a Lambert chart whose parallel of origin is 45 degrees north, the constant of the cone is approximately', '["0.500", "0.866", "0.707", "1.000"]'::jsonb, 2, 'The cone constant is sine 45 degrees, which is approximately 0.707.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-151', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'With n equal to 0.707, a change of longitude of 100 degrees gives chart convergence of', '["141.4 degrees", "70.7 degrees", "50.0 degrees", "7.07 degrees"]'::jsonb, 1, 'Chart convergence is longitude change multiplied by n, so 100 × 0.707 = 70.7 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-152', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'On a Lambert conformal chart, scale is exactly correct at', '["the two standard parallels", "the parallel of origin only", "every parallel", "the upper edge only"]'::jsonb, 0, 'The two circles where the modified cone intersects the reduced Earth are the standard parallels of correct scale.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-153', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'How does Lambert scale behave between and outside its standard parallels?', '["Expanded between and contracted outside", "Correct everywhere", "Constant between and zero outside", "Contracted between and expanded outside"]'::jsonb, 3, 'Lambert scale is contracted between the standard parallels and expanded outside them.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-154', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'The parallel of origin on a Lambert chart', '["is always the equator", "defines the cone constant and normally lies halfway between the standard parallels", "is the only line of correct scale", "is the upper standard parallel"]'::jsonb, 1, 'The parallel of origin is normally midway between the standard parallels and its sine defines n.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-155', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'Under the one-sixth rule, the standard parallels are placed', '["together at the centre of the sheet", "at the top and bottom edges", "one sixth of the sheet in from the top and bottom", "one sixth of a degree apart"]'::jsonb, 2, 'The one-sixth rule places each standard parallel about one sixth of the sheet height in from its nearest edge.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-156', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'A Lambert chart has standard parallels at 63 degrees north and 41 degrees north. Its cone constant is nearest', '["0.891", "0.656", "0.788", "0.707"]'::jsonb, 2, 'The parallel of origin is 52 degrees north and sin 52 degrees is approximately 0.788.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-157', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'Standard parallels are 41 degrees 20 minutes north and 11 degrees 40 minutes north. The cone constant is nearest', '["0.660", "0.446", "0.202", "0.895"]'::jsonb, 1, 'Their midpoint is 26 degrees 30 minutes north; sin 26 degrees 30 minutes is approximately 0.446.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-158', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'Lambert''s conformal conic is', '["perspective and equal-area", "perspective and non-conformal", "cylindrical and perspective", "non-perspective and conformal"]'::jsonb, 3, 'Lambert''s chart is a mathematically modified, non-perspective, conformal conic projection.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-159', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-1', 'Lambert''s Conformal Chart: Part 1', 'medium', 'Lambert conformal charts are especially suitable for', '["mid-latitude aeronautical route and plotting charts", "a single world chart including both poles", "equatorial marine rhumb-line navigation only", "measuring exact global areas"]'::jsonb, 0, 'Their conformality, near constant scale and near-straight great circles suit mid-latitude aviation charting.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 1''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-160', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'The difference between a rhumb-line direction and the corresponding great-circle direction is', '["half Earth convergency", "full chart convergence", "half chart convergence", "the cone constant"]'::jsonb, 0, 'Conversion angle is half Earth convergency and separates the rhumb line from the great circle.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-161', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'On Lambert, the difference between a rhumb line and a straight chart line is', '["full Earth convergency", "conversion angle only", "the latitude difference", "half chart convergence"]'::jsonb, 3, 'A Lambert straight line differs from the rhumb-line direction by half chart convergence at an endpoint.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-162', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'Except at the parallel of origin, a great circle on Lambert appears as', '["a curve concave to the pole", "a shallow curve concave to the parallel of origin", "a straight rhumb line", "a curve concave to the equator in every case"]'::jsonb, 1, 'The Lambert great circle is a shallow curve concave to the parallel of origin.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-163', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'Apart from meridians, rhumb lines on a Lambert chart are', '["straight", "curved towards the equator", "concentric circles", "curves concave to the pole of projection"]'::jsonb, 3, 'Lambert rhumb lines, except meridians, curve concave to the pole of projection.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-164', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'At the mid-meridian of a Lambert route, the straight line, great circle and rhumb line are', '["separated by full chart convergence", "at right angles", "parallel to one another", "equal only on a Mercator"]'::jsonb, 2, 'The three route representations are parallel at the mid-meridian.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-165', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'A Lambert straight line from A to B measures 250 degrees true at A and chart convergence is 6 degrees north. The rhumb-line track is', '["247 degrees true", "253 degrees true", "244 degrees true", "256 degrees true"]'::jsonb, 0, 'Half chart convergence is 3 degrees, so the rhumb line is 250 minus 3 = 247 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-166', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'Distance on a Lambert chart should normally be measured using', '["longitude graduations at the chart edge", "the equatorial scale only", "the convergency factor", "latitude graduations along a suitable meridian"]'::jsonb, 3, 'A graduated meridian supplies the latitude scale, with one minute of latitude representing one nautical mile.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-167', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'A true VOR bearing plotted on Lambert should be referenced to', '["the VOR station''s meridian", "the aircraft''s meridian", "the mid-meridian only", "a parallel of latitude"]'::jsonb, 0, 'VOR bearing is established at the ground station, so it is plotted from the station''s meridian using variation at the station.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-168', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'An aircraft heads 330 degrees true and observes an NDB at relative bearing 090 degrees. The reciprocal position line through the NDB is plotted as', '["060 degrees from the NDB meridian", "240 degrees from a line parallel to the aircraft''s meridian", "243 degrees from the aircraft position", "270 degrees from the mid-meridian"]'::jsonb, 1, 'The bearing to the NDB is 060 degrees true, so its reciprocal is 240 degrees plotted from a transferred aircraft meridian through the NDB.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-169', 'air-navigation', 'air-navigation-lambert-s-conformal-chart-part-2', 'Lambert''s Conformal Chart: Part 2', 'medium', 'On a Lambert chart n is 0.80. Initial straight-line track is 070 degrees true and rhumb-line track is 082 degrees true. From 4 degrees west, the destination longitude is', '["34 degrees west", "11 degrees east", "26 degrees east", "15 degrees east"]'::jsonb, 2, 'The 12 degree track difference is half chart convergence; full convergence is 24 degrees, giving 30 degrees of longitude and destination 26 degrees east.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Lambert''s Conformal Chart: Part 2''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-170', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'Polar stereographic scale away from the pole varies approximately as', '["secant squared of half the co-latitude", "secant latitude", "cosine of co-latitude", "sine of mean latitude"]'::jsonb, 0, 'The polar scale factor is sec² of half the co-latitude.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-171', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'Polar stereographic scale remains within about 1 percent of polar scale from the pole to', '["70 degrees latitude", "78 degrees latitude", "60 degrees latitude", "45 degrees latitude"]'::jsonb, 1, 'The scale is within about 1 percent between 90 and 78 degrees latitude.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-172', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'On a polar stereographic chart, chart convergence between two meridians equals', '["longitude change times cosine latitude", "half the longitude change", "the full change of longitude", "zero"]'::jsonb, 2, 'The polar convergence factor n is 1, so chart convergence equals the full longitude difference.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-173', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'On a polar stereographic, the initial straight-line track from 75 north 60 west to 75 north 60 east is', '["030 degrees true", "090 degrees true", "120 degrees true", "330 degrees true"]'::jsonb, 0, 'The meridians differ by 120 degrees and form an isosceles polar triangle, leaving a 30 degree initial track angle.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-174', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'Grid navigation is used at high latitude mainly because', '["parallels become straight", "local True North changes rapidly as converging meridians are crossed", "scale becomes exactly zero", "magnetic variation is always constant"]'::jsonb, 1, 'Rapid meridian convergence rotates local True North, while parallel grid lines provide a fixed direction datum.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-175', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'On a standard North Polar grid, the convergence at 45 degrees west is', '["45 degrees west", "zero", "90 degrees east", "45 degrees east"]'::jsonb, 3, 'North Polar standard-grid convergence has the longitude''s magnitude and the opposite east or west name, giving 45 degrees east.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-176', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'A grid direction of 105 degrees with convergence 20 degrees west converts to true direction', '["125 degrees", "085 degrees", "105 degrees", "145 degrees"]'::jsonb, 0, 'With west convergence, true is greater than grid, so 105 plus 20 gives 125 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-177', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'Grivation is the algebraic sum of', '["deviation and drift", "grid track and heading", "Earth rate and transport wander", "variation and convergence"]'::jsonb, 3, 'Grivation combines magnetic variation and grid convergence algebraically.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-178', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'Grid heading is 090 degrees and grivation is 20 degrees east. The corresponding magnetic heading is', '["110 degrees", "090 degrees", "070 degrees", "250 degrees"]'::jsonb, 2, 'From Grid to Magnetic, east grivation is subtracted, giving 090 minus 20 = 070 degrees magnetic.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-179', 'air-navigation', 'air-navigation-polar-stereographic-and-grid-navigation', 'Polar Stereographic and Grid Navigation', 'medium', 'When a directional gyro is used for grid steering, the normal treatment is to', '["correct transport wander but ignore Earth rate", "correct Earth rate but not normal transport wander", "ignore both Earth rate and real drift", "slave it continuously to Magnetic North"]'::jsonb, 1, 'The gyro is aligned to Grid North and corrected for Earth rate; normal transport-wander correction is not applied because the grid is fixed.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Polar Stereographic and Grid Navigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-180', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'A Maximum Elevation Figure shown in a grid square should be treated as', '["a mandatory cruising altitude", "an aerodrome circuit altitude", "a pressure altitude", "terrain and obstacle information, not automatically a safe altitude"]'::jsonb, 3, 'A Maximum Elevation Figure reports the dominant elevation under the chart''s stated method; it is not automatically a safe altitude.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-181', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'To interpret an airspace boundary correctly, the pilot must read', '["only its colour", "only its line thickness", "its symbol, label, vertical limits and effective details", "only the nearest navigation aid"]'::jsonb, 2, 'The complete meaning comes from the boundary symbol together with its label, vertical limits and effective details.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-182', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'Which feature is normally the most useful precise visual checkpoint?', '["a large motorway junction", "a long featureless beach", "a broad area of forest", "one village among many similar villages"]'::jsonb, 0, 'A large motorway junction is conspicuous, accurately positioned and usually more unique than the other choices.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-183', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'Reading map to ground is the normal method when the aircraft is', '["known to be lost", "inside cloud", "near planned track and time", "using only radio navigation"]'::jsonb, 2, 'When near track and time, map to ground predicts what should appear next and directs the outside search.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-184', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'When position is uncertain, ground to map means', '["turning the chart upside down", "following a road without identifying it", "ignoring the planned route", "matching an observed arrangement of features to the chart"]'::jsonb, 3, 'Ground to map starts with a distinctive observed pattern and searches for that same arrangement on the chart.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-185', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'At a groundspeed of 150 kt, the aircraft travels how far in 6 minutes?', '["10 NM", "15 NM", "25 NM", "90 NM"]'::jsonb, 1, 'Six minutes is one tenth of an hour, so 150 divided by 10 gives 15 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-186', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'Two line features crossed approximately at right angles to track are especially useful for', '["compass swinging", "altitude selection", "timing and groundspeed checks", "magnetic variation measurement"]'::jsonb, 2, 'The known chart distance between transverse line features can be compared with elapsed time to check groundspeed.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-187', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'As visual navigation altitude increases, which change is generally expected?', '["all charted masts become easier to see", "near hills always hide more of the horizon", "small details gain contrast", "a wider pattern is visible but small vertical features lose prominence"]'::jsonb, 3, 'Greater altitude widens the view, while small masts and local vertical relief become less prominent.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-188', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'Which factor can substantially change the visual contrast of a checkpoint?', '["The chart projection alone", "Season, light and weather", "The radio frequency selected", "The compass deviation card"]'::jsonb, 1, 'Season, light and weather can change colour, shadow, water extent and surface appearance.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-189', 'air-navigation', 'air-navigation-topographical-maps-and-map-reading', 'Topographical Maps and Map Reading', 'medium', 'Before using a printed aeronautical chart, the pilot should first ensure that', '["its edition and operational information are current", "every symbol is memorised without the legend", "all towns are overflown", "only the magnetic variation is checked"]'::jsonb, 0, 'The chart edition and operational information must be current through the applicable aeronautical information and NOTAM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Topographical Maps and Map Reading''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-190', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'Viewed from the North Celestial Pole, Earth moves around the Sun', '["clockwise in an ellipse", "anticlockwise in an ellipse", "clockwise in a circle", "anticlockwise in a circle"]'::jsonb, 1, 'Viewed from above the North Celestial Pole, Earth follows its elliptical orbit anticlockwise.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-191', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'The principal cause of the seasons is', '["the changing equation of time", "the Moon''s orbit", "Earth''s distance from the Sun", "the inclination of Earth''s axis"]'::jsonb, 3, 'The seasons result mainly from the approximately 23.5 degree inclination of Earth''s axis from the normal to its orbital plane.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-192', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'The angle between the ecliptic and the equinoctial is approximately', '["23.5 degrees", "45 degrees", "66.5 degrees", "90 degrees"]'::jsonb, 0, 'The obliquity of the ecliptic is approximately 23.5 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-193', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'At the Southern Hemisphere winter solstice, the Sun''s declination is approximately', '["23.5 degrees south", "zero", "23.5 degrees north", "66.5 degrees north"]'::jsonb, 2, 'Southern Hemisphere winter occurs near the June solstice, when solar declination is about 23.5 degrees north.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-194', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'Compared with an apparent solar day, a sidereal day is', '["longer by about 4 minutes", "exactly equal", "longer by one hour", "shorter by about 4 minutes"]'::jsonb, 3, 'A sidereal day is about 23 hours 56 minutes, roughly 4 minutes shorter than a mean or typical apparent solar day.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-195', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'A mean solar day is', '["one orbit measured against a star", "the annual average of apparent solar days", "the shortest apparent solar day", "the interval between two solstices"]'::jsonb, 1, 'The mean solar day is the average length of apparent solar days over the year and is fixed at 24 hours.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-196', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'The maximum difference between mean time and apparent solar time is about', '["4 minutes", "8 minutes", "30 minutes", "16 minutes"]'::jsonb, 3, 'Oxford gives the largest equation of time difference as about 16 minutes in mid November.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-197', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'The tropical year is approximately', '["360 days", "365 days exactly", "365 days 5 hours 48.75 minutes", "365 days 6 hours"]'::jsonb, 2, 'The tropical year, measured by the seasonal cycle, is about 365 days 5 hours 48.75 minutes.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-198', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'Greenwich Hour Angle is measured', '["westwards from Greenwich from 0 to 360 degrees", "eastwards from Greenwich from 0 to 180 degrees", "northwards from the equinoctial", "southwards from the ecliptic"]'::jsonb, 0, 'GHA is the equinoctial arc measured westwards from the Greenwich meridian from 0 to 360 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-199', 'air-navigation', 'air-navigation-time-1-the-solar-system-and-time', 'Time 1: The Solar System and Time', 'medium', 'A celestial body with GHA 270 degrees is transiting which equivalent geographic meridian?', '["090 degrees west", "090 degrees east", "270 degrees east only", "the Greenwich meridian"]'::jsonb, 1, 'A GHA of 270 degrees west is the same meridian as longitude 090 degrees east.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 1: The Solar System and Time''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-200', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'If it is 0900 LMT at Greenwich, what is the LMT at 045 degrees east?', '["1200", "0600", "0900", "1500"]'::jsonb, 0, 'Forty five degrees equals 3 hours, and east is later, giving 1200 LMT.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-201', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'If Cairo at 030 degrees east has 0900 LMT, the corresponding UTC is', '["1100", "0900", "0700", "0500"]'::jsonb, 2, 'Thirty degrees equals 2 hours; east LMT is ahead, so 0900 minus 0200 gives 0700 UTC.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-202', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'The normal width of a theoretical full time zone is', '["7.5 degrees", "15 degrees", "30 degrees", "45 degrees"]'::jsonb, 1, 'Earth rotates 15 degrees per hour, so a theoretical full zone is 15 degrees wide.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-203', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'Using Oxford''s zone number convention, longitude 137 degrees east lies in zone number', '["+9", "+8", "-8", "-9"]'::jsonb, 3, '137 divided by 15 is 9.13, rounded to 9, and east longitude receives a negative zone number, giving -9.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-204', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'The algebraic relationship between UTC, Zone Time and Zone Number is', '["UTC equals Zone Time minus longitude", "Zone Time equals UTC plus longitude", "UTC = Zone Time + Zone Number", "UTC equals Zone Time divided by Zone Number"]'::jsonb, 2, 'The governing relationship is UTC = Zone Time + Zone Number.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-205', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'Indian Standard Time is', '["UTC + 5 hours 30 minutes", "UTC + 5 hours", "UTC + 6 hours 30 minutes", "UTC minus 5 hours 30 minutes"]'::jsonb, 0, 'Indian Standard Time is UTC + 5 hours 30 minutes, based on 82 degrees 30 minutes east.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-206', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'Why may a country''s Standard Time differ from theoretical Zone Time?', '["Earth rotates at different rates by country", "Latitude changes the length of an hour", "Legal and administrative boundaries determine Standard Time", "UTC is not used in aviation"]'::jsonb, 2, 'Standard Time is a legal and administrative choice, so its boundary need not follow a theoretical 15 degree zone.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-207', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'When crossing the International Date Line eastbound, the traveller normally', '["subtracts one calendar day", "adds one calendar day", "adds 12 hours", "keeps both time and date unchanged"]'::jsonb, 0, 'Eastbound crossing subtracts one calendar day; westbound crossing adds one day.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-208', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'A flight leaves 175 degrees east at 0100 LMT on 18 November, flies eastbound for 4 hours, and arrives at 150 degrees west. The arrival LMT is', '["0720 on 18 November", "2120 on 17 November", "0520 on 18 November", "0720 on 17 November"]'::jsonb, 3, 'Departure converts to 1320 UTC on 17 November; after 4 hours it is 1720 UTC, then minus 10 hours gives 0720 LMT on 17 November.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-209', 'air-navigation', 'air-navigation-time-2-utc-zone-time-and-the-date-line', 'Time 2: UTC, Zone Time and the Date Line', 'medium', 'At longitude 130 degrees east, Zone Time is 0600 on 1 January and the zone number is -9. The UTC is', '["1500 on 1 January", "2100 on 31 December", "0300 on 1 January", "2100 on 1 January"]'::jsonb, 1, 'UTC = 0600 + (-9 hours), which gives 2100 UTC on 31 December.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 2: UTC, Zone Time and the Date Line''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-210', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Civil twilight ends in the evening when the centre of the Sun reaches', '["the sensible horizon", "0 degrees 50 minutes below the horizon", "12 degrees below the horizon", "6 degrees below the sensible horizon"]'::jsonb, 3, 'Evening civil twilight ends when the Sun''s centre is 6 degrees below the sensible horizon.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-211', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Nautical twilight occurs while the Sun''s centre is between', '["6 and 12 degrees below the sensible horizon", "0 and 6 degrees below", "12 and 18 degrees below", "18 and 24 degrees below"]'::jsonb, 0, 'Nautical twilight is the band from 6 to 12 degrees below the sensible horizon.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-212', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Between 60 degrees north and 60 degrees south, the minimum civil-twilight duration is about', '["16 minutes", "30 minutes", "21 minutes", "45 minutes"]'::jsonb, 2, 'The minimum is about 21 minutes at the equator, where the Sun crosses the horizon most steeply.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-213', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Compared with the sea-level table, an observer at high altitude normally sees', '["later sunrise, earlier sunset and longer twilight", "earlier sunrise, later sunset and shorter twilight", "the same sunrise and sunset with shorter twilight", "earlier sunrise, earlier sunset and unchanged twilight"]'::jsonb, 1, 'Greater height produces earlier sunrise, later sunset and generally shorter civil twilight.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-214', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'At visible sunrise, the point of the Sun used to define the event is the', '["upper limb first appearing at the visible horizon", "centre crossing the sensible horizon", "lower limb touching the sensible horizon", "centre reaching 6 degrees below the horizon"]'::jsonb, 0, 'Visible sunrise is defined by the upper limb first appearing at the visible horizon.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-215', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Air Almanac sunrise and twilight values are normally tabulated as', '["UTC for flight level 100", "Standard Time for the capital city", "zone time for mean sea level", "LMT for an observer at sea level"]'::jsonb, 3, 'The tables provide Local Mean Time for the stated latitude and date at sea level.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-216', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'For a Delhi sunrise problem, the Air Almanac table is entered initially with', '["longitude and UTC", "date and latitude", "IST and longitude", "altitude and Standard Time"]'::jsonb, 1, 'Date and latitude select the Air Almanac value; longitude is used later to convert LMT to UTC.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-217', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'Sunset at New York is 1929 LMT and ECT is 2001 LMT. Evening civil twilight lasts', '["32 minutes", "21 minutes", "28 minutes", "42 minutes"]'::jsonb, 0, 'Evening civil twilight duration is ECT minus sunset, so 2001 minus 1929 is 32 minutes.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-218', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'At visible sunset the centre of the Sun is approximately', '["6 degrees below the sensible horizon", "16 minutes above the visual horizon", "50 minutes of arc below the sensible horizon", "12 degrees below the sensible horizon"]'::jsonb, 2, 'Refraction of about 34 minutes plus the Sun''s radius of about 16 minutes places its centre roughly 50 minutes below the sensible horizon.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-219', 'air-navigation', 'air-navigation-time-3-sunrise-sunset-and-twilight', 'Time 3: Sunrise, Sunset and Twilight', 'medium', 'For two places on the same latitude and date, the Air Almanac sunrise value in LMT is', '["later at the eastern place", "earlier at the eastern place", "controlled by longitude alone", "the same at both places"]'::jsonb, 3, 'Sunrise occurs at the same Local Mean Time along the same parallel on the same date; longitude changes the corresponding UTC.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Time 3: Sunrise, Sunset and Twilight''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-220', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'An aircraft flies heading 000 degrees and makes good track 010 degrees. Its drift is', '["10 degrees left", "zero", "20 degrees right", "10 degrees right"]'::jsonb, 3, 'Track lies 10 degrees to the right of heading, so the aircraft has 10 degrees right drift.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-221', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'To maintain a required track in a crosswind, the wind correction angle is normally', '["equal to the drift and in the same direction", "equal to the drift and in the opposite direction", "twice the drift", "independent of drift"]'::jsonb, 1, 'The wind correction angle is equal in magnitude and opposite in sense to the drift it prevents.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-222', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'A wind reported from 330 degrees is drawn in the triangle of velocities towards', '["330 degrees", "030 degrees", "240 degrees", "150 degrees"]'::jsonb, 3, 'Wind is reported from 330 degrees but its vector points downwind towards 150 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-223', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'In the usual navigation vector convention, the wind vector is identified by', '["one arrowhead", "two arrowheads", "three arrowheads", "no arrowhead"]'::jsonb, 2, 'The wind vector carries three arrowheads; the air vector carries one and the ground vector carries two.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-224', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'For heading 000 degrees, TAS 100 kt and wind 240 degrees at 30 kt, the approximate scale-drawing result is', '["track 012 degrees and groundspeed 118 kt", "track 347 degrees and groundspeed 82 kt", "track 012 degrees and groundspeed 82 kt", "track 000 degrees and groundspeed 130 kt"]'::jsonb, 0, 'The scale drawing gives a track of about 012 degrees and a groundspeed of about 118 kt.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-225', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'With a wind exactly at right angles to the required track, the groundspeed after correcting heading is', '["always greater than TAS", "less than TAS", "equal to TAS", "equal to wind speed"]'::jsonb, 1, 'Crabbing uses part of the air vector across the track, so a pure crosswind gives a groundspeed less than TAS.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-226', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'Required track is 120 degrees, TAS 180 kt and wind is 340 degrees at 50 kt. The approximate heading and groundspeed are', '["130 degrees and 144 kt", "120 degrees and 180 kt", "110 degrees and 216 kt", "100 degrees and 230 kt"]'::jsonb, 2, 'Opening the triangle gives approximately heading 110 degrees and groundspeed 216 kt.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-227', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'True heading is 310 degrees, TAS is 200 kt, groundspeed is 176 kt and drift is 7 degrees right. The approximate wind is', '["090 degrees at 33 kt", "270 degrees at 33 kt", "270 degrees at 43 kt", "090 degrees at 43 kt"]'::jsonb, 1, 'Opening the known air and ground vectors gives a wind of approximately 270 degrees at 33 kt.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-228', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'From a fix, an aircraft flies heading 090 degrees at 120 kt TAS for 30 minutes. Before wind displacement is applied, its air position is', '["30 NM east of the fix", "60 NM south of the fix", "120 NM east of the fix", "60 NM east of the fix"]'::jsonb, 3, 'The air distance is 120 multiplied by 0.5 hour, so the air position is 60 NM east of the fix.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-229', 'air-navigation', 'air-navigation-dead-reckoning-and-the-triangle-of-velocities', 'Dead Reckoning and the Triangle of Velocities', 'medium', 'A complete dead-reckoning plot advances the last confirmed fix by applying', '["direction, speed, time and forecast wind", "a radio bearing only", "a visual fix only", "pressure altitude only"]'::jsonb, 0, 'A complete DR plot advances the last confirmed fix using direction, speed, elapsed time and the forecast wind.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Dead Reckoning and the Triangle of Velocities''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-230', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'At FL 200 in ISA, relative density is about 0.533. A CAS of 100 kt gives a TAS closest to', '["137 kt", "100 kt", "73 kt", "153 kt"]'::jsonb, 0, 'TAS is 100 divided by the square root of 0.533, which is approximately 137 kt.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-231', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'Which sequence correctly follows the airspeed corrections?', '["IAS, EAS, CAS, TAS", "CAS, IAS, TAS, EAS", "IAS, CAS, EAS, TAS", "IAS, TAS, CAS, EAS"]'::jsonb, 2, 'The correct sequence is IAS, CAS, EAS, TAS as position, compressibility and density corrections are applied.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-232', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'The difference between total air temperature and static air temperature is called', '["ISA deviation", "density error", "ram rise", "position error"]'::jsonb, 2, 'Ram rise is the heating difference between TAT and SAT caused by slowing and compressing the airflow at the probe.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-233', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'A recovery factor of one means that the temperature probe', '["recovers the full theoretical ram rise", "shows SAT directly at every speed", "has no compressibility heating", "must read zero Celsius"]'::jsonb, 0, 'Recovery factor one represents full recovery of the theoretical ram-temperature rise.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-234', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'The local speed of sound in ISA conditions at mean sea level is approximately', '["575 kt", "593 kt", "638 kt", "661 kt"]'::jsonb, 3, 'At 288.15 K the local speed of sound is approximately 661 kt.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-235', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'At SAT minus 42 degrees Celsius and Mach 0.86, the TAS is closest to', '["593 kt", "510 kt", "460 kt", "661 kt"]'::jsonb, 1, 'The local speed of sound is about 593 kt, and 0.86 multiplied by 593 is about 510 kt TAS.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-236', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'If TAS remains constant while SAT decreases, Mach number will', '["increase", "decrease", "remain constant", "become equal to CAS"]'::jsonb, 0, 'Colder air lowers the local speed of sound, so the same TAS represents a higher Mach number.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-237', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'At pressure altitude 5,000 ft and OAT 25 degrees Celsius, the density altitude using Bali''s 118 factor is closest to', '["5,000 ft", "7,350 ft", "2,650 ft", "9,900 ft"]'::jsonb, 1, 'ISA temperature is about 5.1 degrees Celsius, giving a positive deviation near 19.9 degrees and density altitude near 7,348 ft.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-238', 'air-navigation', 'air-navigation-tas-mach-number-and-density-altitude', 'TAS, Mach Number and Density Altitude', 'medium', 'The airspeed used as the magnitude of the air vector in the triangle of velocities is', '["IAS", "CAS", "TAS", "groundspeed"]'::jsonb, 2, 'TAS is the aircraft''s speed through the air mass and therefore forms the magnitude of the air vector.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''TAS, Mach Number and Density Altitude''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-239', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'An aircraft is 6 NM right of track after 90 NM. What is the approximate track error?', '["6 degrees right", "9 degrees right", "4 degrees right", "4 degrees left"]'::jsonb, 2, 'Sixty multiplied by 6 divided by 90 gives 4 degrees right.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-240', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'A fix is 4 NM left of track after 30 NM. The approximate track error is', '["8 degrees left", "4 degrees left", "2 degrees left", "8 degrees right"]'::jsonb, 0, 'Four in 30 scales to eight in 60, so the error is 8 degrees left.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-241', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'Planned track is 045 degrees true. After 80 NM the fix is 4 NM left. Track made good is approximately', '["042 degrees true", "048 degrees true", "041 degrees true", "049 degrees true"]'::jsonb, 0, 'The error is 60 multiplied by 4 divided by 80, which is 3 degrees left; 045 minus 3 gives 042 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-242', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'Planned track is 220 degrees true. A fix 3 NM right after 45 NM gives a track made good of', '["216 degrees true", "223 degrees true", "224 degrees true", "226 degrees true"]'::jsonb, 2, 'The error is 4 degrees right, so track made good is 220 plus 4, or 224 degrees true.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-243', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'Using pi as 3.142, the circumference of a circle of radius one unit is', '["3.142 units", "6.284 units", "57.3 units", "60 units"]'::jsonb, 1, 'Circumference is 2 pi r, so a radius of one gives 2 multiplied by 3.142, or 6.284 units.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-244', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'One radian is approximately', '["60.0 degrees", "45.0 degrees", "6.284 degrees", "57.3 degrees"]'::jsonb, 3, 'One radian equals 360 divided by 2 pi, approximately 57.3 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-245', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'Why is 60 used instead of the exact 57.3 in the pilot rule?', '["It removes tangent error completely", "It makes the rule exact at every angle", "It permits easy mental arithmetic with about 5 percent rounding error", "It converts nautical miles to kilometres"]'::jsonb, 2, 'Rounding 57.3 to 60 makes proportional mental arithmetic easy and introduces about 5 percent error.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-246', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'At an angle of 10 degrees, the exact opposite side for an adjacent side of 60 units is closest to', '["10.6 units", "6.0 units", "16.1 units", "20.0 units"]'::jsonb, 0, 'Sixty multiplied by tangent 10 degrees is approximately 10.56 units, closest to 10.6.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-247', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'A 5 degree track error continues for 84 NM. The estimated distance off track is', '["5 NM", "14 NM", "4 NM", "7 NM"]'::jsonb, 3, 'Distance off is 5 multiplied by 84 divided by 60, which is 7 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-248', 'air-navigation', 'air-navigation-the-1-in-60-rule', 'The 1 in 60 Rule', 'medium', 'For the track-error triangle, distance gone is measured', '["along track made good to the fix", "along planned track to the fix''s abeam position", "from the fix directly to destination", "along the wind vector"]'::jsonb, 1, 'Distance gone is the adjacent side measured along planned track from the last on-track point to the present fix''s abeam position.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''The 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-249', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'For the same 78 NM leg with a fix 4 NM left after 30 NM, the direct-to-destination heading alteration is', '["5 degrees right", "13 degrees right", "8 degrees right", "13 degrees left"]'::jsonb, 1, 'Track error is 8 degrees and closing angle is 5 degrees, so the aircraft turns 13 degrees right towards track.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-250', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'An aircraft is 4 NM left after 30 NM and will regain track after another 30 NM. The first heading alteration is', '["8 degrees right", "8 degrees left", "16 degrees left", "16 degrees right"]'::jsonb, 3, 'With equal outbound and return distances, the double-track-error turn is 2 multiplied by 8 degrees, giving 16 degrees right.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-251', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'After the double-track-error correction in the previous question, what turn is made when track is regained?', '["16 degrees left", "16 degrees right", "8 degrees right", "8 degrees left"]'::jsonb, 3, 'At the intercept, an 8 degree left turn removes only the closing angle and leaves the net wind correction.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-252', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'On a 95 NM leg, a fix after 35 NM is 7 NM right of track. The heading alteration to fly direct to destination is approximately', '["12 degrees left", "19 degrees left", "7 degrees left", "19 degrees right"]'::jsonb, 1, 'Track error is 12 degrees and closing angle over the remaining 60 NM is 7 degrees, giving a 19 degree turn left.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-253', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'A 96 NM leg has 36 NM gone and a fix 3 NM right of track. The direct correction is', '["8 degrees left", "5 degrees left", "8 degrees right", "3 degrees left"]'::jsonb, 0, 'Track error is 5 degrees and closing angle is 3 degrees, so the direct correction is 8 degrees left.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-254', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'If a cross-track error developed over 12 minutes and a double-track-error turn is made with unchanged groundspeed, track should be regained after approximately', '["6 minutes", "24 minutes", "12 minutes", "36 minutes"]'::jsonb, 2, 'The equal-triangle method takes the same time to regain track as the time taken to develop the error, which is 12 minutes.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-255', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'A closing angle is 5 degrees on a 78 NM leg with 30 NM gone. The combined correction is', '["8 degrees", "13 degrees", "5 degrees", "18 degrees"]'::jsonb, 1, 'Combined correction is closing angle multiplied by total distance divided by distance gone: 5 multiplied by 78 divided by 30 equals 13 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-256', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'A fix is one quarter of the way along a leg and the closing angle is 5 degrees. New Track Reference gives a heading alteration of', '["5 degrees", "10 degrees", "15 degrees", "20 degrees"]'::jsonb, 3, 'Invert one quarter to obtain 4, then multiply by the 5 degree closing angle to obtain 20 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-257', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'An aircraft is 4 NM off track and must regain track 24 NM ahead. The closing angle is', '["6 degrees", "8 degrees", "10 degrees", "12 degrees"]'::jsonb, 2, 'Closing angle is 60 multiplied by 4 divided by 24, which gives 10 degrees.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-258', 'air-navigation', 'air-navigation-navigation-using-the-1-in-60-rule', 'Navigation Using the 1 in 60 Rule', 'medium', 'Which statement correctly distinguishes track error from drift?', '["Track error is between planned track and TMG; drift is between heading and track", "Track error is between heading and TMG; drift is between planned track and TMG", "Both are always the same angle", "Drift can be calculated without knowing heading"]'::jsonb, 0, 'Track error compares planned track with track made good, while drift compares heading with a ground track.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Using the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-259', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'An aircraft is 2 NM from touchdown on a 3 degree path. Its approximate height is', '["300 ft", "900 ft", "1200 ft", "600 ft"]'::jsonb, 3, 'A 3 degree path changes height by about 300 ft per NM, so at 2 NM the height is 600 ft.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-260', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'The required ROD at 120 kt groundspeed on a 3.5 degree path is approximately', '["600 ft/min", "700 ft/min", "875 ft/min", "420 ft/min"]'::jsonb, 1, 'Five times 120, multiplied by 3.5 divided by 3, gives 700 ft/min.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-261', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'At 180 kt groundspeed on a 2.6 degree path, the approximate ROD is', '["900 ft/min", "780 ft/min", "650 ft/min", "468 ft/min"]'::jsonb, 1, 'Five times 180, multiplied by 2.6 divided by 3, gives 780 ft/min.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-262', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'On a 3 degree path at 150 kt groundspeed, the approximate ROD is', '["500 ft/min", "600 ft/min", "900 ft/min", "750 ft/min"]'::jsonb, 3, 'For a 3 degree path, ROD is about five times groundspeed, giving 750 ft/min.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-263', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'Groundspeed reduces from 150 kt to 120 kt on a 3 degree path. To maintain the path, ROD should', '["decrease by 150 ft/min", "increase by 150 ft/min", "decrease by 30 ft/min", "remain unchanged"]'::jsonb, 0, 'The 30 kt reduction requires a five-times change, so ROD decreases by 150 ft/min.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-264', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'On a 2.5 degree path, TAS is 220 kt and headwind is 10 kt. Approximate ROD is', '["750 ft/min", "917 ft/min", "875 ft/min", "1050 ft/min"]'::jsonb, 2, 'Groundspeed is 210 kt, so five times 210 multiplied by 2.5 divided by 3 gives 875 ft/min.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-265', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'Required inbound QDM is 137 degrees, indicated QDM is 141 degrees and DME range is 90 NM. The aircraft is approximately', '["4 NM right", "5 NM right", "6 NM right", "6 NM left"]'::jsonb, 3, 'The 4 degree difference at 90 NM gives 4 multiplied by 90 divided by 60, or 6 NM left of centreline.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-266', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'A point bearing changes 8 degrees while an aircraft at 120 kt flies for 6 minutes. Approximate range to the point is', '["60 NM", "90 NM", "120 NM", "45 NM"]'::jsonb, 1, 'The aircraft flies 12 NM; 12 multiplied by 60 divided by 8 gives a range of 90 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-267', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'For a three-degree path, the rapid rate-of-descent factor is', '["5 times groundspeed", "3 times groundspeed", "10 times groundspeed", "groundspeed divided by 5"]'::jsonb, 0, 'A 3 degree path is about 300 ft per NM, which gives an ROD of approximately five times groundspeed.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-268', 'air-navigation', 'air-navigation-other-applications-of-the-1-in-60-rule', 'Other Applications of the 1 in 60 Rule', 'medium', 'A 2 degree angular deviation at a range of 30 NM represents an approximate displacement of', '["0.5 NM", "2 NM", "1 NM", "4 NM"]'::jsonb, 2, 'Displacement is angle multiplied by range divided by 60: 2 multiplied by 30 divided by 60 equals 1 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Other Applications of the 1 in 60 Rule''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-269', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'An aircraft passes X at 1420 and Y, 30 NM farther, at 1450. If Z is 20 NM beyond Y, ETA at Z is', '["1500", "1506", "1510", "1512"]'::jsonb, 2, 'The measured groundspeed is 60 kt, so 20 NM takes 20 minutes and ETA is 1510.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-270', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'A common planning radius for a circle of uncertainty after 70 NM without a fix is', '["5 NM", "7 NM", "10 NM", "14 NM"]'::jsonb, 1, 'Using 10 percent of distance flown gives an uncertainty radius of 7 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-271', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'Visual checkpoints are normally selected at intervals of about', '["1 to 2 minutes", "15 to 20 minutes", "5 to 10 minutes", "30 minutes"]'::jsonb, 2, 'Oxford recommends visual checkpoints at roughly 5 to 10 minute intervals.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-272', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'Immediately after setting heading, the navigator should first establish', '["a definite departure point and time", "the final fuel reserve", "the destination QNH", "the next radio frequency only"]'::jsonb, 0, 'A definite departure point and departure time provide the origin for the first track and ETA check.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-273', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'At a groundspeed of 150 kt, the distance represented by a six-minute chart marker is', '["2.5 NM", "6 NM", "10 NM", "15 NM"]'::jsonb, 3, 'A six-minute marker equals groundspeed divided by 10, so 150 kt gives 15 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-274', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'Which sequence best describes the normal in-flight navigation cycle?', '["Correct, record, anticipate, identify", "Anticipate, check, correct, record", "Record, correct, check, anticipate", "Check, record, anticipate, correct"]'::jsonb, 1, 'The normal cycle is anticipate, check, correct and record, with heading and ETA revised after a confirmed observation.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-275', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'If position is still uncertain when the planned turning-point time arrives, the normal navigation action is to', '["continue straight until a feature appears", "turn on the planned ETA", "descend immediately", "ignore the flight log"]'::jsonb, 1, 'The lost procedure advises turning on the planned ETA rather than continuing indefinitely on the old heading.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-276', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'When the expected checkpoint is missing and position is uncertain, the more suitable visual-reading method is', '["map-to-ground only", "time-to-distance", "track-error lines only", "ground-to-map"]'::jsonb, 3, 'Ground-to-map starts with observed features and searches the chart for a matching pattern, which suits uncertain position.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-277', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'If a safe line feature outside the uncertainty circle is chosen, the aircraft should', '["intercept it and follow it to a definite checkpoint", "cross it and continue the same heading", "descend below safety altitude", "enter controlled airspace without clearance"]'::jsonb, 0, 'A line feature can be intercepted and followed until a definite checkpoint allows normal navigation to resume.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-278', 'air-navigation', 'air-navigation-in-flight-navigation-technique', 'In-flight Navigation Technique', 'medium', 'A fix is more than halfway along the leg and the pilot wishes to fly straight to destination. The preferred correction is', '["turn only by track error", "use no correction", "add track error and closing angle", "double track error regardless of distance"]'::jsonb, 2, 'A direct-to-destination correction combines track error with the closing angle for the remaining distance.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''In-flight Navigation Technique''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-279', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'A QDM of 330 degrees magnetic is converted to its QDR by taking the reciprocal. The QDR is', '["150 degrees magnetic", "160 degrees magnetic", "330 degrees true", "510 degrees magnetic"]'::jsonb, 0, 'The reciprocal of QDM 330 M is QDR 150 M.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-280', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'When plotting a VOR radial after magnetic-to-true conversion, the applicable variation is normally at', '["the aircraft", "the destination", "the VOR station", "the midpoint of the route"]'::jsonb, 2, 'A VOR bearing is referenced and measured at the ground station, so station variation is used.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-281', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'An aircraft heads 315 M where aircraft variation is 9 degrees west. An NDB bears 207 relative. The true bearing to plot FROM the NDB is', '["153 T", "306 T", "027 T", "333 T"]'::jsonb, 3, 'True heading is 306 T; adding relative 207 gives 153 T TO, whose reciprocal is 333 T FROM the NDB.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-282', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'Two DME range circles normally create', '["one unambiguous point", "two possible intersections", "a straight position line", "no usable position information"]'::jsonb, 1, 'Two circles normally intersect at two possible positions, so DR position, heading or range trend resolves the ambiguity.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-283', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'At 120 kt, a position line observed 10 minutes earlier is transferred along track by', '["10 NM", "15 NM", "20 NM", "24 NM"]'::jsonb, 2, 'Transfer distance is 120 multiplied by 10 divided by 60, which equals 20 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-284', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'To construct a running fix, the earlier position line is', '["moved parallel to itself by estimated ground movement", "rotated through the drift angle", "left unchanged and relabelled", "converted into a DME circle"]'::jsonb, 0, 'The complete earlier line is moved parallel to itself in track direction by the estimated distance travelled.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-285', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'The size of a cocked hat primarily indicates', '["aircraft altitude", "chart scale", "agreement and probable accuracy of the position lines", "magnetic variation"]'::jsonb, 2, 'A smaller cocked hat shows closer agreement of the plotted lines, though common systematic error can still shift them.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-286', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'On an air and ground plot for the same interval, the vector from air position to ground position represents', '["true airspeed", "wind displacement", "track made good only", "magnetic variation"]'::jsonb, 1, 'The difference between air position and simultaneous ground position is the displacement caused by wind.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-287', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'On a Lambert chart, an aircraft-measured ADF bearing is most accurately plotted from', '["a line through the NDB parallel to the aircraft meridian", "the equator", "the nearest parallel of latitude", "magnetic north at destination"]'::jsonb, 0, 'A false meridian through the NDB, parallel to the aircraft meridian, automatically allows for chart convergence.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-288', 'air-navigation', 'air-navigation-plotting', 'Plotting', 'medium', 'To lose 23,000 ft over 65 NM at a groundspeed of 240 kt, the approximate rate of descent is', '["1060 ft per minute", "1200 ft per minute", "1630 ft per minute", "1415 ft per minute"]'::jsonb, 3, 'The flight covers 65 NM in 16.25 minutes, and 23,000 divided by 16.25 is about 1415 ft per minute.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Plotting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-289', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'A beacon changes from relative bearing 270 to 225 in 3 minutes while GS is 180 kt. For the stated isosceles geometry, closest approach is', '["3 NM", "6 NM", "12 NM", "9 NM"]'::jsonb, 3, 'The aircraft travels 9 NM in 3 minutes, and the 45-degree isosceles geometry makes closest approach also 9 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-290', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'In exact triangle-of-velocities geometry, zero head or tail component occurs when wind is at right angles to', '["track only", "the bisector between heading and track", "heading only", "true north"]'::jsonb, 1, 'Strictly, the wind must be perpendicular to the bisector between heading and track for zero along-track component.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-291', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'Safe endurance used in a PNR calculation is', '["time available after protected reserves are excluded", "all fuel on board including unusable fuel", "route time to destination only", "final-reserve time alone"]'::jsonb, 0, 'Safe endurance is the time available for the defined outbound and return operation after protected reserves and unusable fuel are removed.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-292', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'Safe endurance is 8 hours, outbound GS 450 kt and homebound GS 350 kt. Time to PNR is', '["3.0 hours", "3.25 hours", "3.5 hours", "4.5 hours"]'::jsonb, 2, 'PNR time is 8 multiplied by 350 divided by 800, which equals 3.5 hours.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-293', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'Which expression gives PNR distance from base when E is safe endurance, O outbound GS and H homebound GS?', '["E x O / H", "E x O x H / (O + H)", "E x (O + H)", "E x H / O"]'::jsonb, 1, 'PNR distance equals E multiplied by O multiplied by H, divided by O plus H.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-294', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'With E 10 hours, outbound GS 300 kt and homebound GS 500 kt, PNR distance is', '["1500 NM", "1750 NM", "2500 NM", "1875 NM"]'::jsonb, 3, 'PNR time is 10 x 500 / 800 = 6.25 hours, and 6.25 x 300 gives 1875 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-295', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'Available decision fuel is 3000 kg. Outbound flow is 500 kg/h at 400 kt and homebound flow 400 kg/h at 500 kt. Fuel-limited PNR distance is about', '["1200 NM", "1333 NM", "1600 NM", "1463 NM"]'::jsonb, 3, 'Distance is 3000 divided by (500/400 + 400/500), which is approximately 1463 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-296', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'For a 2400 NM route with outbound GS 480 kt and homebound GS 320 kt, CP distance from base is', '["960 NM", "1200 NM", "1440 NM", "1600 NM"]'::jsonb, 0, 'CP distance is 2400 multiplied by 320 divided by 800, giving 960 NM.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-297', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'An along-track wind moves the critical point towards', '["the route midpoint in every case", "the downwind endpoint", "the upwind endpoint", "the point of no return"]'::jsonb, 2, 'The critical point shifts towards the upwind endpoint because travel is slower in that direction.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('NAV-298', 'air-navigation', 'air-navigation-navigation-problems-relative-velocity-pnr-and-cp', 'Navigation Problems: Relative Velocity, PNR and CP', 'medium', 'Which statement correctly distinguishes CP from PNR?', '["Both require safe endurance", "CP uses route distance and both groundspeeds, while PNR uses safe endurance", "PNR is always the route midpoint", "CP is determined only by fuel flow"]'::jsonb, 1, 'CP is an equal-time point based on route distance and groundspeeds; PNR is an endurance or fuel-limited return point.', 'Oxford ATPL General Navigation / R.K. Bali, Chapter ''Navigation Problems: Relative Velocity, PNR and CP''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-051', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which definition describes a non-power driven heavier than air aircraft deriving lift chiefly from fixed surfaces?', '["Airship", "Helicopter", "Amphibian", "Glider"]'::jsonb, 3, 'Glider is the correct term for a non-power driven heavier than air aircraft that derives lift chiefly from fixed surfaces.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-052', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which operation is neither commercial air transport nor aerial work?', '["Public transport", "General aviation", "Scheduled air transport", "Aerial work"]'::jsonb, 1, 'General aviation is defined as an aircraft operation other than commercial air transport or aerial work.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-053', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'When a pressure altimeter is set to QNH, which vertical quantity does it indicate?', '["Altitude", "Height above the QFE datum", "Flight level", "Aerodrome elevation only"]'::jsonb, 0, 'Altitude is indicated with QNH because altitude is referenced to mean sea level.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-054', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which minimum provides at least 1,000 ft obstacle clearance within a 25 NM sector centred on a radio navigation aid?', '["MOCA", "MEA", "MDA", "MSA"]'::jsonb, 3, 'MSA is the minimum sector altitude, providing at least 1,000 ft clearance within a 25 NM sector.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-055', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which airspace begins at the surface and extends upward to a specified upper limit?', '["Control area", "Control zone", "Airway", "Flight information region"]'::jsonb, 1, 'A control zone is controlled airspace extending upwards from the surface to a specified upper limit.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-056', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which navigation specification includes on-board performance monitoring and alerting?', '["RNAV specification", "ATS route", "Advisory route", "RNP specification"]'::jsonb, 3, 'An RNP specification includes the requirement for on-board performance monitoring and alerting.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-057', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which aerodrome area consists of the manoeuvring area plus the apron or aprons?', '["Movement area", "Landing area", "Runway strip", "Clearway"]'::jsonb, 0, 'The movement area consists of the manoeuvring area and the apron or aprons.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-058', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which declared distance equals TORA plus stopway, if a stopway is provided?', '["TODA", "LDA", "ASDA", "TORA"]'::jsonb, 2, 'ASDA is the accelerate-stop distance available and equals TORA plus the stopway, if provided.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-059', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which flight plan includes changes resulting from subsequent clearances?', '["Filed flight plan", "Current flight plan", "Operational flight plan", "Repetitive flight plan"]'::jsonb, 1, 'The current flight plan is the flight plan including changes brought about by later clearances.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-060', 'air-regulations', 'air-regulations-definitions-and-framework', 'Definitions and Framework', 'medium', 'Which emergency phase means reasonable certainty that grave and imminent danger exists and immediate assistance is required?', '["ALERFA", "INCERFA", "DETRESFA", "Alerting service"]'::jsonb, 2, 'DETRESFA is the distress phase, used when grave and imminent danger is reasonably certain and immediate assistance is required.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Definitions and Framework''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-061', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which item is one of the seven documents listed under Article 29?', '["Certificate of registration", "Airport entry permit", "Passenger health card for every flight", "Aerodrome licence"]'::jsonb, 0, 'A certificate of registration is one of the documents Article 29 requires an aircraft in international navigation to carry.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-062', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Within what period does Article 38 require notice after an amended international Standard when a State does not amend its own practice?', '["30 days", "45 days", "60 days", "One year"]'::jsonb, 2, 'The required period stated by Article 38 is 60 days after adoption of the amendment.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-063', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which ICAO body has all Contracting States represented with one vote each?', '["Council", "Air Navigation Commission", "Assembly", "Secretariat"]'::jsonb, 2, 'The Assembly includes all Contracting States, with one vote for each State.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-064', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which body adopts international Standards and Recommended Practices?', '["The Council", "The Secretariat", "A regional office", "The Air Transport Committee alone"]'::jsonb, 0, 'The Council adopts international Standards and Recommended Practices, while technical bodies prepare and recommend material.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-065', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which Annex addresses safe transport of dangerous goods by air?', '["Annex 16", "Annex 17", "Annex 19", "Annex 18"]'::jsonb, 3, 'Annex 18 addresses the safe transport of dangerous goods by air.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-066', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'What status do Regional Supplementary Procedures have?', '["They are national laws in every State", "They are Council-approved procedures for the relevant region", "They replace the Chicago Convention", "They apply only to military aircraft"]'::jsonb, 1, 'Regional Supplementary Procedures are approved by the Council and apply only in the relevant region.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-067', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which freedom permits landing in another State for refuelling without taking on or putting down traffic?', '["Second freedom", "First freedom", "Fourth freedom", "Fifth freedom"]'::jsonb, 0, 'The second freedom permits a non-traffic technical landing such as refuelling or repair.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-068', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which convention chiefly addresses unlawful seizure of aircraft?', '["Tokyo 1963", "Rome 1952", "The Hague 1970", "Geneva 1948"]'::jsonb, 2, 'The Hague Convention 1970 chiefly addresses suppression of unlawful seizure of aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-069', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which convention concerns damage caused by foreign aircraft to persons or property on the surface?', '["Warsaw 1929", "Rome 1952", "Tokyo 1963", "Cape Town 2001"]'::jsonb, 1, 'The Rome Convention 1952 concerns liability for damage caused by foreign aircraft to third parties on the surface.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-070', 'air-regulations', 'air-regulations-icao-and-conventions', 'ICAO and Conventions', 'medium', 'Which Indian body is responsible for civil aviation safety regulation, licensing and airworthiness oversight?', '["AAI", "ICAO", "Ministry of External Affairs", "DGCA"]'::jsonb, 3, 'DGCA is the Indian safety regulator responsible for licensing, airworthiness and related oversight.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ICAO and Conventions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-071', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'What must an Indian registered aircraft normally obtain before leaving India for an overseas flight?', '["A customs seal only", "Required DGCA permission", "An AIC", "A new certificate of registration"]'::jsonb, 1, 'Required DGCA permission is needed before an Indian registered aircraft leaves India for an overseas flight.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-072', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'If a pilot strays into a prohibited area under the rule summarised by Bali, what is the correct immediate course?', '["Descend immediately inside the area", "Continue to destination without reporting", "Circle until a clearance is received", "Signal distress, leave the area and land at the nearest aerodrome"]'::jsonb, 3, 'The stated response is to signal distress, leave the prohibited area and land at the nearest aerodrome.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-073', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'How long before flight does Bali state that flight crew must avoid alcohol, sedatives and narcotics?', '["6 hours", "12 hours", "18 hours", "24 hours"]'::jsonb, 1, 'Bali states a 12-hour prohibition before flight, together with the continuing rule against operating while intoxicated.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-074', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'At what jet-exhaust distance does the fuelling rule in the lesson require fuelling to stop?', '["15 m", "30 m", "43 m", "50 m"]'::jsonb, 2, 'Fuelling stops when hazardous jet exhaust comes within 43 m of the fuelling equipment or aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-075', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'For how long must a flight crew log book be preserved under the stated rule?', '["At least five years after the last entry", "Two years after the first entry", "Until the next licence renewal", "For the holder''s lifetime"]'::jsonb, 0, 'The personal flight crew log book is retained for at least five years after its last entry.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-076', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'For how long is a draft CAR placed on the DGCA website for objections and suggestions before final issue?', '["7 days", "14 days", "21 days", "30 days"]'::jsonb, 3, 'The stated consultation period for a draft CAR is 30 days before final issue.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-077', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'Which publication is used for urgent, time-sensitive information about a facility, service, procedure or hazard?', '["AIC", "NOTAM", "Operations Manual", "Certificate of airworthiness"]'::jsonb, 1, 'A NOTAM provides time-sensitive operational information whose timely knowledge is essential.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-078', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'Which airspace type permits flight only in accordance with specified conditions?', '["Restricted area", "Prohibited area", "Danger area in every circumstance", "Aerodrome traffic zone only"]'::jsonb, 0, 'A restricted area permits flight only in accordance with its specified conditions.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-079', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'What identifier is assigned to a registered drone under the Drone Rules system?', '["Certificate of airworthiness number", "SSR code", "Unique Identification Number", "Aerodrome reference code"]'::jsonb, 2, 'A registered drone receives a Unique Identification Number, commonly shortened to UIN.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-080', 'air-regulations', 'air-regulations-indian-regulatory-system', 'Indian Regulatory System', 'medium', 'What general maximum fine is stated in Bali''s summary of the 2024 Act?', '["Rs. 1 lakh", "Rs. 10 lakh", "Rs. 50 lakh", "Rs. 1 crore"]'::jsonb, 3, 'Bali''s summary states a general maximum fine of Rs. 1 crore, alongside imprisonment up to two years or both.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Indian Regulatory System''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-081', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Which combination must be excluded because it can be confused with an urgency signal?', '["RCC", "PAN", "DDD", "LLL"]'::jsonb, 1, 'PAN is an internationally recognised urgency signal and must not be used as a registration-mark combination.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-082', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Which mark does Bali identify for Indian civil aircraft?', '["AT", "VU", "U followed by six characters", "VT"]'::jsonb, 3, 'VT is the nationality mark that Bali identifies as continuing in use for Indian civil aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-083', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'What is the minimum height of marks on the wings of a heavier-than-air aircraft?', '["30 cm", "40 cm", "50 cm", "60 cm"]'::jsonb, 2, 'The wing marks of a heavier-than-air aircraft must be at least 50 cm high.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-084', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Where are the wing marks placed on a heavier-than-air aircraft?', '["On the lower wing surface", "Only on the upper wing surface", "Only on the wing tips", "Inside the wheel wells"]'::jsonb, 0, 'The required wing marks are placed on the lower wing surface for ready external identification.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-085', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'What minimum height applies to marks on the fuselage or vertical tail of a heavier-than-air aircraft?', '["20 cm", "30 cm", "40 cm", "50 cm"]'::jsonb, 1, 'Fuselage and vertical-tail marks on a heavier-than-air aircraft must be at least 30 cm high.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-086', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Which document is evidence that an aircraft has been entered on the national register?', '["Certificate of Airworthiness", "Noise certificate", "Journey log book", "Certificate of Registration"]'::jsonb, 3, 'The Certificate of Registration is the official evidence that the aircraft has been entered on the national register.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-087', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Which item is specifically added to the Indian Certificate of Registration for a leased aircraft?', '["Lease validity and particulars of lessor and lessee", "The pilot''s medical expiry", "Every airport in the intended route network", "A passenger manifest"]'::jsonb, 0, 'A leased aircraft''s certificate includes the lease validity and the names, nationalities and addresses of lessor and lessee.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-088', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Which event is a stated ground for DGCA cancellation of Indian registration?', '["A routine change of parking stand", "The Certificate of Airworthiness has been expired for five years or more", "A single delayed departure", "Replacement of a cabin seat cover"]'::jsonb, 1, 'A Certificate of Airworthiness that has remained expired for five years or more is a stated cancellation ground.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-089', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'Who exercises operational control over a leased aircraft in Bali''s summary?', '["The common mark authority", "The aircraft manufacturer", "The lessee operator", "The aerodrome licensee"]'::jsonb, 2, 'The lessee operator exercises operational control and must hold the necessary economic and operating authority.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-090', 'air-regulations', 'air-regulations-nationality-and-registration', 'Nationality and Registration', 'medium', 'What does a common mark replace for a qualifying international operating agency?', '["The registration certificate", "The identification plate", "The registration mark", "The nationality mark"]'::jsonb, 3, 'A common mark replaces the nationality mark for a qualifying international operating agency.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Nationality and Registration''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-091', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'What is the main purpose of a Type Certificate?', '["To license the flight crew", "To approve one maintenance release", "To approve the type design", "To register one aircraft"]'::jsonb, 2, 'A Type Certificate records approval of the type design after compliance with the applicable design requirements is shown.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-092', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'Which document summarises approved models, certification basis, powerplant combinations and design limitations?', '["Journey log", "Noise Certificate", "Certificate of Registration", "Type Certificate Data Sheet"]'::jsonb, 3, 'The Type Certificate Data Sheet summarises the approved design data and limitations associated with the Type Certificate.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-093', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'What must be true before DGCA issues a normal Certificate of Airworthiness?', '["The aircraft must have flown internationally", "The owner must also be the manufacturer", "The aircraft must conform to its approved design and be safe to operate", "The Noise Certificate must replace the flight manual"]'::jsonb, 2, 'DGCA issues the normal Certificate of Airworthiness only when the aircraft conforms to its approved basis and is in a condition for safe operation.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-094', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'What does an Airworthiness Review Certificate record?', '["Approval of a new aircraft type", "A satisfactory periodic continuing-airworthiness review", "Ownership of the aircraft", "Permission to use a radio frequency"]'::jsonb, 1, 'An Airworthiness Review Certificate records that the required periodic continuing-airworthiness review was completed satisfactorily.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-095', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'Which action belongs to continuing airworthiness?', '["Controlling defects and complying with mandatory airworthiness instructions", "Changing the nationality mark without approval", "Ignoring an applicable directive until the next sale", "Replacing technical records with the journey log"]'::jsonb, 0, 'Controlling defects and complying with mandatory airworthiness instructions are core continuing-airworthiness duties.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-096', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'Who ensures a structural integrity programme, including corrosion-control information, exists for the applicable type?', '["The aerodrome operator", "The pilot alone", "The travel agent", "The State of Design"]'::jsonb, 3, 'The State of Design ensures that the applicable structural integrity programme includes corrosion-control information.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-097', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'Which event causes the certificate to be deemed suspended under Bali''s national provisions?', '["Major damage to the aircraft", "A change of parking stand", "A delayed departure", "A passenger missing a connection"]'::jsonb, 0, 'Major damage is one of the events that causes the Certificate of Airworthiness to be deemed suspended.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-098', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'What may the Director General require when there is reasonable doubt about aircraft safety?', '["A change of aircraft nationality only", "Automatic commercial approval", "Deletion of the technical log", "Inspection, repair, replacement, overhaul or flight testing under approved supervision"]'::jsonb, 3, 'The Director General may require inspection, repair, replacement, overhaul or flight testing under approved supervision.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-099', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'What does a special flight permit authorise?', '["Unlimited normal operation", "Any flight selected by the pilot", "A specific exceptional flight subject to stated limitations", "Permanent restoration of the normal certificate"]'::jsonb, 2, 'A special flight permit authorises a specific exceptional flight subject to its stated purpose and limitations.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-100', 'air-regulations', 'air-regulations-airworthiness', 'Airworthiness', 'medium', 'Which document answers whether the aircraft meets an applicable certified noise standard?', '["Certificate of Registration", "Noise Certificate", "Flight crew licence", "Journey log"]'::jsonb, 1, 'The Noise Certificate records compliance of the approved aircraft configuration with the applicable certified noise standard.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airworthiness''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-101', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What is the normal Class 2 medical validity up to age 50?', '["Six months", "Two years", "One year", "Four years"]'::jsonb, 1, 'The normal Class 2 medical validity is two years up to age 50.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-102', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'Which restriction applies to an SPL holder?', '["The holder may carry one passenger", "The holder may fly for hire under supervision", "The holder may fly IFR after ten solo hours", "The holder flies under VFR and may not carry passengers"]'::jsonb, 3, 'An SPL holder flies under VFR and may not carry passengers, animals or goods.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-103', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What total flight experience does Bali state for the aeroplane PPL?', '["20 hours", "100 hours", "40 hours", "200 hours"]'::jsonb, 2, 'The aeroplane PPL requires at least 40 hours of total flight time.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-104', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What recent night experience is required before a PPL holder carries passengers at night?', '["Five take-offs and five landings by night as pilot-in-command in six months", "Ten night landings in twelve months", "One night cross-country every month", "Five instrument approaches in six months"]'::jsonb, 0, 'The PPL holder needs five take-offs and five landings by night as pilot-in-command within the preceding six months.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-105', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'Which set correctly states the CPL core experience?', '["100 total, 50 command, 10 cross-country", "250 total, 150 command, 50 instrument", "1,500 total, 250 command, 500 cross-country", "200 total, 100 command, 20 cross-country command"]'::jsonb, 3, 'The CPL core is 200 total hours, 100 hours as pilot-in-command and 20 hours cross-country as pilot-in-command.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-106', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'How long is the type proficiency check described for transport aeroplanes above 5,700 kg valid?', '["Twelve months", "Six months", "Twenty-four months", "Three months"]'::jsonb, 1, 'The applicable type proficiency check is valid for six months.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-107', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What total time does Bali state for the aeroplane ATPL?', '["1,500 hours", "1,000 hours", "500 hours", "250 hours"]'::jsonb, 0, 'The aeroplane ATPL requires at least 1,500 hours of total flight time.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-108', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What is the ATPL minimum total night-flight experience?', '["25 hours", "50 hours", "100 hours", "75 hours"]'::jsonb, 3, 'The ATPL experience table requires at least 75 hours of night flight.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-109', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'What is the normal validity of an aeroplane Instrument Rating from its flight test?', '["Six months", "Twenty-four months", "Twelve months", "Ten years"]'::jsonb, 2, 'The aeroplane Instrument Rating is valid for twelve months from the instrument flight test.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-110', 'air-regulations', 'air-regulations-personnel-licensing', 'Personnel Licensing', 'medium', 'Which time must the student log as SPIC with the instructor named in remarks?', '["Ordinary passenger time", "Student pilot-in-command time", "All simulator time", "Unsupervised co-pilot time"]'::jsonb, 1, 'Student pilot-in-command time is logged by the student as SPIC with the instructor named in the remarks.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Personnel Licensing''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-111', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'What is the VFR minimum over a congested area when no exception applies?', '["500 ft above the nearest person", "1,000 ft above the highest obstacle within 600 m", "2,000 ft above every obstacle within 8 km", "600 ft above the aerodrome"]'::jsonb, 1, 'The VFR congested-area minimum is 1,000 ft above the highest obstacle within 600 m.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-112', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'What does Bali state about civil formation flight in India?', '["It is freely permitted below 3,000 ft", "It needs only passenger consent", "It is mandatory for training aircraft", "It is not permitted"]'::jsonb, 3, 'Bali states that civil formation flight is not permitted in India.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-113', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'In a converging encounter at the same level, which aircraft gives way?', '["The aircraft with the other on its left", "The faster aircraft", "The aircraft with the other on its right", "The larger aircraft in every case"]'::jsonb, 2, 'The aircraft that has the other aircraft on its right gives way.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-114', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'What action is required in an approximately head-on encounter?', '["Both aircraft alter heading to the right", "Both aircraft turn left", "Only the lower aircraft turns", "Both aircraft maintain heading"]'::jsonb, 0, 'In a head-on or approximately head-on encounter, both aircraft alter heading to the right.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-115', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'Who has right-of-way during overtaking?', '["The overtaking aircraft", "The aircraft on the right only", "The faster aircraft", "The aircraft being overtaken"]'::jsonb, 3, 'The aircraft being overtaken has right-of-way, and the overtaking aircraft keeps clear by altering to the right.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-116', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'When may an aircraft cross a lighted stop bar?', '["Whenever no traffic is visible", "Only after the lights are switched off and the required clearance exists", "Whenever the pilot has received a taxi route", "After flashing landing lights"]'::jsonb, 1, 'An aircraft proceeds beyond a stop bar only after the lights are switched off and the required clearance exists.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-117', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'Which navigation light is displayed on the aircraft''s port side?', '["Red", "Green", "White", "Amber"]'::jsonb, 0, 'The port navigation light is red.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-118', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'For an Indian semicircular track of 225 degrees, which IFR family normally applies below the RVSM transition?', '["Odd thousands", "Odd thousands plus 500 ft", "Any level selected by the pilot", "Even thousands"]'::jsonb, 3, 'A track from 180 through 359 degrees uses the even-thousand IFR family.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-119', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'What does a VI R designator identify?', '["A prohibited area", "A restricted area", "A danger area", "A compulsory reporting point"]'::jsonb, 1, 'VI R identifies an Indian restricted area, which may be entered only under the published conditions.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-120', 'air-regulations', 'air-regulations-rules-of-the-air-general', 'Rules of the Air: General', 'medium', 'Which maximum vertical displacement from the leader is stated for an authorised formation?', '["300 m", "500 ft", "30 m or 100 ft", "1 km"]'::jsonb, 2, 'The Annex 2 formation condition limits vertical displacement from the leader to 30 m or 100 ft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: General''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-121', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'Which flight always requires a flight plan under the listed rules?', '["A local taxi movement", "A flight crossing an international border", "Every glider winch launch", "Every engine ground run"]'::jsonb, 1, 'A flight crossing an international border is one of the flights for which a flight plan is required.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-122', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What is the general IFR obstacle margin over high or mountainous terrain?', '["2,000 ft above the highest obstacle within 8 km", "500 ft within 600 m", "1,000 ft within 8 km", "1,500 ft within 5 km"]'::jsonb, 0, 'Over high or mountainous terrain, the general IFR minimum is 2,000 ft above the highest obstacle within 8 km.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-123', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'Which radiotelephony word indicates an urgency condition?', '["MAYDAY", "PAN PAN", "SOS", "WILCO"]'::jsonb, 1, 'PAN PAN is the radiotelephony urgency signal.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-124', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What is the first visual response to the interceptor''s follow-me signal?', '["Rock the wings, flash navigation lights and follow", "Lower the landing gear immediately", "Make an abrupt 90 degree turn away", "Switch all lights regularly"]'::jsonb, 0, 'The intercepted aircraft acknowledges the follow-me signal by rocking its wings, flashing navigation lights and following.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-125', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What do red flashes from the tower mean to an aircraft in flight?', '["Cleared to land", "Return for landing", "Give way and circle", "Aerodrome unsafe, do not land"]'::jsonb, 3, 'Red flashes to an aircraft in flight mean the aerodrome is unsafe and the aircraft must not land.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-126', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'Which marshalling signal calls for an emergency stop?', '["Slowly lowering both arms", "Moving the wands outward", "Abruptly crossing the raised wands above the head", "Holding both arms at 45 degrees downward"]'::jsonb, 2, 'An emergency stop is signalled by abruptly raising and crossing the wands above the head.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-127', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What does a white dumbbell in the signal area mean?', '["Landing, take-off and taxiing are confined to runways and taxiways", "Gliders are operating", "Landing is prohibited", "Right-hand traffic is in use"]'::jsonb, 0, 'A white dumbbell means landing, take-off and taxiing are confined to runways and taxiways.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-128', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'After an IFR flight encounters visual conditions, when is IFR cancelled?', '["Automatically on entering VMC", "When cloud disappears from view", "When ATC first sees the aircraft", "Only after the pilot explicitly cancels IFR and reports the plan change"]'::jsonb, 3, 'Visual conditions do not cancel IFR automatically; the pilot must explicitly cancel IFR and communicate the flight-plan change.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-129', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'What sustained true-airspeed deviation is reported under Bali''s flight-plan change rule?', '["Mach 0.20 only", "Mach 0.02 or 10 kt", "Any 1 kt change", "Exactly 20 kt only"]'::jsonb, 1, 'A sustained deviation of Mach 0.02 or 10 kt from the filed true airspeed is reported.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-130', 'air-regulations', 'air-regulations-rules-of-the-air-vfr-ifr-and-signals', 'Rules of the Air: VFR, IFR and Signals', 'medium', 'Which navigation-light combination shows another aircraft approaching approximately head-on?', '["White only", "Red and white", "Red and green", "Green and white"]'::jsonb, 2, 'Seeing both red and green navigation lights indicates an approaching, approximately head-on aspect.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Rules of the Air: VFR, IFR and Signals''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-131', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'In which class are IFR and VFR admitted and all aircraft separated from each other?', '["Class A", "Class B", "Class D", "Class G"]'::jsonb, 1, 'Class B admits IFR and VFR and provides separation between every aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-132', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'Which second letter belongs to the Chennai FIR family in an Indian location indicator?', '["O", "A", "E", "I"]'::jsonb, 0, 'The Chennai FIR family uses O as the second letter, as in VOMM.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-133', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'What does prefix U indicate in an ATS route designator?', '["An advisory-only route", "A helicopter route", "A route or portion in upper airspace", "A route confined to VFR"]'::jsonb, 2, 'Prefix U identifies an ATS route or portion established in upper airspace.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-134', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'Which item must be read back when transmitted by voice?', '["An ATC route clearance", "A general airport advertisement", "A catering request", "A passenger announcement"]'::jsonb, 0, 'An ATC route clearance is safety-related information that must always be read back when transmitted by voice.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-135', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'Where may Voice ATIS never be transmitted?', '["On a discrete VHF frequency", "On the voice channel of an ILS", "On a suitable VOR voice channel", "By a continuous repetitive broadcast"]'::jsonb, 1, 'Voice ATIS must not be transmitted on the ILS voice channel.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-136', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'Which condition can directly trigger ALERFA?', '["A routine five-minute en-route delay", "Failure to land within five minutes after landing clearance with communication not restored", "A normal change of cruise level", "Arrival exactly on the estimated time"]'::jsonb, 1, 'Failure to land within five minutes after landing clearance, combined with loss of communication, is an ALERFA trigger.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-137', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'What is the minimum stated lower limit of a control area?', '["200 m or 700 ft above ground or water", "The surface in every case", "FL 290", "5 NM above the aerodrome"]'::jsonb, 0, 'Bali states that the lower limit of a control area must be at least 200 m or 700 ft above ground or water.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-138', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'What service is given to participating IFR flights in Class F airspace?', '["Aerodrome control only", "No service", "Full separation from every aircraft", "Air traffic advisory service plus flight information"]'::jsonb, 3, 'Participating IFR flights in Class F receive air traffic advisory service and flight information.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-139', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'What is the RVSM vertical band stated in the lesson?', '["FL 100 to FL 190", "FL 410 to FL 600", "Surface to FL 150", "FL 290 to FL 410 inclusive"]'::jsonb, 3, 'RVSM airspace extends from FL 290 through FL 410 inclusive.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-140', 'air-regulations', 'air-regulations-airspace-and-ats', 'Airspace and ATS', 'medium', 'What is essential traffic?', '["Any VFR aircraft parked on an apron", "Only an emergency aircraft", "Controlled traffic to which separation applies but the required minimum is not or will not be maintained", "Any aircraft outside an FIR"]'::jsonb, 2, 'Essential traffic is controlled traffic to which separation should apply but which is not, or will not be, separated by the required minimum.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Airspace and ATS''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-141', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'Which angular difference is classified as reciprocal track?', '["180 degrees", "020 degrees", "090 degrees", "320 degrees"]'::jsonb, 0, 'A reciprocal-track relationship is more than 135 degrees but less than 225 degrees, so 180 degrees qualifies.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-142', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What time minimum may be used when the leader is at least 40 kt faster and the stated same-track conditions are met?', '["15 minutes", "10 minutes", "5 minutes", "3 minutes"]'::jsonb, 3, 'The same-track same-level minimum may reduce to 3 minutes when the leader is at least 40 kt faster and all stated geometry conditions are met.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-143', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What is the basic DME or GNSS distance minimum for aircraft at the same level on the same track?', '["5 NM", "10 NM", "80 NM", "20 NM"]'::jsonb, 3, 'The basic common-reference DME or GNSS minimum for same-level same-track aircraft is 20 NM.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-144', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'Which technique requires turbojet aircraft to maintain an ATC-assigned speed expressed as Mach number?', '["Mach number technique", "Visual separation", "Geographical separation", "Stop-bar control"]'::jsonb, 0, 'Mach number technique uses assigned Mach numbers to stabilise relative speed and preserve longitudinal spacing.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-145', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What surveillance wake minimum applies to a Light aircraft following a Heavy aircraft?', '["3 NM", "4 NM", "6 NM", "5 NM"]'::jsonb, 2, 'A Light aircraft following a Heavy aircraft requires 6 NM surveillance wake spacing in the table.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-146', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What must ATC do before the current separation method becomes insufficient?', '["Wait for the aircraft to report a loss", "Establish another valid form of separation", "Cancel both flight plans", "Transfer all responsibility to the pilots"]'::jsonb, 1, 'ATC establishes another valid method before the existing separation becomes insufficient.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-147', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What does Bali state about cruise climb in Indian FIRs?', '["It is not permitted", "It is permitted above FL 290", "It needs only pilot agreement", "It is compulsory in RVSM airspace"]'::jsonb, 0, 'Bali states that cruise climb is not permitted in Indian FIRs.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-148', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'For aircraft climbing or descending on reciprocal tracks without lateral separation, how long is vertical separation protected around estimated passing?', '["Five minutes before only", "Five minutes after only", "At least 10 minutes before and 10 minutes after", "Until the first position report"]'::jsonb, 2, 'Vertical separation is provided for at least 10 minutes before and after the estimated passing time.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-149', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'What is the normal horizontal surveillance minimum stated by Bali?', '["3 NM everywhere", "5 NM", "10 NM", "20 NM"]'::jsonb, 1, 'Bali states 5 NM as the normal horizontal surveillance minimum, with 3 NM only where specifically authorised.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-150', 'air-regulations', 'air-regulations-separation', 'Separation', 'medium', 'Which category includes aircraft above 7,000 kg but below 136,000 kg maximum take-off mass?', '["SUPER", "HEAVY", "LIGHT", "MEDIUM"]'::jsonb, 3, 'The MEDIUM category covers aircraft above 7,000 kg but below 136,000 kg.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-151', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'For a straight-in arrival, until when may a departure take off in any direction?', '["Until 3 minutes before the arrival reaches the runway", "Until the arrival crosses the final approach fix", "Until 5 minutes before the arrival is estimated over the instrument runway", "Until 10 minutes before touchdown"]'::jsonb, 2, 'A departure in any direction is permitted only until 5 minutes before the straight-in arrival is estimated over the instrument runway.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-152', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'Which situation can support reduced separation near an aerodrome?', '["The following crew has the preceding aircraft in sight and can maintain separation", "Both aircraft are using the same runway", "The controller has issued traffic information only", "The crews can hear each other on frequency"]'::jsonb, 0, 'One permitted case is the following crew reporting the preceding aircraft in sight and confirming that separation can be maintained.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-153', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'What Bali visibility figure applies to a Category C aeroplane requesting a visual approach, before comparison with the operating minimum?', '["2,800 m", "3,200 m", "5 km", "3,600 m"]'::jsonb, 1, 'Bali states 3,200 m for a Category C aeroplane, with the higher applicable operating minimum still governing.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-154', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'Up to what level may the specified own-separation-in-VMC climb or descent be cleared?', '["The transition level without limit", "FL 200", "5,000 ft", "3,050 m (10,000 ft)"]'::jsonb, 3, 'The clearance is for a specified portion at or below 3,050 m, which is 10,000 ft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-155', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'At what expected delay does Bali require an EAT to be determined?', '["10 minutes or more", "15 minutes or more", "30 minutes or more", "5 minutes or more"]'::jsonb, 0, 'An EAT is determined when the arriving aircraft is expected to be delayed by 10 minutes or more.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-156', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'When is a revised EAT transmitted without delay under Bali''s normal threshold?', '["Whenever it changes by 2 minutes", "Only after a 30-minute hold", "When it differs by 5 minutes or more", "Only at the pilot''s request"]'::jsonb, 2, 'The normal revision threshold is a difference of 5 minutes or more, unless a smaller agreed period applies.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-157', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'What departure information is passed without delay when its status changes?', '["A visual or non-visual aid essential for take-off and climb", "The next day''s forecast", "The operator''s stand allocation", "The destination customs status"]'::jsonb, 0, 'A change in the operational status of an aid essential for take-off and climb is passed without delay.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-158', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'Which mean wind-component change is significant at the commencement of final approach according to Bali?', '["Head-wind 2 kt", "Cross-wind 10 kt", "Tail-wind 5 kt", "Tail-wind 2 kt"]'::jsonb, 3, 'Bali lists 2 kt as the significant change in the mean tail-wind component.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-159', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'What does an expected onward clearance time tell a held aircraft?', '["Its expected touchdown time", "When it can expect to leave the fix where it is being held", "When the runway will reopen", "When its flight plan expires"]'::jsonb, 1, 'Expected onward clearance time is the time at which the aircraft can expect to leave the fix where it is held.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-160', 'air-regulations', 'air-regulations-separation-near-aerodromes', 'Separation Near Aerodromes', 'medium', 'Which item is essential local traffic when it may create a collision hazard?', '["Only an airborne IFR aircraft", "Only vehicles actually on the runway", "An aircraft, vehicle or person on or near the runway", "Only an aircraft inside controlled airspace"]'::jsonb, 2, 'Essential local traffic includes an aircraft, vehicle or person on or near the runway when it may constitute a collision hazard.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Separation Near Aerodromes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-161', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'What must a pilot report with a start-up request under Bali''s procedure?', '["Persons on board including crew, plus security-check completion", "Only estimated taxi time", "Only the requested cruising level", "Passenger count excluding crew"]'::jsonb, 0, 'The start-up request includes total persons on board, including crew, and confirmation that the security check is complete.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-162', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'If a taxi limit lies beyond a runway, what must the clearance contain?', '["A request to report the runway in sight", "Permission to choose any crossing", "An explicit crossing clearance or instruction to hold short", "Only the taxiway designator"]'::jsonb, 2, 'A taxi clearance beyond a runway must explicitly clear the crossing or instruct the aircraft to hold short.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-163', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'What distance from the runway edge does Bali state for a runway 900 m or longer, unless the marked holding position governs?', '["15 m", "30 m", "75 m", "50 m"]'::jsonb, 3, 'For a runway 900 m or longer, Bali states the holding position or at least 50 m from the runway edge.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-164', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'What instruction follows when an obstruction threatens an aircraft already cleared to land?', '["Continue approach", "Go around", "Hold position", "Change runway after touchdown"]'::jsonb, 1, 'The controller instructs the landing aircraft to go around when a runway obstruction threatens safety.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-165', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'How is ATIS receipt normally acknowledged on first contact?', '["By reporting the current phonetic designator", "By repeating the complete broadcast", "By stating the observation time only", "By reading back the runway condition"]'::jsonb, 0, 'The pilot reports the current ATIS phonetic designator, after which ATC passes later changes or missing items.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-166', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'What is the tower''s first action when VFR operations are suspended?', '["Close the aerodrome to IFR traffic", "Cancel every flight plan", "Hold all VFR departures", "Switch off the runway lights"]'::jsonb, 2, 'The suspension procedure begins by holding all VFR departures.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-167', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'Which aircraft normally has priority between an aircraft on final and one ready to depart from the same runway?', '["The departure because it is ready", "The aircraft landing or in the final stages of approach", "Whichever called first", "The heavier aircraft"]'::jsonb, 1, 'An aircraft landing or in the final stages of approach normally has priority over a departure from the same or intersecting runway.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-168', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'When does Bali require aeronautical ground lights by day in India?', '["When visibility is 5,000 m or less", "Whenever cloud is below 1,500 ft", "Only during rain", "Only at the pilot''s home aerodrome"]'::jsonb, 0, 'From sunrise to sunset, Bali requires the lights when visibility in India is 5,000 m or less.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-169', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'A measured runway friction coefficient of 0.27 corresponds to which assessment?', '["Good, code 5", "Medium, code 3", "Poor, code 1", "Medium to poor, code 2"]'::jsonb, 3, 'A coefficient from 0.29 to 0.26 is medium to poor and carries code 2.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-170', 'air-regulations', 'air-regulations-aerodrome-control', 'Aerodrome Control', 'medium', 'To what approximate height does Bali extend the low-level wind-shear description?', '["500 ft", "1,000 ft", "1,500 ft", "3,000 ft"]'::jsonb, 2, 'Bali describes low-level wind shear from the surface to approximately 1,500 ft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodrome Control''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-171', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'How does multilateration calculate aircraft position?', '["From a single reflected radar pulse", "From the code selected by the pilot alone", "From a magnetic bearing reported by radio", "From differences in arrival time at several receivers"]'::jsonb, 3, 'MLAT calculates position from the time differences with which several receivers obtain the same transmission.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-172', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What communication condition normally supports an ATS surveillance service?', '["A listening watch on a company frequency only", "Direct two-way communication with the unit providing the service", "No radio contact after identification", "Communication only through another aircraft"]'::jsonb, 1, 'Direct two-way communication with the unit providing the surveillance service is normally required.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-173', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'Under the PSR departing-aircraft method, where should identification normally be established?', '["Within 1 NM of the end of the runway used", "Within 10 NM of the aerodrome boundary", "Only after reaching cruising level", "At the first FIR boundary"]'::jsonb, 0, 'The departing-aircraft method requires correlation within 1 NM of the runway end, with care to prevent confusion.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-174', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'Unless another minimum is prescribed, what ICAO surveillance separation minimum does Bali state?', '["2.0 NM", "3.0 NM", "5.0 NM", "10.0 NM"]'::jsonb, 2, 'Bali states 5.0 NM, or 9.3 km, as the general ICAO surveillance minimum unless otherwise prescribed.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-175', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What code is selected before entry into an Indian FIR if no SSR code has been assigned?', '["Mode A 7000", "Mode A3 2000", "Mode A 7600", "Mode C 2000"]'::jsonb, 1, 'Bali requires Mode A3 code 2000 before Indian FIR entry when no code has been assigned.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-176', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'Which special code indicates radio communication failure?', '["7000", "7500", "7700", "7600"]'::jsonb, 3, 'Mode A code 7600 indicates radio communication failure.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-177', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What altitude-data tolerance does Bali state for RVSM airspace?', '["Plus or minus 500 ft", "Plus or minus 300 ft", "Plus or minus 200 ft", "Zero error"]'::jsonb, 2, 'Bali uses a tolerance of plus or minus 200 ft for pressure-altitude data in RVSM airspace.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-178', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What normally happens after an in-flight transponder failure where carriage is mandatory?', '["The flight may continue to the next intended landing, subject to coordination", "The aircraft must land immediately on the nearest runway", "The flight automatically becomes VFR", "The pilot selects 0000 and continues without advising ATS"]'::jsonb, 0, 'A flight with an in-flight transponder failure is normally allowed to continue to its next intended landing, subject to coordination and safety restrictions.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-179', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What should a pilot do if an ACAS RA conflicts with an ATC vertical instruction?', '["Ignore the RA because ATC always has priority", "Average the two vertical rates", "Maintain level until ATC repeats the instruction", "Follow the RA and inform ATC as soon as workload permits"]'::jsonb, 3, 'The pilot follows the RA even when it conflicts with an ATC instruction, then informs ATC as soon as workload permits.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-180', 'air-regulations', 'air-regulations-ats-surveillance', 'ATS Surveillance', 'medium', 'What risk is addressed by a minimum safe altitude warning?', '["A duplicate transponder code", "Unsafe proximity to terrain or obstacles", "A predicted radio failure", "Wake turbulence only"]'::jsonb, 1, 'MSAW warns a controller that a tracked aircraft is at, or predicted to be at, an unsafe altitude relative to terrain or obstacles.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''ATS Surveillance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-181', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'What standard PDG is assumed unless another gradient is published?', '["2.5 percent", "3.3 percent", "0.8 percent", "5.0 percent"]'::jsonb, 1, 'The standard procedure design gradient is 3.3 percent.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-182', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'At what rate does MOC increase from zero at the DER?', '["0.8 percent of horizontal distance", "3.3 percent", "2.5 percent", "15 percent"]'::jsonb, 0, 'MOC increases at 0.8 percent of horizontal distance from the DER.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-183', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Which initial alignment defines a straight departure?', '["Exactly on the centre line", "Within 5 degrees", "Within 30 degrees", "Within 15 degrees of runway centre line"]'::jsonb, 3, 'A straight departure has an initial track within 15 degrees of runway centre-line alignment.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-184', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'What height above DER elevation is normally reached before an aeroplane begins a turning departure?', '["60 m, 200 ft", "90 m, 295 ft", "120 m, 394 ft", "300 m, 1,000 ft"]'::jsonb, 2, 'An aeroplane normally flies straight until at least 120 m, 394 ft, above DER elevation.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-185', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'How far from the runway beginning is an omnidirectional turn normally not initiated sooner?', '["600 m", "150 m", "3.5 km", "10 km"]'::jsonb, 0, 'The basic omnidirectional design does not initiate a turn sooner than 600 m from the runway beginning.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-186', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Where does a SID normally terminate?', '["At the first turn", "At the first en-route fix, facility or waypoint", "At 3,000 ft", "At the control-zone boundary"]'::jsonb, 1, 'A SID terminates at the first fix, facility or waypoint of the en-route phase.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-187', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'How does RNAV normally fly a fly-by waypoint?', '["It crosses before turning", "It waits for a radio call", "It ignores the waypoint in wind", "It anticipates the turn to intercept the next leg"]'::jsonb, 3, 'At a fly-by waypoint, RNAV anticipates the turn and intercepts the next leg smoothly.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-188', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Who develops the contingency procedure for an engine failure after V1?', '["The operator", "The procedure designer", "The tower", "The database supplier"]'::jsonb, 0, 'The operator is responsible for the engine-failure contingency procedure after V1.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-189', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Which procedure delays acceleration to reduce noise close to the aerodrome?', '["Normal en-route climb", "NADP 1", "Omnidirectional departure", "NADP 2"]'::jsonb, 1, 'NADP 1 delays acceleration and clean-up to reduce close-in noise.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-190', 'air-regulations', 'air-regulations-instrument-departures', 'Instrument Departures', 'medium', 'Below which height should the first noise-driven action not begin?', '["400 ft above aerodrome elevation", "3,000 ft above aerodrome elevation", "800 ft above aerodrome elevation", "120 m above DER"]'::jsonb, 2, 'The first noise-driven thrust or acceleration action should not begin below 800 ft above aerodrome elevation.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Departures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-191', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'What obstacle clearance does an MSA or TAA provide within its 25 NM area?', '["At least 600 m in every case", "At least 150 m, 492 ft", "Exactly 50 m, 164 ft", "At least 300 m, 1,000 ft"]'::jsonb, 3, 'An MSA or TAA provides at least 300 m, 1,000 ft, obstacle clearance within 25 NM.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-192', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'What is the maximum normal initial-segment intercept angle for a precision approach?', '["30 degrees", "90 degrees", "45 degrees", "120 degrees"]'::jsonb, 1, 'The precision initial-segment intercept angle is limited to 90 degrees.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-193', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'Which point begins the final segment of a precision approach?', '["MAPt", "IAF", "FAP", "FAF"]'::jsonb, 2, 'The FAP is where the intermediate altitude meets the precision glide path and the final segment begins.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-194', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'What is the optimum final-approach descent angle with a FAF?', '["3.0 degrees", "2.5 degrees", "3.7 degrees", "5.7 degrees"]'::jsonb, 0, 'The optimum is 3.0 degrees, equivalent to about 5.2 percent or 318 ft per NM.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-195', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'Which operational minimum is used for a non-precision approach?', '["DA/H only", "MDA/H", "Transition level", "OCA/H as the operational minimum in every case"]'::jsonb, 1, 'An NPA uses MDA/H; OCA/H is the design value from which the operational minimum is derived.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-196', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'What is the normal minimum missed-approach climb gradient?', '["0.8 percent", "3.3 percent", "5.2 percent", "2.5 percent"]'::jsonb, 3, 'The standard missed-approach construction uses a minimum climb gradient of 2.5 percent.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-197', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'What should the pilot do first if visual reference is lost while circling?', '["Descend to regain the runway", "Begin a climbing turn towards the landing runway and aerodrome", "Continue at MDA/H indefinitely", "Turn directly away from the aerodrome"]'::jsonb, 1, 'The circling missed approach begins with a climbing turn towards the landing runway and aerodrome before joining the published missed track.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-198', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'How long is the outbound holding leg at or below 14,000 ft in still air?', '["One minute", "One and one-half minutes", "Two minutes", "Thirty seconds"]'::jsonb, 0, 'At or below 14,000 ft, the standard outbound holding time is one minute.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-199', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'Which entry flies 30 degrees from the reciprocal inbound track on the holding side?', '["Direct", "Parallel", "Offset", "DME arc"]'::jsonb, 2, 'The offset entry flies a track 30 degrees from the reciprocal on the holding side.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-200', 'air-regulations', 'air-regulations-instrument-approaches-and-holding', 'Instrument Approaches and Holding', 'medium', 'Which statement describes Mode 2 parallel approaches?', '["Approaches are independent with no adjacent radar minimum", "One runway is reserved for departures", "Only simultaneous departures are permitted", "Radar separation minima are prescribed between adjacent approaches"]'::jsonb, 3, 'Mode 2 is the dependent parallel-approach mode, so radar separation minima are prescribed between adjacent approaches.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Instrument Approaches and Holding''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-201', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'What is QNE?', '["The current sea-level pressure", "The fixed value 1013.2 hPa", "The pressure at runway level", "The expected touchdown indication with standard pressure set"]'::jsonb, 3, 'QNE is the calculated altimeter indication at touchdown when standard pressure is set.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-202', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'When climbing, where is the altimeter changed from QNH to standard pressure?', '["At the transition level", "When passing the transition altitude", "At the lowest usable flight level only", "At the destination QNH boundary"]'::jsonb, 1, 'On climb, standard pressure is set when passing the transition altitude.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-203', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'What is the lowest transition altitude stated by Bali for India?', '["4,000 ft", "3,000 ft", "5,000 ft", "FL 040"]'::jsonb, 0, 'Bali states that the lowest transition altitude in India is 4,000 ft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-204', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'How is the lowest usable flight level related to minimum flight altitude?', '["It is always one level below it", "It is unrelated to it", "It corresponds to or lies immediately above it", "It is always FL 100"]'::jsonb, 2, 'The lowest usable flight level corresponds to, or lies immediately above, the established minimum flight altitude.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-205', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'What setting is normally used en route above transition altitude?', '["QFE", "1013.2 hPa", "Destination QNH", "QNE"]'::jsonb, 1, 'Above transition altitude after changeover, 1013.2 hPa is used and vertical position is reported as a flight level.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-206', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'What is Bali''s pre-flight tolerance for an altimeter with a 0 to 30,000 ft test range?', '["Plus or minus 20 ft", "Plus or minus 100 ft", "Plus or minus 80 ft", "Plus or minus 60 ft"]'::jsonb, 3, 'For a test range of 0 to 30,000 ft, Bali gives a tolerance of plus or minus 60 ft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-207', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'What happens to true altitude when temperature is colder than standard at a constant indicated altitude?', '["It becomes higher than indicated", "It remains exactly equal", "It becomes lower than indicated", "It changes only above FL 410"]'::jsonb, 2, 'In colder-than-standard air, pressure surfaces contract and true altitude is lower than indicated.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-208', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'Which IFR family normally applies to magnetic tracks from 180 through 359 degrees?', '["Odd thousands", "Even thousands", "Odd thousands plus 500 ft", "Any level selected without ATC"]'::jsonb, 1, 'Tracks from 180 through 359 degrees use the even-thousand IFR family.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-209', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'Which statement about transition level is correct?', '["It is fixed for the State", "It is always equal to transition altitude", "It is selected by the pilot after take-off", "It changes with QNH"]'::jsonb, 3, 'Transition level changes with QNH so the transition layer remains protected.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-210', 'air-regulations', 'air-regulations-altimeter-setting', 'Altimeter Setting', 'medium', 'If a pressure setting higher than the correct value is set, what is the main hazard?', '["The aircraft is lower than indicated", "The aircraft is always higher than indicated", "The altimeter reads zero", "The flight level becomes an altitude automatically"]'::jsonb, 0, 'A setting that is too high makes the altimeter over-read, so the aircraft is lower than indicated.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Altimeter Setting''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-211', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'Which three principal parts form an AIP?', '["GEN, MET and SAR", "GEN, ENR and AD", "RAC, COM and AD", "AGA, FAL and MAP"]'::jsonb, 1, 'The AIP is divided into GEN, ENR and AD.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-212', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'A temporary change will last four months. Which product normally carries it?', '["An AIP supplement", "Only a monthly checklist", "Only an AIC", "A permanent AIP amendment"]'::jsonb, 0, 'An AIP supplement carries a temporary change of three months or longer.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-213', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'Which Indian NOTAM series does Bali associate with general and lasting information affecting aircraft operations?', '["Series A", "Series B", "Series D", "Series G"]'::jsonb, 3, 'Bali describes Series G as carrying general and lasting information affecting aircraft operations.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-214', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'What does Item E of a NOTAM contain?', '["The operational text in standard plain language and abbreviations", "Only the upper flight level", "Only the ICAO location indicator", "The filing signature"]'::jsonb, 0, 'Item E contains the operational text, expressed with standard language and abbreviations.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-215', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'What is the interval between common AIRAC effective dates?', '["42 days", "14 days", "28 days", "56 days"]'::jsonb, 2, 'AIRAC common effective dates occur at intervals of 28 days.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-216', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'Which special-series message reports operationally significant volcanic activity or volcanic ash?', '["PIB", "ASHTAM", "SNOWTAM", "AIC"]'::jsonb, 1, 'ASHTAM reports an operationally significant change in volcanic activity, eruption or ash cloud.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-217', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'What is a PIB?', '["A plain-language pre-flight summary of current NOTAM and urgent information", "A permanent amendment to the AIP", "A volcanic alert message", "A chart amendment record"]'::jsonb, 0, 'A PIB is a plain-language pre-flight summary of current NOTAM and other urgent information.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-218', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'What is the main purpose of WGS 84 in aeronautical information?', '["To define NOTAM series letters", "To replace all altimeter settings", "To provide one common geodetic datum for published coordinates", "To set AIRAC dates"]'::jsonb, 2, 'WGS 84 provides a common geodetic datum for coordinates used by charts, databases and navigation systems.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-219', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'When should a trigger NOTAM become effective?', '["One month after the supplement", "When the next checklist is printed", "Seven days before every amendment", "On the same effective date as the AIRAC amendment or supplement"]'::jsonb, 3, 'A trigger NOTAM comes into force on the same effective date as the AIRAC amendment or supplement it announces.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-220', 'air-regulations', 'air-regulations-aeronautical-information', 'Aeronautical Information', 'medium', 'What should a crew report through the post-flight information process?', '["Only passenger complaints", "Observed defects in navigation facilities and operational hazards", "Only forecast weather errors", "Only a late arrival"]'::jsonb, 1, 'Post-flight information includes observed defects in navigation facilities and hazards such as birds or wildlife near an aerodrome.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aeronautical Information''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-221', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'What is the minimum RESA length stated in the lesson?', '["60 m", "90 m", "120 m", "240 m"]'::jsonb, 1, 'The RESA extends at least 90 m from the end of the runway strip.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-222', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'Which relationship normally defines ASDA?', '["LDA plus clearway", "TODA plus RESA", "TORA minus stopway", "TORA plus stopway"]'::jsonb, 3, 'ASDA normally equals TORA plus any available stopway.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-223', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'At a runway and taxiway intersection, which markings continue?', '["Taxiway markings only", "Runway markings", "Neither set", "Both sets without interruption"]'::jsonb, 1, 'Runway markings continue through a runway and taxiway intersection, while taxiway markings are interrupted.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-224', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'How is a permanently displaced threshold shown?', '["By white arrows leading to a transverse white threshold stripe", "Only by yellow taxiway lines", "By a red stop bar painted on the runway", "By removing every centre-line marking"]'::jsonb, 0, 'White arrows lead to the transverse white stripe that marks a displaced threshold.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-225', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'How far from the threshold does an aiming-point marking begin when LDA is 2,400 m or more?', '["300 m", "150 m", "250 m", "400 m"]'::jsonb, 3, 'For an LDA of 2,400 m or more, the aiming-point marking starts 400 m from the threshold.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
