INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-227', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'What is the diameter of a VOR aerodrome-checkpoint circle?', '["3 m", "15 m", "9 m", "6 m"]'::jsonb, 3, 'The VOR aerodrome-checkpoint circle is 6 m in diameter.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
