INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-229', 'air-regulations', 'air-regulations-aerodromes-markings', 'Aerodromes: Markings', 'medium', 'What does a yellow inscription on a black sign identify?', '["The current location", "A runway-exit direction", "A prohibited area", "A mandatory runway limit"]'::jsonb, 0, 'A yellow inscription on black is a location sign showing the current taxiway, runway or pavement.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Markings''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
