INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-233', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'What does an illuminated stop bar require?', '["Cross after a voice clearance", "Follow the green centre line without stopping", "Turn onto the runway immediately", "Stop and do not cross while it remains illuminated"]'::jsonb, 3, 'An illuminated red stop bar is a stop instruction and must not be crossed.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-234', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'Which obstacle surface protects the initial take-off climb?', '["Inner horizontal surface", "Take-off climb surface", "Conical surface", "Transitional surface only"]'::jsonb, 1, 'The take-off climb surface is the inclined, widening plane beyond the runway or clearway end.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-235', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'How are high-intensity obstacle lights displayed?', '["Flashing white", "Fixed red", "Flashing blue", "Fixed yellow"]'::jsonb, 0, 'High-intensity obstacle lights are flashing white and may be used by day as well as night.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-236', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'Which overall-length band defines RFF category 8?', '["39 m to below 49 m", "61 m to below 76 m", "49 m to below 61 m", "76 m to below 90 m"]'::jsonb, 2, 'Category 8 covers overall lengths from 49 m up to, but not including, 61 m.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-237', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'What can happen when highest-category movements are fewer than 700 in the busiest consecutive three months?', '["Protection may be one category lower", "The fire station may close", "Dry chemical agent is no longer required", "The runway becomes non-instrument"]'::jsonb, 0, 'Subject to the stated condition, the protection provided may be one category below the determined category.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-238', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'Which item belongs in a disabled-aircraft removal plan?', '["A new runway-designation method", "Only passenger compensation arrangements", "A replacement flight plan", "A coordinator and available lifting or towing resources"]'::jsonb, 3, 'The removal plan identifies a coordinator, equipment, routes, communications and recovery information.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-239', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'What is a principal purpose of apron management?', '["Issue airworthiness certificates", "Prevent collisions and coordinate apron movement", "Publish instrument minima", "Allocate aircraft nationality marks"]'::jsonb, 1, 'Apron management regulates movement to prevent collisions and coordinates apron entry, exit and vehicle activity.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-240', 'air-regulations', 'air-regulations-aerodromes-lighting-and-services', 'Aerodromes: Lighting and Services', 'medium', 'What is a primary control for wildlife hazard?', '["Switch off every runway light", "Permit food waste near the runway", "Manage habitat and attractants, then monitor and disperse wildlife", "Replace all taxiway markings"]'::jsonb, 2, 'Wildlife risk is reduced through habitat and attractant control, surveillance, dispersal and reporting.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Aerodromes: Lighting and Services''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-241', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'Who makes the final decision about admitting a permitted person to the flight deck?', '["The passenger", "The handling agent", "The commander", "The meteorological office"]'::jsonb, 2, 'The commander retains the final responsibility for admission to the flight deck.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-242', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'What additive produces Restricted AOM from Normal AOM in Bali?', '["50 ft and 200 m", "100 ft and 400 m", "No fixed additive", "200 ft and 800 m"]'::jsonb, 1, 'Restricted AOM adds 100 ft to DA/H or MDA/H and 400 m to visibility or RVR.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-243', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'What vertical separation is applied in RVSM airspace from FL 290 to FL 410 inclusive?', '["1,000 ft", "2,000 ft", "500 ft", "3,000 ft"]'::jsonb, 0, 'RVSM applies 1,000 ft vertical separation between FL 290 and FL 410 inclusive.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-244', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'Which statement correctly compares MEL and MMEL?', '["Neither requires approval", "The MMEL is written for one individual flight", "The MEL cancels aircraft limitations", "The operator MEL cannot be less restrictive than the MMEL"]'::jsonb, 3, 'An operator''s approved MEL is derived from and cannot be less restrictive than the aircraft-type MMEL.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-245', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'Below which compartment pressure must oxygen cover crew and passengers for any period?', '["700 hPa", "620 hPa", "850 hPa", "1,013 hPa"]'::jsonb, 1, 'For any period below 620 hPa, oxygen must be available for crew and passengers.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-246', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'What is turbine-aeroplane final reserve fuel?', '["15 minutes at cruise speed", "45 minutes at holding speed at sea level", "30 minutes at holding speed 1,500 ft above the aerodrome", "Five per cent of taxi fuel"]'::jsonb, 2, 'For a turbine aeroplane, final reserve is 30 minutes at holding speed 1,500 ft above aerodrome elevation in standard conditions.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
