INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-248', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'How long must FDTL duty and rest records be retained?', '["Eighteen months", "Twelve months", "Twenty-four months", "Six months"]'::jsonb, 0, 'Bali states that records of duties and rest periods are kept for 18 months.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-249', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'What is the maximum two-pilot FDP for four landings in Bali''s table?', '["11 hours", "12 hours 30 minutes", "12 hours", "13 hours"]'::jsonb, 2, 'For four landings, the table permits 8 hours flight time and a maximum FDP of 12 hours.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-250', 'air-regulations', 'air-regulations-operational-procedures', 'Operational Procedures', 'medium', 'Which term means block time from first movement for take-off until final rest after flight?', '["Standby", "Flight time", "Duty period", "Rest period"]'::jsonb, 1, 'Flight time is block-to-block time from first movement for take-off until final rest after landing.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-251', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'What should a pilot do first when exposed to a strong laser beam on approach?', '["Descend below the beam without informing ATC", "Stare at the source to identify it", "Switch off all cockpit lighting", "Look away and maintain control using instruments"]'::jsonb, 3, 'The pilot should look away from the beam, maintain control on instruments and transfer control if needed.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-252', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'Which agent principle is correct for an energised class C electrical fire?', '["Use an approved nonconducting agent", "Use only metal-fire powder", "Use a conducting water jet", "Add fuel to cool the wiring"]'::jsonb, 0, 'A class C electrical fire requires an approved nonconducting agent such as halon or carbon dioxide.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-253', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'What is the immediate crew priority after explosive decompression at high altitude?', '["Complete the passenger manifest", "Ask ATC for a route shortcut", "Put on oxygen masks and control the aircraft", "Inspect the cargo hold"]'::jsonb, 2, 'The crew first put on oxygen masks and control the aircraft before communication and assessment.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-254', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'Which sequence describes a microburst encounter on approach?', '["Tailwind, updraft, headwind", "Tailwind gain followed by calm air", "Continuous headwind only", "Headwind gain, downdraft, tailwind loss"]'::jsonb, 3, 'A microburst typically gives a headwind gain, then a downdraft, followed by a dangerous tailwind loss.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-255', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'When are wingtip vortices strongest?', '["When the generating aircraft is heavy, clean and slow", "When it is light, dirty and fast", "Only during taxi", "Only above the tropopause"]'::jsonb, 0, 'Wake vortices are strongest when the generating aircraft is heavy, clean and slow.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-256', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'What surveillance wake minimum applies to an A380 followed by a Light aircraft in Bali''s table?', '["5 NM", "8 NM", "6 NM", "10 NM"]'::jsonb, 1, 'Bali''s surveillance table gives 8 NM for an A380 followed by a Light aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-257', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'What vertical position is required for traffic behind a fuel-jettisoning aircraft within the protected trail area?', '["Only 500 ft below", "Exactly the same level", "At least 1,000 ft above or 3,000 ft below", "At least 3,000 ft above or 1,000 ft below"]'::jsonb, 2, 'Traffic behind within the protected distance remains at least 1,000 ft above or 3,000 ft below.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-258', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'What mainly characterises dynamic hydroplaning?', '["The tyre gains extra friction from water", "Water pressure lifts the tyre from the pavement", "The runway slope disappears", "The wheel brakes become more effective"]'::jsonb, 1, 'In dynamic hydroplaning, water pressure lifts the tyre from the pavement and greatly reduces braking and directional control.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-259', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'Which dangerous-goods class contains corrosives?', '["Class 3", "Class 9", "Class 6", "Class 8"]'::jsonb, 3, 'Class 8 is the dangerous-goods class for corrosive substances.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-260', 'air-regulations', 'air-regulations-operational-hazards', 'Operational Hazards', 'medium', 'Which organisation issues volcanic ash advisory information for its assigned area?', '["A Volcanic Ash Advisory Centre", "The aerodrome fire service", "The aircraft manufacturer", "The baggage-handling agent"]'::jsonb, 0, 'A Volcanic Ash Advisory Centre analyses the hazard and issues volcanic ash advisory information.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Operational Hazards''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-261', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'What does INCERFA mean?', '["The aircraft has requested medical assistance", "The aircraft is certainly destroyed", "Rescue work has been completed", "Uncertainty exists about the safety of an aircraft and its occupants"]'::jsonb, 3, 'INCERFA is the uncertainty phase, in which uncertainty exists about aircraft and occupant safety.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-262', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'Which statement best describes DETRESFA action by an RCC?', '["Wait for a scheduled report before acting", "Initiate the coordinated search and rescue plan without delay", "Close the flight plan automatically", "Transfer all responsibility to the operator"]'::jsonb, 1, 'During DETRESFA the RCC initiates the coordinated search and rescue plan without delay.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-263', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'Who normally takes initial on-scene charge when the first arriving aircraft is not a dedicated SAR aircraft?', '["The nearest airline dispatcher", "The last aircraft to arrive", "The pilot of the first aircraft", "The aerodrome fire chief"]'::jsonb, 2, 'The pilot of the first aircraft takes temporary on-scene charge until agreed transfer or arrival of a dedicated SAR aircraft.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-264', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'Which search pattern is best suited to a precisely known datum and compact area?', '["Expanding square", "Random visual search", "Track crawl", "Parallel sweep only"]'::jsonb, 0, 'An expanding-square search begins near an accurate datum and expands systematically through a compact area.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-265', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'How does an aircraft direct a surface craft toward survivors when radio communication is unavailable?', '["Land beside the vessel", "Circle it, cross close ahead while attracting attention, then fly the required direction", "Cross its wake close astern and depart", "Flash the landing lights once and climb"]'::jsonb, 1, 'The directing sequence is to circle, cross close ahead while attracting attention, and then head toward the distress site.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-266', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'What does the survivor ground symbol X mean?', '["Proceed in this direction", "No or negative", "Operation completed", "Require medical assistance"]'::jsonb, 3, 'The survivor symbol X means require medical assistance.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-267', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'What is the primary role of the 406 MHz component of an ELT?', '["Satellite distress alerting with coded identity", "Routine air-to-air communication", "ILS localiser guidance", "Weather-radar calibration"]'::jsonb, 0, 'The 406 MHz ELT transmission provides coded satellite distress alerting through COSPAS-SARSAT.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-268', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'What is the defining assessment in ALERFA?', '["No concern exists", "The operation is complete", "Apprehension exists about aircraft and occupant safety", "A forced landing is certain"]'::jsonb, 2, 'ALERFA is the alert phase, when apprehension exists about the safety of the aircraft and occupants.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-269', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'How does an aircraft acknowledge a ground signal at night?', '["By rocking the wings only", "By circling exactly three times", "By transmitting IDENT", "By flashing landing lights twice, or navigation lights twice if needed"]'::jsonb, 3, 'At night the aircraft flashes its landing lights twice or, if unavailable, switches navigation lights on and off twice.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-270', 'air-regulations', 'air-regulations-search-and-rescue', 'Search and Rescue', 'medium', 'Which streamer colour identifies food and water in droppable SAR supplies?', '["Red", "Blue", "Yellow", "Black"]'::jsonb, 1, 'Blue streamers identify packages containing food and water.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Search and Rescue''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-271', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Which event is a typical serious incident?', '["A near collision requiring an avoidance manoeuvre", "A routine gate delay", "A passenger missing a connection", "Normal use of reverse thrust"]'::jsonb, 0, 'A near collision requiring avoidance is a typical serious incident because an accident nearly occurred.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-272', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'What is the correct timing principle for notifying AAIB?', '["Wait until every fact is confirmed", "Notify only after the final report", "Notify promptly by the quickest means and within Bali''s 24-hour limit", "Notify at the next licence renewal"]'::jsonb, 2, 'Known facts are notified promptly by the quickest means, with Bali''s outer limit of 24 hours after awareness.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-273', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Which State normally institutes an investigation for an occurrence in its territory?', '["State of Design", "State of Occurrence", "State of Manufacture", "State of Operator"]'::jsonb, 1, 'The State of Occurrence normally institutes and conducts the territorial investigation.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-274', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Who normally investigates an accident in India under the 2017 Rules?', '["The aerodrome operator alone", "The insurance company", "The aircraft manufacturer", "AAIB"]'::jsonb, 3, 'AAIB investigates accidents under the Aircraft (Investigation of Accidents and Incidents) Rules, 2017.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-275', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'What takes priority over preserving an untouched wreckage site?', '["Public access for photographs", "Release of baggage without recording", "Rescue of people and removal of immediate danger", "Commercial recovery of parts"]'::jsonb, 2, 'Lifesaving rescue and removal of immediate danger take priority, with necessary disturbance documented.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-276', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'What is ADREP?', '["ICAO''s Accident and Incident Data Reporting system", "An aerodrome lighting system", "A flight crew licence", "A runway-friction code"]'::jsonb, 0, 'ADREP is ICAO''s standardised Accident and Incident Data Reporting system.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-277', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Which statement describes just culture?', '["Every error is punished identically", "Proportionate honest actions are protected while wilful misconduct remains accountable", "No one can ever be disciplined", "Only anonymous reports are accepted"]'::jsonb, 1, 'Just culture protects proportionate honest actions while retaining accountability for wilful misconduct and similarly unacceptable behaviour.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-278', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Who may also notify AAIB besides the pilot or operator?', '["The aerodrome operator, ATS unit and DGCA where applicable", "Only passengers", "Only the manufacturer", "Only foreign embassies"]'::jsonb, 0, 'The aerodrome operator, ATS unit concerned and DGCA where applicable also submit notification to AAIB.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-279', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'Which Indian body normally investigates other incidents not assigned to AAIB by the serious-incident criteria?', '["The District Magistrate", "The airport retailer", "The State of Manufacture", "DGCA"]'::jsonb, 3, 'DGCA normally investigates incidents and serious incidents not assigned to AAIB, unless AAIB takes over.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-280', 'air-regulations', 'air-regulations-accident-investigation', 'Accident Investigation', 'medium', 'What is the purpose of a safety recommendation?', '["To establish criminal guilt", "To set insurance premiums", "To address a safety deficiency and prevent recurrence", "To cancel every certificate involved"]'::jsonb, 2, 'A safety recommendation proposes preventive action to address an identified safety deficiency.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Accident Investigation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
