INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-282', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'What is the purpose of a direct transit area?', '["To store unclaimed cargo", "To conduct aircraft maintenance", "To replace the runway holding point", "To let transit passengers remain under supervision without applying for entry"]'::jsonb, 3, 'A direct transit area lets passengers remain under authority supervision during transfer without applying to enter the State.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
