INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-285', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'Which statement correctly distinguishes an inadmissible person from a deportee?', '["An inadmissible person must be airline crew", "They are identical terms", "A deportee is always a transit passenger", "An inadmissible person is refused entry, while a deportee is formally ordered to leave after admission or presence"]'::jsonb, 3, 'Inadmissibility is refusal of entry; deportation is formal removal of a person already admitted or present.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-286', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'What is disinsection intended to control?', '["Runway rubber deposits", "Aircraft corrosion", "Insects capable of carrying disease or pests", "Passenger baggage weight"]'::jsonb, 2, 'Disinsection uses an approved treatment to control insects that can carry disease or agricultural pests.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-287', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'Which channel is used in India by an arriving passenger with no dutiable goods?', '["Red Channel", "Green Channel", "Cargo channel", "Diplomatic mail channel"]'::jsonb, 1, 'An arriving passenger with no dutiable goods uses the Green Channel and remains responsible for an accurate declaration.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-288', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'Which three standard aircraft documents are central to the chapter?', '["General Declaration, Passenger Manifest and Cargo Manifest", "Licence, medical and radio permit", "Load sheet, fuel sheet and journey log", "Weather chart, flight plan and tech log"]'::jsonb, 0, 'The standard facilitation documents are the General Declaration, Passenger Manifest and Cargo Manifest.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-289', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'Who normally arranges removal after a border authority refuses a passenger admission?', '["The aircraft manufacturer", "The meteorological office", "The operator under the State''s removal order", "The passenger''s hotel"]'::jsonb, 2, 'After the State refuses admission and issues the removal direction, the operator normally arranges carriage to the specified admissible point.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-290', 'air-regulations', 'air-regulations-facilitation', 'Facilitation', 'medium', 'What must happen before an international flight leaves India according to Bali''s national provision?', '["The cargo manifest must be destroyed", "All passengers must use the Red Channel", "The aircraft must be re-registered", "Immigration and customs clearance must be obtained on the General Declaration"]'::jsonb, 3, 'Bali states that immigration and customs authorities must clear the flight on the General Declaration before departure from India.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Facilitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-291', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'What does a security quality-control test establish?', '["Whether an aircraft can meet take-off performance", "Whether a control detects or prevents a simulated threat", "Whether a passenger has a visa", "Whether a route is economical"]'::jsonb, 1, 'A security test challenges a control under managed conditions to see whether it detects or prevents a simulated threat.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-292', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'What distinguishes a security restricted area from a general landside area?', '["It is a priority risk area with additional access and security controls", "It contains only shops", "It is always outside the airport fence", "It is open to every ticket holder"]'::jsonb, 0, 'A security restricted area is a priority risk area where additional access and security controls apply.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-293', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'What is required if screened passengers mix with unscreened persons after the screening point?', '["Only a new boarding card", "A head count only", "No action if the flight is ready", "The affected passengers and cabin baggage must be screened again"]'::jsonb, 3, 'Mixing breaks the sterile flow, so affected passengers and their cabin baggage must be screened again before boarding.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-294', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'When can screened cargo continue to be treated as secure?', '["Only when it travels with a passenger", "Even after an unexplained access breach", "Only while it remains protected from unauthorised interference", "Whenever its package is large"]'::jsonb, 2, 'Screened cargo retains secure status only while it remains protected from unauthorised interference.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-295', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'Which statement correctly compares an aircraft security check and search?', '["A search is the more thorough interior and exterior inspection", "They are identical terms", "A check is always more extensive", "Neither concerns suspicious objects"]'::jsonb, 0, 'An aircraft security search is the more thorough inspection of interior, exterior and defined concealed areas.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-296', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'Who must receive operationally necessary information about an authorised armed person aboard?', '["Every passenger", "The pilot-in-command", "Only the baggage handler", "No one after authorisation"]'::jsonb, 1, 'The pilot-in-command must receive the information needed to manage authorised armed carriage safely.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-297', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'What is the normal action when an unlawfully seized aircraft lands in a State?', '["Move all passengers to another flight without coordination", "Require immediate departure in every case", "Release it whenever the operator asks", "Retain it on the ground unless protection of human life requires departure"]'::jsonb, 3, 'The State normally retains the aircraft on the ground, with an exception when the overriding duty to protect human life requires departure.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-298', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'What is the AVSEC Panel''s central role?', '["Licensing Indian flight crew", "Operating airport screening lanes", "Advising ICAO on security standards, threats and Annex 17 amendments", "Investigating every baggage delay"]'::jsonb, 2, 'The AVSEC Panel advises ICAO on emerging threats, vulnerabilities, security standards and proposed Annex 17 amendments.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-299', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'Which national document coordinates security responsibilities and required controls across India?', '["The National Civil Aviation Security Programme", "The aircraft journey log", "The passenger manifest", "The meteorological watch plan"]'::jsonb, 0, 'The National Civil Aviation Security Programme coordinates national aviation security responsibilities, standards and controls.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('REG-300', 'air-regulations', 'air-regulations-security', 'Security', 'medium', 'Which recipients are explicitly part of the landing notification chain after an act of unlawful interference?', '["Only the departure airport shops", "The States of Registry and Operator, affected-national States and ICAO", "Only the aircraft manufacturer", "Only the next air traffic control unit"]'::jsonb, 1, 'The notification chain includes the States of Registry and Operator, relevant States connected to affected citizens and ICAO.', 'R.K. Bali Air Regulations / DGCA CAR, Chapter ''Security''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-046', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'easy', 'What is the standard sea-level temperature and pressure in the International Standard Atmosphere (ISA)?', '["+15°C and 1013.25 hPa", "0°C and 1000.0 hPa", "+20°C and 1013.25 hPa", "+15°C and 29.82 inHg"]'::jsonb, 0, 'In ISA, standard sea-level values are defined by ICAO as a temperature of +15°C (288.15 K), pressure of 1013.25 hPa (29.92 inHg), and density of 1.225 kg/m³.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''The Atmosphere''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-047', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'medium', 'What is the standard ISA temperature lapse rate in the troposphere up to 11 km (36,090 ft)?', '["1.0°C per 1,000 ft (3.0°C/km)", "1.98°C per 1,000 ft (6.5°C/km)", "3.0°C per 1,000 ft (9.8°C/km)", "0.5°C per 1,000 ft (1.5°C/km)"]'::jsonb, 1, 'In the standard troposphere, temperature decreases uniformly with altitude at a rate of 1.98°C per 1,000 ft (approximately 6.5°C per kilometre) up to the standard tropopause at 11,000 m (36,090 ft), where it remains constant at -56.5°C.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''The Atmosphere''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-048', 'aviation-meteorology', 'aviation-meteorology-the-atmosphere', 'The Atmosphere', 'hard', 'Why is the average tropopause altitude higher and colder over the Equator than over the Poles?', '["Due to greater rotational centrifugal force pushing cold air upward at the poles", "Because strong solar heating causes deep vertical convective overturning in the tropics, lifting the tropopause to ~16-18 km (-75°C to -80°C)", "Because the ozone layer is situated lowest at the equator", "Due to descending polar easterly wind currents cooling the upper stratosphere"]'::jsonb, 1, 'Intense thermal convection in equatorial and tropical regions pushes the tropopause up to 16-18 km (FL500-600) where temperatures drop to -75°C to -85°C. At the poles, where convective lifting is minimal, the tropopause sits at only 8-10 km with temperatures around -45°C to -50°C.', 'I.C. Joshi Aviation Meteorology, Chapter 1 ''The Atmosphere''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-049', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'easy', 'When an aircraft altimeter subscale is set to QNH, the altimeter indicates:', '["Height above the aerodrome elevation", "Altitude above Mean Sea Level (MSL)", "Pressure altitude relative to the 1013.25 hPa datum", "True height above the instantaneous ground level (AGL)"]'::jsonb, 1, 'QNH is the altimeter subscale setting obtained by reducing station pressure to mean sea level using ISA temperature lapse rates. Setting QNH causes the altimeter to read altitude above Mean Sea Level (MSL), reading aerodrome elevation when on the runway.', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-050', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'medium', 'An aircraft flies from a region of high atmospheric pressure to an area of low atmospheric pressure without resetting its altimeter. The altimeter will:', '["Overread (indicate higher than actual true altitude)", "Underread (indicate lower than actual true altitude)", "Indicate true altitude accurately regardless of pressure changes", "Remain unchanged while true airspeed decreases by 10%"]'::jsonb, 0, 'Flying ''high to low'' pressure without adjusting the subscale causes the aircraft to descend along the sloping isobaric surface. The altimeter continues sensing the same pressure and indicates the assigned altitude, meaning the altimeter is overreading (actual true altitude is lower: ''High to low, look out below'').', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-051', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'medium', 'What is the approximate vertical pressure gradient in the lower atmosphere near sea level?', '["1 hPa per 30 feet (27-30 ft/hPa)", "1 hPa per 100 feet", "1 hPa per 10 feet", "1 hPa per 500 feet"]'::jsonb, 0, 'In the lower levels of the atmosphere near sea level, 1 hPa (or 1 millibar) corresponds to approximately 27 to 30 feet (typically taken as 30 ft/hPa in standard DGCA computations). As altitude increases and air density drops, the vertical distance per hPa increases.', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-052', 'aviation-meteorology', 'aviation-meteorology-atmospheric-pressure', 'Atmospheric Pressure', 'hard', 'An aircraft cruises at FL100 (subscale 1013.25 hPa) with an outside air temperature of -25°C. ISA temperature at FL100 is -5°C. What is the aircraft''s approximate true altitude?', '["10,800 ft", "9,200 ft", "10,000 ft", "8,400 ft"]'::jsonb, 1, 'Temperature deviation is -25°C - (-5°C) = -20°C (ISA -20). The rule of thumb for temperature error is 4 feet per 1,000 feet per °C deviation. Height = 10,000 ft, so error = 4 * 10 * (-20) = -800 ft. True altitude = 10,000 - 800 = 9,200 ft. In cold air, true altitude is lower than indicated (''Cold air, beware'').', 'I.C. Joshi Aviation Meteorology, Chapter 2 ''Atmospheric Pressure''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-053', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'easy', 'A surface temperature inversion is characterized by:', '["Temperature increasing with altitude rather than decreasing", "Temperature dropping at more than the dry adiabatic lapse rate", "Constant temperature up to 10,000 ft", "Rapid formation of deep cumulus and cumulonimbus clouds"]'::jsonb, 0, 'A temperature inversion is an atmospheric condition where temperature increases with increasing altitude, inverting the normal tropospheric environmental lapse rate. It creates extremely stable conditions and traps pollutants, haze, or fog near the surface.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature & Heat''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-054', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'medium', 'At what time of day does the minimum surface air temperature typically occur under clear skies?', '["At midnight", "Shortly after sunrise", "Two hours before sunrise", "At 03:00 hours local time"]'::jsonb, 1, 'The minimum surface air temperature occurs shortly after sunrise (approximately 15 to 30 minutes post-sunrise) because terrestrial radiation continues to exceed incoming solar radiation until the sun rises high enough to balance heat loss.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature & Heat''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-055', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'hard', 'Which mechanism is primarily responsible for transferring heat from the Earth''s surface through the first few millimetres of the atmosphere?', '["Conduction", "Convection", "Advection", "Latent heat release"]'::jsonb, 0, 'Conduction transfers heat between the physical ground surface and the very thin microscopic boundary layer of air in direct molecular contact with it. Beyond this contact layer, convection and turbulent mixing take over as the dominant upward heat transfer mechanisms.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature & Heat''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-056', 'aviation-meteorology', 'aviation-meteorology-air-density', 'Air Density', 'easy', 'How does an increase in ambient temperature affect air density and aircraft takeoff performance?', '["Density decreases; takeoff run increases and climb rate decreases", "Density increases; takeoff run shortens and climb performance improves", "Density increases; true airspeed becomes lower for the same indicated airspeed", "Density remains unchanged because pressure compensates for temperature"]'::jsonb, 0, 'Warm air expands and becomes less dense. Lower air density reduces aerodynamic lift, engine thrust/power, and propeller efficiency, resulting in a longer takeoff ground roll and a lower rate of climb.', 'I.C. Joshi Aviation Meteorology, Chapter 4 ''Air Density''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-057', 'aviation-meteorology', 'aviation-meteorology-air-density', 'Air Density', 'hard', 'Given an airfield elevation of 3,000 ft, QNH 1003 hPa, and ambient temperature of +35°C, what is the approximate density altitude? (Take ISA at sea level = +15°C)', '["Approximately 6,200 ft", "Approximately 3,300 ft", "Approximately 4,500 ft", "Approximately 8,100 ft"]'::jsonb, 0, '1) Pressure altitude = Elevation + (1013 - QNH) * 30 = 3000 + (10) * 30 = 3300 ft. 2) ISA temp at 3300 ft = 15 - (3.3 * 2) = +8.4°C. 3) Temp deviation = +35°C - 8.4°C = +26.6°C. 4) Density altitude = Pressure Alt + (118 * temp dev) = 3300 + (118 * 26.6) = 3300 + 3138 ≈ 6,438 ft (approx 6,200 - 6,500 ft).', 'I.C. Joshi Aviation Meteorology, Chapter 4 ''Air Density''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-058', 'aviation-meteorology', 'aviation-meteorology-humidity', 'Humidity', 'medium', 'As ambient air temperature rises during the afternoon while moisture content remains constant, relative humidity will:', '["Decrease", "Increase", "Remain unchanged", "Reach 100% automatically"]'::jsonb, 0, 'Relative humidity is the ratio of actual water vapor pressure to the saturation vapor pressure. As temperature rises, saturation vapor pressure increases exponentially, meaning the air can hold more water vapor; thus relative humidity decreases.', 'I.C. Joshi Aviation Meteorology, Chapter 5 ''Humidity''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-059', 'aviation-meteorology', 'aviation-meteorology-stability-adiabatics', 'Stability & Adiabatics', 'easy', 'The Dry Adiabatic Lapse Rate (DALR) of an unsaturated parcel of air is approximately:', '["3.0°C per 1,000 ft (9.8°C/km)", "1.5°C per 1,000 ft (5.0°C/km)", "1.98°C per 1,000 ft (6.5°C/km)", "0.5°C per 1,000 ft (1.8°C/km)"]'::jsonb, 0, 'The Dry Adiabatic Lapse Rate (DALR) is constant at approximately 3.0°C per 1,000 ft (or 9.8°C per kilometre / ~1°C per 100 metres) for any dry or unsaturated rising or sinking parcel of air.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Stability & Adiabatics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-060', 'aviation-meteorology', 'aviation-meteorology-stability-adiabatics', 'Stability & Adiabatics', 'medium', 'Why is the Saturated Adiabatic Lapse Rate (SALR) always less than the Dry Adiabatic Lapse Rate (DALR)?', '["Latent heat of condensation is released into the saturated parcel as water vapor condenses, counteracting adiabatic cooling", "Water droplets absorb surrounding sensible heat during expansion", "Moist air has higher molecular weight than dry air", "Coriolis force retards upward vertical air motion"]'::jsonb, 0, 'When saturated air rises, condensation occurs, releasing the latent heat of vaporization (approx 2.5 x 10^6 J/kg). This released heat warms the parcel, partially offsetting adiabatic expansion cooling and lowering the cooling rate (SALR ~1.5°C/1,000 ft near sea level).', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Stability & Adiabatics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-061', 'aviation-meteorology', 'aviation-meteorology-stability-adiabatics', 'Stability & Adiabatics', 'hard', 'An environmental lapse rate (ELR) of 4.0°C per 1,000 ft indicates that the atmosphere is:', '["Absolutely unstable", "Absolutely stable", "Conditionally unstable", "Neutrally stable for unsaturated air"]'::jsonb, 0, 'DALR is 3°C/1000 ft and SALR is ~1.5°C/1000 ft. When the ELR (4.0°C/1000 ft) is greater than DALR, any displaced parcel (whether dry or saturated) will always be warmer and less dense than surrounding ambient air and will accelerate upward. This is absolute instability.', 'I.C. Joshi Aviation Meteorology, Chapter 6 ''Stability & Adiabatics''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-062', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'easy', 'Which cloud genus is classified as a high cloud with a mean base height above 20,000 ft (6,000 m)?', '["Cirrus (Ci)", "Altocumulus (Ac)", "Stratocumulus (Sc)", "Nimbostratus (Ns)"]'::jsonb, 0, 'High clouds (base above 20,000 ft / 6,000 m in temperate latitudes) include Cirrus (Ci), Cirrocumulus (Cc), and Cirrostratus (Cs), composed almost entirely of ice crystals.', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Clouds & Precipitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-063', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'medium', 'Continuous, widespread, steady rain or snow falling from an extensive, dark, overcast layer is typical of which cloud genus?', '["Nimbostratus (Ns)", "Cumulonimbus (Cb)", "Cirrocumulus (Cc)", "Altocumulus lenticularis (Ac len)"]'::jsonb, 0, 'Nimbostratus produces continuous, steady precipitation that reaches the ground, characterized by a thick, dark grey, diffuse overcast layer without lightning or hail.', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Clouds & Precipitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-064', 'aviation-meteorology', 'aviation-meteorology-clouds-precipitation', 'Clouds & Precipitation', 'hard', 'What is the physical difference between rain and drizzle?', '["Drizzle consists of uniform water droplets with diameter less than 0.5 mm that appear to float, whereas raindrops exceed 0.5 mm", "Drizzle originates from cirrus clouds while rain originates from cumuliform clouds", "Drizzle only occurs when the surface temperature is below freezing", "Raindrops always freeze upon surface contact while drizzle remains liquid"]'::jsonb, 0, 'By international WMO definition, drizzle consists of very small, numerous water droplets with diameters less than 0.5 mm falling almost exclusively from Stratus (St) clouds. Raindrops have diameters greater than 0.5 mm (up to ~6 mm max before aerodynamic breakup).', 'I.C. Joshi Aviation Meteorology, Chapter 7 ''Clouds & Precipitation''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-065', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'easy', 'What is Buys Ballot''s Law for an observer in the Northern Hemisphere?', '["If you stand with your back to the wind, low pressure is on your left", "If you stand with your back to the wind, low pressure is on your right", "Wind blows directly from low pressure toward high pressure", "Coriolis force always acts to the left of the wind vector"]'::jsonb, 0, 'Buys Ballot''s Law states that in the Northern Hemisphere, if an observer stands with their back to the wind, the area of lower atmospheric pressure is on their left (and higher pressure on their right). In the Southern Hemisphere, the reverse is true.', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-066', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'medium', 'The geostrophic wind is the theoretical wind resulting from an exact balance between which two forces?', '["Horizontal Pressure Gradient Force and Coriolis Force", "Centrifugal Force and Gravity", "Surface Friction and Pressure Gradient Force", "Thermal buoyancy and Coriolis Force"]'::jsonb, 0, 'The geostrophic wind represents straight, frictionless, steady horizontal flow where the horizontal Pressure Gradient Force (PGF) is exactly balanced by the Coriolis force.', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-067', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'hard', 'In the Northern Hemisphere, how does the surface wind compare with the 2,000 ft geostrophic wind due to ground friction?', '["Surface wind is backed (counter-clockwise) and has lower speed than 2,000 ft wind", "Surface wind is veered (clockwise) and has higher speed than 2,000 ft wind", "Surface wind blows parallel to isobars while 2,000 ft wind crosses isobars at 30°", "Surface wind is completely calm regardless of the isobaric gradient"]'::jsonb, 0, 'Surface friction retards wind speed, reducing the Coriolis force (which depends on speed). The Pressure Gradient Force dominates, deflecting the surface wind across isobars toward low pressure. In the Northern Hemisphere, this backs the wind (counter-clockwise, ~10° over water, ~30° over land) and reduces speed to ~50% of geostrophic value.', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-068', 'aviation-meteorology', 'aviation-meteorology-local-winds', 'Local Winds', 'easy', 'A katabatic wind is an airflow that:', '["Blows down a cold mountain slope or valley at night due to nocturnal radiative cooling", "Blows up a heated slope during the daytime", "Blows from sea to land during the late morning", "Circulates around a thermal low over flat desert terrain"]'::jsonb, 0, 'Katabatic winds are gravity-driven drainage winds of cold, dense air flowing downslope along mountains or hillsides at night after surface radiative cooling.', 'I.C. Joshi Aviation Meteorology, Chapter 9 ''Local Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-069', 'aviation-meteorology', 'aviation-meteorology-local-winds', 'Local Winds', 'medium', 'A sea breeze typically develops under which conditions and at what time of day?', '["Under sunny skies with weak synoptic winds, blowing onshore from sea to land, reaching peak intensity in mid-afternoon", "At night, blowing from land to sea due to cooling coastal terrain", "Only during deep monsoon depressions with heavy continuous rain", "Just before dawn when the sea surface temperature reaches its minimum"]'::jsonb, 0, 'During the day, solar heating warms the land faster than the adjacent sea. Air over the land expands and rises, forming a local low pressure area at the surface. Cooler, denser air moves onshore from the sea (sea breeze), reaching maximum strength between 13:00 and 16:00 local time.', 'I.C. Joshi Aviation Meteorology, Chapter 9 ''Local Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-070', 'aviation-meteorology', 'aviation-meteorology-visibility-fog', 'Visibility & Fog', 'easy', 'What meteorological conditions are most favorable for the formation of radiation fog?', '["Clear skies, high relative humidity near the ground, and light winds (2 to 8 knots)", "Strong gusty winds (over 25 knots), overcast cirrostratus, and dry air", "Warm air advecting rapidly over cold sea water in gale force conditions", "Deep convective updrafts during mid-day solar heating"]'::jsonb, 0, 'Radiation fog requires clear nocturnal skies (allowing maximum terrestrial radiation heat loss), high relative humidity, and light wind (2-8 knots) to provide just enough gentle turbulent mixing without dissipating the cooling layer.', 'I.C. Joshi Aviation Meteorology, Chapter 10 ''Visibility & Fog''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-071', 'aviation-meteorology', 'aviation-meteorology-visibility-fog', 'Visibility & Fog', 'hard', 'Runway Visual Range (RVR) is officially reported in a METAR when prevailing visibility drops below:', '["1,500 metres", "5,000 metres", "800 metres", "3,000 metres"]'::jsonb, 0, 'In accordance with ICAO Annex 3 and DGCA regulations, Runway Visual Range (RVR) is measured and reported when the horizontal visibility or RVR is less than 1,500 metres.', 'I.C. Joshi Aviation Meteorology, Chapter 10 ''Visibility & Fog''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-072', 'aviation-meteorology', 'aviation-meteorology-thunderstorms', 'Thunderstorms', 'easy', 'What three basic environmental ingredients are essential for thunderstorm development?', '["Atmospheric instability, high moisture content, and a lifting mechanism", "High barometric pressure, cold dry air, and strong surface inversions", "Dry adiabatic lapse rates, low humidity, and calm upper winds", "Strong katabatic winds, clear skies, and freezing sea surface temperatures"]'::jsonb, 0, 'The three essential ingredients for any thunderstorm are: 1) sufficient atmospheric instability, 2) abundant moisture in the lower to middle troposphere, and 3) a trigger or lifting mechanism (e.g., surface heating, front, orography, or convergence).', 'I.C. Joshi Aviation Meteorology, Chapter 11 ''Thunderstorms''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-073', 'aviation-meteorology', 'aviation-meteorology-thunderstorms', 'Thunderstorms', 'hard', 'When an aircraft penetrates a microburst during approach, what sequence of airspeed and flight path deviations is experienced?', '["A rapid increase in indicated airspeed (headwind), followed by strong downdraft, and then a sudden drop in indicated airspeed (tailwind) with loss of lift", "A sudden severe drop in airspeed followed by a prolonged ballooning climb", "Constant airspeed with a gradual barometric pressure rise of 10 hPa", "Gradual tailwind increase throughout with no vertical shear"]'::jsonb, 0, 'A microburst produces intense outward-diverging winds near the ground. An aircraft encounters: 1) an initial strong headwind causing airspeed and lift to surge, 2) a severe vertical downdraft, and 3) a sudden transition to a strong tailwind causing airspeed and lift to plunge, driving the aircraft toward the ground.', 'I.C. Joshi Aviation Meteorology, Chapter 11 ''Thunderstorms''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-074', 'aviation-meteorology', 'aviation-meteorology-ice-accretion', 'Ice Accretion', 'easy', 'Clear ice (glaze) forms under which of the following in-flight meteorological conditions?', '["Large supercooled water droplets at temperatures between 0°C and -10°C in cumuliform clouds", "Small supercooled droplets at temperatures below -20°C in stratiform clouds", "Dry ice crystals at temperatures below -40°C in cirrus clouds", "In clear air with relative humidity below 30%"]'::jsonb, 0, 'Clear ice forms when large supercooled water droplets impact an airframe at temperatures near freezing (0°C to -10°C). Due to slow freezing, the droplets spread out before solidifying, forming a smooth, transparent, dense, and tenacious sheet of ice that is extremely difficult to dislodge.', 'I.C. Joshi Aviation Meteorology, Chapter 12 ''Ice Accretion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-075', 'aviation-meteorology', 'aviation-meteorology-ice-accretion', 'Ice Accretion', 'medium', 'Rime ice is typically characterized by:', '["A rough, milky white, opaque, and brittle appearance formed by instantaneous freezing of small supercooled droplets", "A transparent, smooth sheet of heavy ice forming horns on the leading edge", "Liquid water freezing in fuel lines due to high altitude evaporation", "Thin ice needles accumulating only on heated windshields"]'::jsonb, 0, 'Rime ice forms when small supercooled water droplets freeze instantaneously upon contact with the airframe at lower temperatures (-10°C to -20°C), trapping air pockets between frozen droplets, resulting in a brittle, milky-white, opaque structure.', 'I.C. Joshi Aviation Meteorology, Chapter 12 ''Ice Accretion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-076', 'aviation-meteorology', 'aviation-meteorology-ice-accretion', 'Ice Accretion', 'hard', 'Carburettor icing can occur even at outside ambient air temperatures as high as +25°C under what conditions?', '["High relative humidity (above 60-80%) and low throttle settings", "Extremely dry desert air at full throttle cruise", "Sub-zero temperatures with lean mixture settings only", "High altitude flight above FL200 in standard atmosphere"]'::jsonb, 0, 'Fuel vaporization and adiabatic pressure reduction through the carburettor venturi can lower internal temperatures by up to 20°C to 25°C. In humid air (RH > 60-80%), water vapor condenses and freezes onto the throttle valve and throat even when ambient temperature is +20°C to +25°C.', 'I.C. Joshi Aviation Meteorology, Chapter 12 ''Ice Accretion''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-077', 'aviation-meteorology', 'aviation-meteorology-jet-streams', 'Jet Streams', 'easy', 'By international WMO definition, what is the minimum core wind speed required for an upper-level wind stream to be classified as a jet stream?', '["60 knots", "100 knots", "40 knots", "150 knots"]'::jsonb, 0, 'By WMO definition, a jet stream is a strong, narrow current of wind concentrated along a quasi-horizontal axis in the upper troposphere or stratosphere, characterized by vertical and horizontal wind shear and possessing a minimum wind speed of 60 knots (approx 110 km/h).', 'I.C. Joshi Aviation Meteorology, Chapter 14 ''Jet Streams''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-078', 'aviation-meteorology', 'aviation-meteorology-jet-streams', 'Jet Streams', 'hard', 'The Tropical Easterly Jet (TEJ) over peninsular India and the northern Indian Ocean is active during which season and at what typical altitude?', '["Southwest Monsoon season (June to September) around 100-150 hPa (FL450-FL500)", "Winter season (December to February) around 300 hPa (FL300)", "Post-monsoon transition (October) at 500 hPa (FL180)", "Throughout the entire calendar year at FL340"]'::jsonb, 0, 'The Tropical Easterly Jet (TEJ) is a unique seasonal upper-tropospheric jet stream that establishes itself over peninsular India and the Arabian Sea during the Southwest Monsoon (June to September). It flows from east to west at altitudes between FL450 and FL500 (150-100 hPa) with core speeds often exceeding 80-100 knots.', 'I.C. Joshi Aviation Meteorology, Chapter 14 ''Jet Streams''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-079', 'aviation-meteorology', 'aviation-meteorology-air-masses-fronts', 'Air Masses & Fronts', 'easy', 'A cold front is defined as the leading boundary of an advancing:', '["Cold air mass replacing a warmer air mass at the surface", "Warm air mass sliding up over a cold air mass", "Quasi-stationary thermal trough without temperature change", "Occluded upper trough where both fronts have dissipated"]'::jsonb, 0, 'A cold front is the leading edge of a colder, denser air mass that wedges under and displaces a warmer air mass as it advances.', 'I.C. Joshi Aviation Meteorology, Chapter 15 ''Air Masses & Fronts''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-080', 'aviation-meteorology', 'aviation-meteorology-air-masses-fronts', 'Air Masses & Fronts', 'medium', 'As a classic active cold front passes over an airfield, what characteristic surface weather changes occur?', '["Wind veers sharply, temperature drops, barometric pressure rises abruptly, accompanied by gusty showers", "Wind backs, temperature rises, pressure drops steadily, and skies become clear", "Pressure drops to minimum followed by continuous light drizzle and warming", "Wind remains constant in direction while barometric pressure stays unchanged"]'::jsonb, 0, 'With the passage of a Northern Hemisphere cold front: wind veers (shifts clockwise, e.g. SW to NW), temperature drops sharply, atmospheric pressure rises rapidly following the frontal trough line, and heavy showery precipitation or thunderstorms occur.', 'I.C. Joshi Aviation Meteorology, Chapter 15 ''Air Masses & Fronts''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-081', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'easy', 'The onset of the Southwest Monsoon over the southern mainland of India (Kerala coast) typically occurs around:', '["1st of June", "1st of April", "15th of July", "1st of September"]'::jsonb, 0, 'The normal climatological onset date of the Indian Southwest Monsoon over the Kerala coast is 1st of June (with a standard deviation of about 7 days).', 'I.C. Joshi Aviation Meteorology, Chapter 16 ''Climatology of India''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-082', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'medium', 'Western Disturbances that bring vital winter rain and snowfall to Northwest India and the Himalayas originate over:', '["The Mediterranean Sea and Caspian Sea region as extra-tropical wave depressions", "The Bay of Bengal as severe tropical cyclonic storms", "The equatorial Indian Ocean as warm core convective systems", "The Tibetan Plateau as thermal katabatic winds"]'::jsonb, 0, 'Western Disturbances are shallow extra-tropical wave depressions originating over the Mediterranean / Caspian Sea region that travel eastward embedded in the subtropical westerly jet stream, bringing winter precipitation to northern and north-western India.', 'I.C. Joshi Aviation Meteorology, Chapter 16 ''Climatology of India''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-083', 'aviation-meteorology', 'aviation-meteorology-tropical-systems-monsoon', 'Tropical Systems & Monsoon', 'medium', 'In the eye of a mature tropical cyclone, what weather conditions are typically observed?', '["Light winds, subsiding air, little or no cloudiness, and the lowest barometric pressure of the system", "The strongest hurricane-force winds and heaviest torrential rainfall", "Extreme vertical wind shear with continuous severe thunderstorm downbursts", "Rapidly rising barometric pressure with dense overcast nimbostratus"]'::jsonb, 0, 'The eye of a tropical cyclone is a central calm region surrounded by the violent eyewall. It features light descending air, low cloud amounts or partly clear skies, and contains the lowest central pressure of the storm.', 'I.C. Joshi Aviation Meteorology, Chapter 17 ''Tropical Systems & Monsoon''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-084', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'easy', 'In a METAR report, the code group ''CAVOK'' replaces visibility, weather, and cloud groups when which conditions are all simultaneously met?', '["Visibility 10 km or more, no cloud below 5,000 ft or MSA (whichever is higher), no CB/TCU, and no significant weather", "Visibility 5,000 m or more, ceiling above 1,500 ft, and no rain", "Visibility 8 km or more, sky clear, and surface winds below 10 knots", "Airfield is in VFR daylight conditions with no reported icing"]'::jsonb, 0, 'CAVOK (Ceiling And Visibility OK) requires: 1) Visibility 10 km or more; 2) No cloud of operational significance (no cloud below 5,000 ft or minimum sector altitude, whichever is greater, and no CB or TCU at any level); and 3) No significant weather at or near the aerodrome.', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Meteorological Services & Codes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-085', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'medium', 'In a METAR, what does the group ''R27/1200D'' signify?', '["Runway 27 Runway Visual Range is 1,200 metres with a downward (decreasing) trend over the last 10 minutes", "Runway 27 is closed for 1,200 minutes due to fog", "Runway 27 touchdown zone has 12 mm of dry snow", "Runway heading 270° with wind 12 knots gusting during daylight"]'::jsonb, 0, 'In RVR reporting: ''R27'' denotes runway 27; ''1200'' represents 1,200 metres visual range; and the suffix ''D'' indicates a downward (decreasing) trend over the preceding 10-minute period (U = upward, N = no change).', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Meteorological Services & Codes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-086', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'medium', 'In an aerodrome forecast (TAF), what does the change indicator ''BECMG 1416'' indicate?', '["A regular or irregular change expected to commence at 14:00 UTC and be completed by 16:00 UTC", "Temporary fluctuations lasting less than one hour between 14:00 and 16:00 UTC", "A sudden severe weather change occurring exactly at 14:16 UTC", "Weather conditions valid only for 14 hours starting at 16:00 UTC"]'::jsonb, 0, 'BECMG (becoming) indicates a transition where weather conditions are forecast to change at a regular or irregular rate between the start time (14:00 UTC) and the end time (16:00 UTC), after which the new conditions persist.', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Meteorological Services & Codes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-087', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'hard', 'What type of phenomenon warrants the issuance of a SIGMET for en-route aircraft?', '["Severe turbulence, severe icing, volcanic ash, heavy thunderstorm (obscured, embedded, or squall line), and tropical cyclones", "Moderate turbulence at FL050 in VFR conditions", "Light chop and isolated fair weather cumulus clouds", "Routine diurnal wind shifts between land and sea breezes"]'::jsonb, 0, 'SIGMETs are issued by Meteorological Watch Offices (MWOs) to warn pilots of en-route weather phenomena that may affect the safety of all aircraft operations: severe turbulence, severe icing, severe mountain waves, heavy sandstorm, tropical cyclone, volcanic ash, and obscured/embedded/frequent thunderstorms.', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Meteorological Services & Codes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-088', 'aviation-meteorology', 'aviation-meteorology-clear-air-turbulence', 'Clear Air Turbulence', 'hard', 'What is the primary indicator of severe mountain waves (lee waves) to an approaching pilot?', '["Stationary lens-shaped Altocumulus lenticularis clouds over crests and Rotor clouds (Roll clouds) in the turbulent zone beneath the crests", "Dense cirrostratus overcast extending for 500 nautical miles", "Heavy continuous drizzle over the leeward valleys", "Sudden drops in ambient barometric pressure exceeding 50 hPa"]'::jsonb, 0, 'Mountain waves form when stable air flows across a mountain barrier at >20-25 kt perpendicular to the ridge. The principal visual cues are Altocumulus lenticularis (standing lens-shaped clouds) at the crests and dangerous turbulent Rotor (Roll) clouds beneath the wave crests.', 'I.C. Joshi Aviation Meteorology, Chapter 13 ''Mountain Waves''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-089', 'aviation-meteorology', 'aviation-meteorology-temperature-heat', 'Temperature & Heat', 'medium', 'A subsidence inversion is typically formed by:', '["Slowly sinking and adiabatically compressing air within a high-pressure anticyclone", "Nocturnal radiation cooling of the earth surface on a winter night", "Warm air being forced over a cold mountain slope", "Advection of polar air over warm tropical waters"]'::jsonb, 0, 'Subsidence inversions form in anticyclones (high pressure systems) where air gently sinks over a wide area. As it descends, it is adiabatically compressed and heated, becoming warmer than the air layer immediately beneath it.', 'I.C. Joshi Aviation Meteorology, Chapter 3 ''Temperature Inversions''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-090', 'aviation-meteorology', 'aviation-meteorology-winds', 'Winds', 'medium', 'How does the Coriolis force vary with latitude from the Equator to the Poles?', '["Zero at the Equator and reaches maximum magnitude at the Poles", "Maximum at the Equator and decreases to zero at the Poles", "Constant at all latitudes regardless of earth rotation", "Directly proportional to longitude rather than latitude"]'::jsonb, 0, 'Coriolis acceleration is given by 2 * omega * V * sin(latitude). Because sin(0°) = 0, Coriolis force is zero at the Equator, and because sin(90°) = 1, it reaches maximum at the North and South Poles.', 'I.C. Joshi Aviation Meteorology, Chapter 8 ''Winds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-091', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'medium', 'Violent pre-monsoon convective thunderstorms occurring in West Bengal, Bihar, and Assam during April and May are locally termed:', '["Nor''westers (Kalbaishakhi)", "Andhi", "Loo", "Elephantas"]'::jsonb, 0, 'In West Bengal and Bangladesh, severe pre-monsoon thunderstorms originating from the northwest during the hot season (April-May) are known as Nor''westers or Kalbaishakhi. They produce severe squalls, heavy rain, lightning, and hail.', 'I.C. Joshi Aviation Meteorology, Chapter 16 ''Climatology of India''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-092', 'aviation-meteorology', 'aviation-meteorology-climatology-of-india', 'Climatology of India', 'easy', 'The hot, dry, dust-raising summer wind blowing across the plains of northern India during May and June is known as:', '["Loo", "Mistral", "Sirocco", "Pampero"]'::jsonb, 0, 'The ''Loo'' is a strong, gusty, hot, and dry summer wind from the west which blows over the Indo-Gangetic Plain region of North India during May and June, with temperatures often exceeding 45°C.', 'I.C. Joshi Aviation Meteorology, Chapter 16 ''Climatology of India''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('MET-093', 'aviation-meteorology', 'aviation-meteorology-meteorological-services-codes', 'Meteorological Services & Codes', 'easy', 'In a TAF, what probability percentage values are officially permitted by ICAO and DGCA for forecasting weather phenomena?', '["PROB30 and PROB40 only", "PROB10, PROB20, PROB50, and PROB80", "Any probability percentage between 10% and 90%", "PROB25 and PROB75 only"]'::jsonb, 0, 'Under ICAO Annex 3 and DGCA regulations, only PROB30 (30% probability) and PROB40 (40% probability) may be used in TAFs to describe the probability of alternative weather conditions. Conditions with 50% or higher probability are stated using BECMG, TEMPO, or FM.', 'I.C. Joshi Aviation Meteorology, Chapter 18 ''Meteorological Services & Codes''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-036', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'easy', 'The total aerodynamic drag of an aircraft in level unaccelerated flight is the sum of:', '["Parasite drag and induced drag", "Wave drag and skin friction drag only", "Form drag and interference drag only", "Lift-dependent drag and thrust drag"]'::jsonb, 0, 'Total aircraft drag consists of parasite drag (form, skin friction, and interference drag, which increases with the square of speed) and induced drag (vortex drag created as a byproduct of producing lift, which decreases with the square of speed).', 'Oxford ATPL Principles of Flight / AC 65-9A, Chapter ''Aerodynamic Drag''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-037', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'How does induced drag vary with aircraft airspeed in straight-and-level flight?', '["Induced drag is inversely proportional to the square of airspeed (decreases as speed increases)", "Induced drag increases directly with the cube of airspeed", "Induced drag remains constant at all airspeeds", "Induced drag increases linearly with airspeed"]'::jsonb, 0, 'Induced drag is a byproduct of generating lift at angle of attack (Di ∝ CL² / π*AR). At high speeds, CL is low, so induced drag is small. At low speeds near stall, high CL produces strong wingtip vortices, making induced drag highest.', 'Oxford ATPL Principles of Flight / AC 65-9A, Chapter ''Aerodynamic Drag''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-038', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'What is the effect of extending trailing-edge flaps on stall speed and glide angle?', '["Decreases stall speed and steepens the glide approach angle", "Increases stall speed and flattens the glide path", "Decreases stall speed and increases maximum glide distance", "Has no effect on stall speed but reduces parasite drag"]'::jsonb, 0, 'Trailing-edge flaps increase wing camber and surface area, raising the maximum lift coefficient (CLmax). This lowers the stall speed (Vs), while significantly increasing drag, enabling a steeper landing approach without gaining airspeed.', 'Oxford ATPL Principles of Flight / AC 65-9A, Chapter ''High Lift Devices''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-039', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'hard', 'In a coordinated, level, constant-altitude turn at a 60-degree bank angle, what is the load factor (g)?', '["2.0 g", "1.41 g", "3.0 g", "1.15 g"]'::jsonb, 0, 'Load factor n = 1 / cos(bank angle). For 60°: n = 1 / cos(60°) = 1 / 0.5 = 2.0 g. Stall speed in a turn increases by the square root of load factor (√2 ≈ 1.414, or a 41.4% increase in stall speed).', 'Oxford ATPL Principles of Flight / AC 65-9A, Chapter ''Turning Flight & Load Factors''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-040', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'easy', 'What is the primary function of dual independent ignition systems (two spark plugs per cylinder and two magnetos) in aero piston engines?', '["Safety redundancy and improved combustion efficiency", "To allow the engine to run on automotive diesel fuel", "To power the aircraft avionics bus directly", "To prevent carburettor ice accumulation"]'::jsonb, 0, 'Aero piston engines employ two independent magnetos each firing one of two spark plugs per cylinder. This ensures safety redundancy (the engine operates smoothly if one magneto fails) and provides faster, more complete combustion, increasing power output.', 'Oxford ATPL Aircraft General Knowledge / Piston Engines, Chapter ''Ignition Systems''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-041', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'What is engine detonation and what typically causes it?', '["Uncontrolled, instantaneous explosive combustion of the remaining fuel-air charge caused by excessive cylinder head temperature, too low fuel octane, or excessively high manifold pressure", "Ignition of the fuel charge prior to the timed spark discharge due to glowing carbon deposits", "Flame flashing back into the induction intake manifold during starting", "Excessive fuel richness washing lubricating oil off cylinder walls"]'::jsonb, 0, 'Detonation is the spontaneous, explosive combustion of the end-gas ahead of the normal flame front, causing rapid pressure spikes, severe knocking, high cylinder head temperatures, and catastrophic piston damage.', 'Oxford ATPL Aircraft General Knowledge / Piston Engines, Chapter ''Combustion & Fuels''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-042', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'hard', 'What happens to the fuel-air mixture ratio delivered by an uncompensated carburettor as an aircraft climbs to higher altitude?', '["The mixture becomes excessively rich because air density decreases while fuel nozzle metering pressure remains relatively constant", "The mixture becomes excessively lean due to lower ambient temperatures", "The mixture remains exactly stoichiometric automatically", "Fuel flow drops to zero due to fuel tank depressurization"]'::jsonb, 0, 'As altitude increases, air density decreases, meaning less mass of air enters the carburettor for a given volume. Without leaning the mixture control, the carburettor meters fuel based on air velocity, causing the mixture to become progressively richer.', 'Oxford ATPL Aircraft General Knowledge / Piston Engines, Chapter ''Fuel Metering''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-043', 'technical-general', 'technical-general-propellers', 'Propellers', 'easy', 'Why is an aircraft propeller blade twisted along its length from root to tip?', '["To maintain a relatively constant angle of attack along the entire length of the blade despite higher linear velocities near the tip", "To prevent flutter caused by gyroscopic precession", "To ensure equal centrifugal force across the hub", "To direct exhaust fumes away from the cabin intake"]'::jsonb, 0, 'Because the blade tip travels through a much larger circumference than the root, its rotational speed is much higher. Twisting the blade (reducing blade angle toward the tip) maintains a uniform angle of attack and even thrust distribution along the blade.', 'Oxford ATPL Aircraft General Knowledge / Propellers, Chapter ''Propeller Geometry''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-044', 'technical-general', 'technical-general-propellers', 'Propellers', 'medium', 'On a multi-engine aircraft, what does ''feathering'' a propeller achieve after an engine failure?', '["Rotates the propeller blades to an angle approximately 90° into the airflow (edge forward) to minimize aerodynamic drag and stop windmilling", "Locks the propeller into fine pitch for maximum climb thrust", "Reverses blade pitch to provide reverse aerodynamic braking", "Disengages the propeller governor and dumps hydraulic oil into the engine sump"]'::jsonb, 0, 'Feathering rotates the blades until they are edge-on to the relative airflow (pitch angle ~90°). This eliminates windmilling drag, stops engine rotation to prevent further mechanical damage, and dramatically preserves single-engine climb and glide performance.', 'Oxford ATPL Aircraft General Knowledge / Propellers, Chapter ''Multi-Engine Propellers''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-045', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'easy', 'What is the primary function of an accumulator in an aircraft hydraulic system?', '["To store fluid under pressure, absorb hydraulic shock loads, and provide emergency pressure for limited actuator operation", "To cool the hydraulic fluid before it returns to the reservoir", "To convert electrical AC power to direct DC current", "To filter particulate contaminants from the return lines"]'::jsonb, 0, 'An accumulator holds a volume of fluid under compressed gas (nitrogen) pressure. It dampens pump pressure pulsations, assists the pump during peak demand periods, and provides emergency pressure to operate systems (e.g., landing gear or brakes) if the primary pump fails.', 'Oxford ATPL Aircraft General Knowledge / Hydraulic Systems', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-046', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'medium', 'Mineral-based aircraft hydraulic fluid (MIL-H-5606) is dyed which distinctive color?', '["Red", "Blue", "Purple", "Straw yellow"]'::jsonb, 0, 'Mineral-based hydraulic fluid conforming to MIL-PRF-5606 is dyed red for rapid identification and leak detection. Synthetic fluids (like Skydrol) are purple, while vegetable-based fluids are blue.', 'Oxford ATPL Aircraft General Knowledge / Hydraulic Systems', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-047', 'technical-general', 'technical-general-pitot-static-instruments', 'Pitot-Static Instruments', 'medium', 'If the pitot tube ram air intake and its drain hole become completely blocked by ice during flight, how will the Airspeed Indicator (ASI) behave?', '["The ASI will act like an altimeter: overreading during a climb and underreading during a descent", "The ASI will immediately drop to zero and stay at zero", "The ASI will freeze at the cruise airspeed and never change regardless of altitude or pitch", "The ASI will underread during a climb and overread during a descent"]'::jsonb, 0, 'With pitot tube and drain blocked, trapped air pressure in the capsule remains constant. During a climb, ambient static pressure decreases, causing the diaphragm to expand, making the ASI overread (behave like an altimeter). During descent, static pressure rises, making the ASI underread.', 'Oxford ATPL Instrumentation / Pitot-Static Systems', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-048', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'medium', 'What are the two fundamental physical properties that govern the operation of all aircraft mechanical gyroscopic instruments?', '["Rigidity in space (gyroscopic inertia) and Precession", "Coriolis acceleration and centrifugal force", "Magnetic dip and variation", "Pascal''s law and Bernoulli''s theorem"]'::jsonb, 0, 'All gyroscopic flight instruments (Attitude Indicator, Directional Gyro, Turn and Slip Indicator) operate on two fundamental principles: 1) Rigidity in space (rotor remains fixed in plane of rotation), and 2) Precession (force applied manifests 90° ahead in the direction of rotation).', 'Oxford ATPL Instrumentation / Gyroscopes', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-049', 'technical-general', 'technical-general-weight-balance', 'Weight & Balance', 'hard', 'What are the aerodynamic consequences of operating an aircraft with its Center of Gravity (CG) located at the aft limit?', '["Reduced longitudinal stability, lower stall speed, and difficult stall/spin recovery", "Increased longitudinal stability, higher stall speed, and increased control forces", "Higher cruise drag due to increased downward tail load", "Inability to rotate the aircraft during takeoff"]'::jsonb, 0, 'An aft CG reduces the tail moment arm and reduces the downward tail load required for trim. This lowers the aircraft''s effective weight and stall speed, and improves cruise speed. However, longitudinal static stability is severely degraded, control forces are light, and recovery from stalls and spins becomes difficult or impossible.', 'Oxford ATPL Principles of Flight / Weight and Balance', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-050', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'easy', 'Calibrated Airspeed (CAS) is defined as:', '["Indicated Airspeed (IAS) corrected for instrument and position (pressure) errors", "True Airspeed (TAS) corrected for wind drift", "Equivalent Airspeed (EAS) corrected for compressibility effects", "Groundspeed corrected for magnetic track deviation"]'::jsonb, 0, 'Calibrated Airspeed (CAS) is Indicated Airspeed (IAS) corrected for instrument manufacturing tolerances and position/pressure error caused by the placement of the pitot tube and static ports.', 'Oxford ATPL Instrumentation / Airspeed Definitions', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-051', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'medium', 'For a constant Indicated Airspeed (IAS) in standard atmosphere, how does True Airspeed (TAS) change as an aircraft climbs to higher altitude?', '["TAS increases at approximately 1.5% to 2% per 1,000 feet of altitude gain", "TAS decreases because temperature drops", "TAS remains constant because the dynamic pressure is unchanged", "TAS increases by 10% per 1,000 feet up to the tropopause"]'::jsonb, 0, 'Dynamic pressure q = 1/2 * rho * TAS^2 = 1/2 * rho_0 * IAS^2. As altitude increases, air density (rho) decreases; therefore, to produce the same indicated dynamic pressure, TAS must increase (rule of thumb: ~2% per 1,000 ft).', 'Oxford ATPL Principles of Flight / Airspeed Definitions', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-052', 'technical-general', 'technical-general-airspeed-definitions', 'Airspeed Definitions', 'hard', 'Equivalent Airspeed (EAS) is Calibrated Airspeed (CAS) corrected for:', '["Compressibility error of air at high speeds and high altitudes", "Instrument friction and mechanical linkage play", "Altimeter temperature deviation", "Sideslip and rudder deflection angles"]'::jsonb, 0, 'At high speeds (Mach > 0.3) and high altitudes, air compresses ahead of the pitot tube, causing CAS to overread. Correcting CAS for adiabatic compressibility error yields Equivalent Airspeed (EAS).', 'Oxford ATPL Instrumentation / Airspeed Definitions', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-053', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'easy', 'What is the critical (stall) angle of attack of an aerofoil?', '["The angle of attack at which maximum lift coefficient (CLmax) is produced and beyond which airflow separates smoothly", "The pitch attitude of the fuselage relative to the horizon", "The angle between the chord line and the longitudinal datum axis", "The angle of climb during engine failure at takeoff"]'::jsonb, 0, 'The critical angle of attack (stalling angle) is the angle of attack at which the aerofoil generates its maximum lift coefficient (CLmax). Increasing angle of attack beyond this point causes widespread airflow separation and a catastrophic loss of lift, regardless of airspeed, aircraft weight, or bank angle.', 'Oxford ATPL Principles of Flight / Stalling', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-054', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'medium', 'When an aircraft enters ''ground effect'' during landing (within approximately one wingspan of the ground), what aerodynamic changes occur?', '["Induced drag decreases significantly, effective lift increases, and the aircraft tends to float", "Parasite drag increases dramatically and stall speed rises by 20%", "Induced drag increases causing rapid settling onto the runway", "The elevator loses all aerodynamic effectiveness"]'::jsonb, 0, 'Near the ground (within one wingspan), the physical ground restricts the formation of wingtip vortices and downwash. This reduces induced drag substantially, increases effective lift curve slope, and creates a floating tendency.', 'Oxford ATPL Principles of Flight / Ground Effect', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-055', 'technical-general', 'technical-general-principles-of-flight', 'Principles of Flight', 'hard', 'What are the standard control inputs required to recover an aircraft from an intentional or unintentional spin?', '["Throttle to IDLE, Ailerons NEUTRAL, apply FULL OPPOSITE RUDDER, and smoothly ease forward control column to break the stall", "Apply full power and pull back forcefully on the control column", "Apply full in-spin aileron with neutral rudder", "Extend full flaps and maintain full nose-up elevator"]'::jsonb, 0, 'Standard spin recovery (PARE procedure): 1) Power to IDLE; 2) Ailerons NEUTRAL; 3) Rudder FULL OPPOSITE to spin direction; 4) Elevator FORWARD smoothly past neutral to break the wing stall; and once rotation stops, neutralize rudder and recover smoothly from the dive.', 'Oxford ATPL Principles of Flight / Spins & Stalls', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-056', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'easy', 'What is the primary difference between supercharging and turbocharging in aircraft piston engines?', '["A supercharger is mechanically driven directly by the engine crankshaft, whereas a turbocharger is driven by engine exhaust gases", "A supercharger uses exhaust gas while a turbocharger is electric", "A supercharger operates only at sea level while turbochargers work only above 30,000 ft", "Superchargers inject nitrous oxide while turbochargers inject water"]'::jsonb, 0, 'A supercharger is mechanically coupled via gears directly to the engine crankshaft (consuming engine power). A turbocharger uses the otherwise wasted kinetic and thermal energy of exhaust gases passing through a turbine to drive an intake compressor.', 'Oxford ATPL Aircraft General Knowledge / Piston Engines', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-057', 'technical-general', 'technical-general-piston-engines', 'Piston Engines', 'medium', 'What is ''vapour lock'' in an aircraft fuel system?', '["Vaporization of aviation fuel in lines or pumps caused by low ambient pressure, high temperature, or excessive suction, blocking liquid fuel flow", "Condensation of ambient water vapor freezing the fuel filter screen", "Hydraulic lock of engine cylinders caused by unburned avgas during priming", "Locking of the fuel tank filler cap due to negative pressure differential"]'::jsonb, 0, 'Vapour lock occurs when fuel vaporizes prematurely in fuel delivery lines or pumps due to high temperatures, low ambient atmospheric pressure at altitude, or excessive line suction, creating gas bubbles that block liquid fuel delivery to the engine.', 'Oxford ATPL Aircraft General Knowledge / Fuel Systems', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-058', 'technical-general', 'technical-general-aircraft-systems', 'Aircraft Systems', 'medium', 'What is the primary function of a Transformer Rectifier Unit (TRU) in an aircraft electrical system?', '["To step down high-voltage AC electrical power and convert it into DC electrical power", "To convert DC battery power into 115V 400Hz AC power", "To regulate alternator field current during sudden electrical load shedding", "To prevent electrostatic discharge during in-cloud flight"]'::jsonb, 0, 'A Transformer Rectifier Unit (TRU) transforms high-voltage Alternating Current (typically 115V AC) down to a lower voltage and rectifies it into Direct Current (typically 28V DC) to supply DC consumer buses and charge batteries.', 'Oxford ATPL Aircraft General Knowledge / Electrical Systems', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TG-059', 'technical-general', 'technical-general-gyroscopic-instruments', 'Gyroscopic Instruments', 'medium', 'In an aircraft turn coordinator, the gyro gimbal is tilted upward at approximately 30 degrees. This enables the instrument to sense:', '["Both rate of roll and rate of yaw", "Rate of yaw only, without any roll sensitivity", "Rate of pitch and angle of bank only", "Pure magnetic heading changes"]'::jsonb, 0, 'Unlike the older Turn and Slip indicator (horizontal gimbal sensing yaw only), the modern Turn Coordinator has its gyro gimbal tilted up ~30° from the horizontal axis. This allows the gyro to precess in response to both rate of roll and rate of yaw.', 'Oxford ATPL Instrumentation / Gyroscopes', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-026', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'easy', 'What does the abbreviation ''Vs0'' represent in aircraft flight performance?', '["Stalling speed or minimum steady flight speed in the landing configuration", "Stalling speed in the clean (flaps and gear retracted) configuration", "Design maneuvering speed at maximum gross weight", "Maximum speed with flaps fully extended"]'::jsonb, 0, 'Vs0 is the stalling speed or minimum steady flight speed at which the airplane is controllable in the landing configuration (landing gear extended and full flaps). On the Airspeed Indicator, it marks the lower boundary of the white arc.', 'Aircraft Flight Manual / POH Section 1 ''V-speeds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-027', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'easy', 'What does the abbreviation ''Vx'' represent?', '["Speed for best angle of climb (greatest gain of altitude in a given horizontal distance)", "Speed for best rate of climb (greatest gain of altitude in a given time)", "Maximum structural cruising speed", "Design maneuvering speed"]'::jsonb, 0, 'Vx is the best angle-of-climb speed. It delivers the maximum altitude gain over a given horizontal distance forward, making it critical for obstacle clearance after takeoff.', 'Aircraft Flight Manual / POH Section 4 ''Performance & V-speeds''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-028', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'medium', 'Why does design maneuvering speed (Va) decrease as aircraft weight decreases?', '["A lighter aircraft flies at a lower angle of attack for a given airspeed, so a strong gust can induce higher g-loads before the wing stalls to relieve structural strain", "Lighter aircraft experience higher skin friction drag", "The elevator authority increases by the square of weight reduction", "Engine power drops linearly as cargo weight is unloaded"]'::jsonb, 0, 'At lower weights, the wing operates at a lower cruise angle of attack. A sharp vertical gust will produce a larger change in angle of attack and therefore generate higher load factors before reaching the stall angle. Thus, Va must be reduced at lower weights to allow the aircraft to stall before exceeding structural limit load factors.', 'Aircraft Flight Manual / POH Section 2 ''Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-029', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'medium', 'On a multi-engine aircraft, what does the blue radial line on the Airspeed Indicator indicate?', '["Vyse: Best rate-of-climb speed with one engine inoperative", "Vmc: Minimum control speed with critical engine inoperative", "Vne: Never exceed speed in smooth air", "Vfe: Maximum flap extended speed"]'::jsonb, 0, 'On light multi-engine aircraft, the blue radial line on the ASI marks Vyse, which is the best rate-of-climb speed with the critical engine inoperative (single-engine best rate of climb).', 'Multi-Engine Flight Manual / POH Section 1 & 2', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-030', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'easy', 'What airspeed range is represented by the white arc on an aircraft Airspeed Indicator?', '["The full flap operating range, from Vs0 to Vfe", "The normal operating range, from Vs1 to Vno", "The caution range, from Vno to Vne", "The inverted flight operating range"]'::jsonb, 0, 'The white arc represents the flap operating range. The lower limit is the stall speed in landing configuration (Vs0), and the upper limit is the maximum permissible airspeed with flaps extended (Vfe).', 'Aircraft Flight Manual / POH Section 2 ''Airspeed Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-031', 'technical-specific', 'technical-specific-airspeed-indicator-markings', 'Airspeed indicator markings', 'medium', 'Operation in the yellow arc of the Airspeed Indicator is permitted only:', '["In smooth air, and with caution", "During normal climb with flaps fully retracted", "During intentional aerobatics with gear extended", "Only below 10,000 ft in turbulence"]'::jsonb, 0, 'The yellow arc is the caution range (between Vno and Vne). Flights within this airspeed range must be conducted with caution and only in smooth, non-turbulent air to prevent structural damage from gusts.', 'Aircraft Flight Manual / POH Section 2 ''Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-032', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'easy', 'What is the official dyed color of Aviation Gasoline 100LL (Low Lead)?', '["Blue", "Green", "Red", "Clear / Straw"]'::jsonb, 0, 'AVGAS 100LL is dyed blue. Standard AVGAS 100 is green, AVGAS 80/87 is red, and Jet A-1 is clear or light straw-colored.', 'Aircraft Flight Manual / POH Section 2 ''Fuel Specifications''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-033', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'medium', 'When draining a fuel sample during pre-flight inspection, how can water contamination be visually identified in the tester cup?', '["Water is denser than aviation gasoline and collects at the bottom of the tester cup, forming a distinct clear bubble or separation line beneath the blue fuel", "Water floats on top of the fuel as a bright orange layer", "Water turns the entire fuel sample bright purple", "Water immediately evaporates leaving a crystalline salt deposit"]'::jsonb, 0, 'Because water has a higher density (1.0 kg/L) than avgas (~0.72 kg/L), free water quickly settles to the lowest point of the sumps and tester cup, creating a visible separation boundary line or bubble beneath the dyed avgas.', 'Aircraft Flight Manual / POH Section 4 ''Preflight Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-034', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'easy', 'When an aircraft altimeter is set to QFE on the ground at an aerodrome, the altimeter pointers indicate:', '["Zero feet", "The elevation of the aerodrome above sea level", "Pressure altitude relative to the standard 1013.25 hPa datum", "The density altitude of the runway"]'::jsonb, 0, 'QFE is the barometric pressure measured at the aerodrome datum. When set on the subscale while on the runway, the altimeter reads zero feet (height above ground level).', 'Aircraft Flight Manual / ICAO Doc 8168 Altimeter Procedures', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-035', 'technical-specific', 'technical-specific-altimeter-setting-procedures', 'Altimeter setting procedures', 'medium', 'When climbing through the Transition Altitude, what altimeter subscale adjustment must the pilot make?', '["Set the altimeter to the standard pressure setting of 1013.25 hPa (29.92 inHg)", "Set the altimeter to regional minimum QNH", "Set the altimeter to runway QFE", "Leave the altimeter on aerodrome QNH until reaching the cruise descent point"]'::jsonb, 0, 'In accordance with standard ICAO and DGCA procedures, when climbing through the Transition Altitude (TA), altimeters are reset from local QNH to the standard altimeter setting of 1013.25 hPa (Flight Level mode).', 'DGCA CAR Section 9 / ICAO Doc 8168', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-036', 'technical-specific', 'technical-specific-performance-charts', 'Performance charts', 'medium', 'How does an uphill runway slope affect an aircraft''s takeoff run and landing ground roll?', '["Increases the takeoff ground roll distance and decreases the landing ground roll distance", "Decreases both takeoff distance and landing distance", "Increases both takeoff distance and landing distance", "Decreases takeoff distance and increases landing distance"]'::jsonb, 0, 'An uphill runway slope retards aircraft acceleration, requiring a longer takeoff run to achieve rotation speed. On landing, gravity aids deceleration, shortening the landing ground roll.', 'Aircraft Flight Manual / POH Section 5 ''Performance''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-037', 'technical-specific', 'technical-specific-poh-sections', 'POH sections', 'easy', 'In the standard GAMA format Pilot''s Operating Handbook (POH), which section contains Emergency Procedures?', '["Section 3", "Section 2", "Section 4", "Section 5"]'::jsonb, 0, 'In standardized GAMA format POHs: Section 1 is General, Section 2 is Limitations, Section 3 is Emergency Procedures, Section 4 is Normal Procedures, Section 5 is Performance, and Section 6 is Weight & Balance.', 'General Aviation Manufacturers Association (GAMA) Specification No. 1', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-038', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'easy', 'What does the red radial line on an Airspeed Indicator indicate?', '["Vne: Never exceed speed", "Vs0: Stall speed landing configuration", "Vno: Maximum cruising speed", "Vfe: Flap extension speed limit"]'::jsonb, 0, 'The red radial line marks Vne (Never Exceed speed). Flying above Vne risks immediate structural failure or control flutter under any atmospheric conditions.', 'Aircraft Flight Manual / POH Section 2 ''Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-039', 'technical-specific', 'technical-specific-v-speeds-and-their-meanings', 'V-speeds and their meanings', 'hard', 'On a multi-engine aircraft, which engine is defined as the ''critical engine'' on a conventional twin with both propellers rotating clockwise (as viewed from the cockpit)?', '["The left engine, because its failure creates the greatest adverse yaw and roll due to P-factor, accelerated slipstream, and torque", "The right engine, because its exhaust heats the cabin heater exchanger", "Either engine equally because thrust vectors are symmetric", "The engine equipped with the primary hydraulic pump"]'::jsonb, 0, 'On aircraft where both propellers rotate clockwise, the descending blade on the right side of each engine creates thrust further to the right. The right engine thrust vector acts with a much longer arm from the fuselage centerline than the left. Therefore, failure of the LEFT engine induces the greatest yaw and roll, making it the critical engine.', 'Multi-Engine Flying Manual / DGCA Multi-Engine Syllabus', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-040', 'technical-specific', 'technical-specific-fuel-grades-and-colors', 'Fuel grades and colors', 'easy', 'What is the consequence of fueling an aircraft engine rated for 100LL AVGAS with 80/87 octane aviation fuel?', '["Severe risk of detonation, engine overheating, and catastrophic cylinder failure under high power settings", "Engine will fail to start under cold weather conditions", "Fuel will immediately freeze in the carburettor nozzle", "Spark plugs will suffer rapid lead fouling"]'::jsonb, 0, 'Using fuel with a lower octane rating than specified by the engine manufacturer will cause severe detonation (uncontrolled knocking combustion) at high power settings, causing rapid cylinder head overheating, piston erosion, and engine failure.', 'Aircraft Flight Manual / POH Section 2 ''Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-041', 'technical-specific', 'technical-specific-weight-limits', 'Weight limits', 'easy', 'What is the difference between Maximum Ramp Weight and Maximum Takeoff Weight (MTOW)?', '["Maximum Ramp Weight includes the allowance for fuel burned during engine startup, warmup, and taxi to the runway", "Maximum Ramp Weight is the maximum permissible landing weight", "Maximum Ramp Weight is always lower than MTOW due to strut compression", "There is no difference between the two terms"]'::jsonb, 0, 'Maximum Ramp Weight is the structural weight limit for taxiing on the ground. It is greater than Maximum Takeoff Weight by the mass of fuel expected to be consumed during engine start, run-up, and taxi to the active runway.', 'Aircraft Flight Manual / POH Section 2 ''Weight & Limitations''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('TS-042', 'technical-specific', 'technical-specific-poh-sections', 'POH sections', 'easy', 'Which section of a standardized GAMA Pilot''s Operating Handbook contains aircraft operating limitations (airspeeds, engine limits, weight and CG limits)?', '["Section 2", "Section 1", "Section 3", "Section 7"]'::jsonb, 0, 'Section 2 of every standardized GAMA POH is dedicated strictly to ''Limitations''. Compliance with the limits in Section 2 is legally mandatory under Civil Aviation Requirements.', 'GAMA Specification No. 1 / POH Standards', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-026', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'easy', 'What is the exact aviation meaning of the phraseology term ''ROGER'' in radiotelephony?', '["I have received all of your last transmission", "I understand your message and will comply with it", "Permission for proposed action granted", "That is correct"]'::jsonb, 0, 'Under ICAO Doc 9432 and WPC guidelines, ''ROGER'' means strictly: ''I have received all of your last transmission.'' It must NEVER be used to indicate agreement, approval, or compliance (which is ''WILCO'').', 'ICAO Doc 9432 ''Manual of Radiotelephony'' / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-027', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'easy', 'What is the correct radiotelephony term used to mean ''I understand your message and will comply with it''?', '["WILCO", "ROGER", "AFFIRM", "ACKNOWLEDGE"]'::jsonb, 0, '''WILCO'' is the standard radiotelephony abbreviation for ''Will Comply'' and means ''I understand your message and will comply with it.''', 'ICAO Doc 9432 ''Manual of Radiotelephony'' / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-028', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'medium', 'Which radiotelephony phrase must be used to request a station to repeat all, or a specific part, of a message?', '["SAY AGAIN", "REPEAT", "SPEAK ONCE MORE", "OVER"]'::jsonb, 0, 'The phrase ''SAY AGAIN'' is used. The word ''REPEAT'' is prohibited in civil radiotelephony communications because in military firing operations ''repeat'' is an instruction to artillery to fire again.', 'ICAO Doc 9432 ''Manual of Radiotelephony'' / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-029', 'rtr', 'rtr-standard-phraseology', 'Standard phraseology', 'medium', 'What is the correct standard radiotelephony transmission to request a radio check from an ATC station?', '["Delhi Tower, VT-ABC, RADIO CHECK 118.1", "Delhi Tower, VT-ABC, HOW DO YOU HEAR ME?", "Delhi Tower, VT-ABC, READABILITY CHECK PLEASE", "Delhi Tower, VT-ABC, SIGNAL STRENGTH TEST"]'::jsonb, 0, 'The standard ICAO Doc 9432 phraseology for requesting a transmission quality report is: ''[Station callsign], [Aircraft callsign], RADIO CHECK [frequency].''', 'ICAO Doc 9432 ''Manual of Radiotelephony'' / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-030', 'rtr', 'rtr-phonetic-alphabet', 'Phonetic alphabet', 'easy', 'In aeronautical radiotelephony, how is the number ''9'' correctly pronounced?', '["NIN-ER", "NINE", "NO-VE-NA", "NYNE"]'::jsonb, 0, 'To prevent confusion with the German word ''nein'' (no) or the number ''one'' and ''five'', the number 9 is phonetically spoken as ''NIN-ER''.', 'ICAO Doc 9432 / Annex 10 Vol II', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-031', 'rtr', 'rtr-phonetic-alphabet', 'Phonetic alphabet', 'easy', 'How is an altitude of 10,500 feet transmitted in standard radiotelephony?', '["ONE ZERO THOUSAND FIVE HUNDRED FEET", "TEN POINT FIVE THOUSAND", "TEN THOUSAND FIVE HUNDRED FEET", "WUN ZERO FIVE ZERO ZERO FEET"]'::jsonb, 0, 'Under ICAO Annex 10 and Doc 9432 standards, numbers involving thousands are spoken by pronouncing each digit in the number of thousands followed by the word ''THOUSAND'' and then each digit of hundreds followed by ''HUNDRED'': ''ONE ZERO THOUSAND FIVE HUNDRED FEET''.', 'ICAO Doc 9432 ''Manual of Radiotelephony''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-032', 'rtr', 'rtr-readability-scale', 'Readability scale', 'easy', 'In radiotelephony signal reports, what does a readability of ''3'' mean?', '["Readable but with difficulty", "Readable now and then", "Unreadable", "Perfectly readable"]'::jsonb, 0, 'The ICAO Readability Scale is: 1 = Unreadable, 2 = Readable now and then, 3 = Readable but with difficulty, 4 = Readable, 5 = Perfectly readable.', 'ICAO Annex 10 Vol II / ICAO Doc 9432', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-033', 'rtr', 'rtr-readability-scale', 'Readability scale', 'easy', 'If ATC transmits: ''VT-ABC, READ YOU FIVE'', what does this communicate to the pilot?', '["Transmission is perfectly readable", "Transmission is received on frequency band 5", "Transmission has 5 seconds of delay", "Transmission is readable now and then"]'::jsonb, 0, '''Read you 5'' refers to the maximum score on the 1-to-5 readability scale, meaning reception is perfectly clear and readable.', 'ICAO Doc 9432 / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-034', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'easy', 'What is the spoken distress signal indicating that an aircraft is threatened by grave and imminent danger and requests immediate assistance?', '["MAYDAY (spoken three times)", "PAN PAN (spoken three times)", "EMERGENCY (spoken three times)", "SECURITY (spoken three times)"]'::jsonb, 0, 'MAYDAY (derived from French ''m''aider'', help me) spoken three times is the international aeronautical distress signal. It has absolute priority over all other radio communications.', 'ICAO Annex 10 Vol II / ICAO Doc 9432 Chapter 8', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-035', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'easy', 'What is the radiotelephony urgency signal spoken to indicate a condition concerning the safety of an aircraft or person on board, but not requiring immediate assistance?', '["PAN PAN (spoken three times)", "MAYDAY (spoken three times)", "ATTENTION (spoken three times)", "STANDBY EMERGENCY"]'::jsonb, 0, 'PAN PAN (from French ''panne'', breakdown) spoken three times indicates an urgency condition concerning the safety of an aircraft, vehicle, or person, but not requiring immediate assistance.', 'ICAO Annex 10 Vol II / ICAO Doc 9432 Chapter 8', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-036', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'medium', 'What phraseology is transmitted by an aeronautical station to impose radio silence on all stations during an ongoing distress situation?', '["STOP TRANSMITTING, MAYDAY", "SEELONCE MAYDAY", "EMERGENCY SILENCE NOW", "CLEAR THE FREQUENCY"]'::jsonb, 0, 'Under international radiotelephony standards (ICAO Doc 9432), an aircraft or controlling station may impose silence on interference using the words: ''STOP TRANSMITTING, MAYDAY'' or ''SEELONCE MAYDAY''.', 'ICAO Doc 9432 ''Manual of Radiotelephony'' Chapter 8', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-037', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'easy', 'What Secondary Surveillance Radar (SSR) transponder code indicates a general airborne emergency (MAYDAY)?', '["Code 7700", "Code 7600", "Code 7500", "Code 2000"]'::jsonb, 0, 'SSR Mode A Code 7700 is the international emergency code, alerting all ATC radar displays to a state of distress or emergency.', 'ICAO Doc 8168 / DGCA CAR Section 9', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-038', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'easy', 'What SSR transponder code must a pilot squawk upon experiencing total two-way radio communications failure?', '["Code 7600", "Code 7700", "Code 7500", "Code 1200"]'::jsonb, 0, 'SSR Code 7600 signifies radio communication failure (lost communications). Memory aid: ''76 - radio nix''.', 'ICAO Doc 8168 / DGCA CAR Section 9', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-039', 'rtr', 'rtr-transponder-codes', 'Transponder codes', 'easy', 'What SSR transponder code signifies unlawful interference (hijacking)?', '["Code 7500", "Code 7600", "Code 7700", "Code 7000"]'::jsonb, 0, 'SSR Code 7500 notifies ATC covertly of unlawful interference / hijacking. Memory aid: ''75 - taken alive''.', 'ICAO Doc 8168 / DGCA CAR Section 9', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-040', 'rtr', 'rtr-atc-clearances-and-readback', 'ATC clearances and readback', 'medium', 'Which of the following ATC instructions must ALWAYS be read back in full by the flight crew?', '["Runway in use, altimeter settings (QNH), level instructions, heading instructions, and transponder codes", "Weather observations and wind speed reports", "Airport facility operating hours", "Names of surrounding airspace sectors"]'::jsonb, 0, 'ICAO Annex 11 strictly mandates full readback of safety-critical elements: runway in use, clearance to enter/land/takeoff/hold short of any runway, level instructions (altitudes, flight levels), heading and speed instructions, altimeter settings (QNH), and SSR transponder codes.', 'ICAO Annex 11 / Doc 9432 Chapter 2', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-041', 'rtr', 'rtr-frequency-management', 'Frequency management', 'easy', 'What is the internationally designated VHF Aeronautical Emergency Frequency?', '["121.500 MHz", "243.000 MHz", "123.450 MHz", "118.000 MHz"]'::jsonb, 0, '121.500 MHz is the international civil aeronautical emergency frequency guarded continuously by ATC and flight crews.', 'ICAO Annex 10 Vol V / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-042', 'rtr', 'rtr-vhf-propagation-basics', 'VHF propagation basics', 'hard', 'What is the approximate theoretical line-of-sight VHF communication range (in nautical miles) between an aircraft cruising at 10,000 ft and a ground station located at sea level (0 ft)?', '["Approximately 123 NM", "Approximately 60 NM", "Approximately 250 NM", "Approximately 300 NM"]'::jsonb, 0, 'VHF range formula is: Maximum Range (NM) = 1.23 * (√H1 + √H2), where H is height in feet. Range = 1.23 * (√10,000 + √0) = 1.23 * 100 = 123 Nautical Miles.', 'ICAO Doc 9432 / WPC RTR(A) Radio Theory', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-043', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'medium', 'What are the essential contents of an initial MAYDAY distress message in standard radiotelephony?', '["MAYDAY (x3), Aircraft Callsign (x3), Nature of distress condition, Intentions of person in command, Present position, Level/Altitude, and Heading", "MAYDAY, Pilot license number, Total flight hours, and Departure airfield name", "MAYDAY, Fuel onboard in litres and passengers'' names", "MAYDAY, Aircraft registration, Color of fuselage, and Engine serial number"]'::jsonb, 0, 'In accordance with ICAO Doc 9432 Section 8.2: 1) Distress signal ''MAYDAY'' (x3); 2) Name of station addressed; 3) Aircraft identification (x3); 4) Nature of distress; 5) Intentions of commander; 6) Present position, level, and heading; 7) Pilot qualifications / endurance / persons on board.', 'ICAO Doc 9432 Chapter 8 / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-044', 'rtr', 'rtr-distress-and-urgency-calls', 'Distress and urgency calls', 'easy', 'When an aircraft distress situation has terminated and normal radio communication can resume, what phraseology is broadcast?', '["SEELONCE FEENEE", "MAYDAY OVER", "CANCEL EMERGENCY", "RESUME NORMAL TALKING"]'::jsonb, 0, 'Under ICAO Doc 9432, when distress traffic has ceased, the station controlling the frequency broadcasts: ''[Aircraft/Station Callsign], ALL STATIONS, SEELONCE FEENEE'', followed by the time, permitting normal transmissions to resume.', 'ICAO Doc 9432 Chapter 8 / WPC RTR(A)', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-045', 'rtr', 'rtr-atc-clearances-and-readback', 'ATC clearances and readback', 'medium', 'What is the standard phraseology used by a pilot to correct an error made during their own ongoing radiotelephony transmission?', '["CORRECTION, followed by the last correct phrase or word, and then the correct version", "MISTAKE, CANCEL LAST", "DISREGARD LAST SENTENCE", "WRONG, STANDBY"]'::jsonb, 0, 'ICAO Doc 9432 specifies: ''CORRECTION: An error has been made in this transmission (or message indicated). The correct version is...''', 'ICAO Doc 9432 Chapter 2 ''General Operating Procedures''', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-046', 'rtr', 'rtr-atis', 'ATIS', 'easy', 'How are successive Automatic Terminal Information Service (ATIS) airport broadcasts identified by flight crews?', '["By consecutive letters of the ICAO phonetic alphabet (Information Alpha, Information Bravo, Information Charlie, etc.)", "By military Zulu hour codes (e.g. Broadcast 0100, Broadcast 0200)", "By sequential numbers (e.g. ATIS 1, ATIS 2)", "By the duty air traffic controller''s operating initials"]'::jsonb, 0, 'Under ICAO Annex 11, each successive ATIS message is identified by a code letter assigned in alphabetical sequence (Alpha, Bravo, Charlie, etc.), advancing to the next letter with each new broadcast issuance.', 'ICAO Annex 11 / Doc 9432 Chapter 5', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;
INSERT INTO public.questions (id, subject_id, topic_id, topic_name, difficulty, question, options, answer_index, explanation, source, validation_status) VALUES ('RTR-047', 'rtr', 'rtr-lost-communication-procedures', 'Lost communication procedures', 'hard', 'Under ICAO and DGCA regulations, if an IFR aircraft encounters complete two-way radio failure in Instrument Meteorological Conditions (IMC), what level and route must it maintain?', '["Maintain the last assigned level and speed for 20 minutes following failure to report over a compulsory reporting point, then adjust level and speed in accordance with the filed flight plan, adhering strictly to the current flight plan route", "Immediately descend to minimum safe altitude and land at the nearest non-towered airstrip", "Climb immediately to FL410 to ensure line-of-sight radar contact", "Turn 90 degrees right of course and hold until fuel exhaustion"]'::jsonb, 0, 'ICAO Annex 2 Rule 3.6.5.2 mandates that in IMC (or when weather prevents VMC landing), an aircraft with communication failure shall: maintain the last assigned speed and level (or minimum flight altitude if higher) for 20 minutes following the failure to report over a compulsory reporting point, and thereafter adjust level and speed according with the filed flight plan, flying the assigned or filed route to the destination IAF.', 'ICAO Annex 2 ''Rules of the Air'' / DGCA CAR Section 9', 'approved') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer_index = EXCLUDED.answer_index, explanation = EXCLUDED.explanation, source = EXCLUDED.source, validation_status = EXCLUDED.validation_status;